window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0111", [{"word":"fertility","ipa_uk":"/fəˈtɪləti/","ipa_us":"/fəˈtɪləti/","definition_zh":"肥力；生育力；繁殖力；想象力的丰富","definition_en":"the quality of being fertile; ability to produce offspring or crops","core_image":"一张翻耕过的黑色农田在春雨里冒出嫩绿的苗芽","scene":"在春季农耕纪录片里，解说员说：This soil's fertility lets us grow three crops a year without chemical fertilizer.","sceneCN":"这里指「土壤中养分充足、能长出好庄稼的能力」（第1个义项：土壤让作物生长的性质）；句意为这片土壤的肥力让我们不用化肥也能一年三熟。","pos":[{"tag":"n.","zh":"肥力；生育力；繁殖力；想象力的丰富"}],"collocations":[{"phrase":"soil fertility","zh":"土壤肥力"},{"phrase":"fertility rate","zh":"生育率"},{"phrase":"human fertility","zh":"人类生育能力"},{"phrase":"fertility treatment","zh":"生育治疗"},{"phrase":"fertility of mind","zh":"思维的丰富性"},{"phrase":"declining fertility","zh":"下降的肥力/生育率"}],"forms":[{"label":"复数","form":"fertilities"}],"derivatives":[{"word":"fertile","pos":"adj.","zh":"肥沃的；能生育的；想象力丰富的"},{"word":"fertilize","pos":"v.","zh":"使受精；施肥"},{"word":"fertilizer","pos":"n.","zh":"肥料"},{"word":"infertile","pos":"adj.","zh":"不育的；贫瘠的"},{"word":"infertility","pos":"n.","zh":"不育；贫瘠"}],"senses":[{"no":"01","title":"Soil or land that makes plants grow well","titleCN":"土壤的肥沃性","definition":"the quality of soil that allows it to support many strong crops","definitionCN":"土壤能支撑大量茁壮作物生长的性质","example":"Farmers test the field every season to measure its fertility.","exampleCN":"农民每个季节都检测田地以衡量其肥力。","why":"Fertility is the abstract noun of fertile, so it names the property that land has when crops grow easily on it.","whyCN":"fertility 是 fertile 的抽象名词，指的就是土地上作物容易生长的那种性质。"},{"no":"02","title":"Ability of animals or people to have children","titleCN":"人类或动物的生育能力","definition":"the biological capacity to produce offspring","definitionCN":"产生后代的生理能力","example":"Doctors measured his fertility before the marriage.","exampleCN":"医生在他结婚前检查了他的生育能力。","why":"The word carries the same root as fertile land because producing a child is, biologically, a kind of 'growth'.","whyCN":"这个词与 fertile land 共用词根，因为从生物角度看，生育也是一种「生长」。"},{"no":"03","title":"Rate of births in a population","titleCN":"某一人口群体的生育率","definition":"the average number of children born to each woman or couple in a region","definitionCN":"某地区每位女性或每对夫妇平均生育的孩子数量","example":"The fertility rate dropped sharply after the economic crisis.","exampleCN":"经济危机后生育率急剧下降。","why":"Statistics uses fertility as the short form of 'fertility rate', the key number that demographers watch.","whyCN":"统计学家把 fertility 作为 fertility rate 的简称，是人口学家最关注的数字。"},{"no":"04","title":"Medical treatment that helps conception","titleCN":"帮助受孕的医学手段","definition":"procedures or drugs used when a couple has trouble conceiving","definitionCN":"夫妇难以受孕时使用的医疗手段或药物","example":"They tried fertility treatment for three years before a successful pregnancy.","exampleCN":"他们尝试了三年生育治疗才成功怀孕。","why":"Fertility clinics and fertility treatment borrow the noun, focusing on the biological side.","whyCN":"生育诊所与生育治疗借用了这个名词，聚焦在生理层面。"},{"no":"05","title":"Richness of imagination or ideas","titleCN":"想象力的丰富性","definition":"the quality of producing many original ideas","definitionCN":"能够产生大量原创想法的性质","example":"The fertility of his imagination made every lecture feel new.","exampleCN":"他想象力的丰富让每一场讲座都别开生面。","why":"Just as fertile land yields many crops, a fertile mind yields many ideas; this is a common figurative extension.","whyCN":"正如肥沃的土地长出很多庄稼，活跃的头脑产出很多想法，这是一个常见的比喻。"},{"no":"06","title":"Ability of eggs or sperm to function","titleCN":"卵子或精子的存活能力","definition":"how effectively reproductive cells can unite to form a pregnancy","definitionCN":"生殖细胞能够结合并形成怀孕的有效程度","example":"Freezing lowers egg fertility over time.","exampleCN":"冷冻会慢慢降低卵子的受精能力。","why":"In biology, fertility is narrowed down to the viability of gametes, the smallest unit of reproduction.","whyCN":"生物学里 fertility 被收窄到配子存活能力——这是生殖的最小单元。"},{"no":"07","title":"Season or place where growth peaks","titleCN":"生长的高峰时段或地点","definition":"a period or region noted for abundant natural productivity","definitionCN":"以自然生产力充足著称的时段或地区","example":"The annual flooding renews the fertility of the Nile delta.","exampleCN":"一年一度的洪水恢复了尼罗河三角洲的肥沃。","why":"Rivers and flood plains are archetypes of fertility because they bring new soil every year.","whyCN":"河流与冲积平原是 fertility 的原型，因为它们每年带来新的土壤。"},{"no":"08","title":"Figurative richness of a body of work","titleCN":"作品整体的丰富性","definition":"variety and abundance of themes or forms in an artist's output","definitionCN":"艺术家产出中主题或形式的多样与充足","example":"Critics praised the fertility of the composer's late string quartets.","exampleCN":"评论家称赞了这位作曲家晚期弦乐四重奏的丰富主题。","why":"Critics borrow the agricultural metaphor: the artist's output is the 'crop' of their mental soil.","whyCN":"评论家借用农业比喻：艺术家的产出就是他们精神土壤上的「庄稼」。"}],"etymology":{"intro":{"en":"Fertility enters English through French and Latin, keeping the root fert- that once meant 'to bear' and now means 'able to bear'.","cn":"fertility 经由法语和拉丁语进入英语，保留了词根 fert-——它原先的意思是「生」，现在是「能生」。"},"items":[{"era":"LATIN","en":"Latin fertilis meant 'bearing abundantly, fruitful', from the root ferre 'to bear, carry'. The suffix -itas turned it into fertilitas, the abstract noun for that quality.","cn":"拉丁语 fertilis 意为「产得多、果实多」，来自词根 ferre「生、携带」。后缀 -itas 把它变成 fertilitas——这个性质的抽象名词。"},{"era":"OLD FRENCH","en":"Old French fertileté borrowed Latin fertilitas, with the same meaning: the capacity to produce children or crops.","cn":"古法语 fertileté 借入拉丁语 fertilitas，含义相同：生育后代或作物的能力。"},{"era":"MIDDLE ENGLISH","en":"Middle English took fertileté directly from Old French, spelling it fertilitie by the 15th century.","cn":"中古英语直接从古法语借入 fertileté，到 15 世纪拼为 fertilitie。"},{"era":"EARLY MODERN","en":"Spelling settled to fertility in the 16th century, mirroring Latin fertilitas with its -ty abstract suffix.","cn":"16 世纪拼写固定为 fertility，用 -ty 抽象后缀呼应拉丁语 fertilitas。"},{"era":"METAPHORIC SHIFT","en":"By the 17th century, the word shifted from soil and bodies to minds, describing the 'bearing' of ideas and invention.","cn":"到 17 世纪，词义从土壤与身体转移到头脑，描述想法与发明的「产出」。"},{"era":"MODERN STATISTICS","en":"From the 20th century, demographers shortened 'fertility rate' to fertility, giving it a precise numeric sense.","cn":"20 世纪起，人口学家把 fertility rate 简称为 fertility，赋予它一个精确的统计含义。"}]},"similar":{"note":{"en":"Group one holds the same-root fertile family members that share fert-; group two holds near-meaning abstract nouns for abundance.","cn":"第一组是同属 fert- 词根的 fertile 家族；第二组是语义相近的表示「丰富」的抽象名词。"},"groups":[{"heading":"SAME ROOT FAMILY","entries":[{"word":"fertile","ipa":"/ˈfɜːrtaɪl/","tag":"the adjective","definition":"Describes land, bodies or minds that produce much; fertility names the property itself.","definitionCN":"形容词，形容土地、身体或头脑产得多；fertility 命名的正是这个性质本身。"},{"word":"fertilizer","ipa":"/ˈfɜːrrtəlaɪzər/","tag":"noun","definition":"A substance added to soil to make it more fertile, not the quality itself.","definitionCN":"加到土壤里让它更肥沃的物质，不是 fertility 这个性质本身。"},{"word":"infertility","ipa":"/ˌɪnfɜːrˈtɪləti/","tag":"negative noun","definition":"The opposite of fertility: inability to produce offspring or crops.","definitionCN":"fertility 的反义词：无法产生后代或作物。"},{"word":"infertilize","ipa":"/ɪnˈfɜːrtəlaɪz/","tag":"verb","definition":"To make land or a body unable to produce; rare, opposed to fertilize.","definitionCN":"让土地或身体失去生产能力的动词，罕见，与 fertilize 相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fecundity","ipa":"/fɪˈkʌndəti/","tag":"formal noun","definition":"A formal synonym for fertility, used especially for reproductive or metaphorical productivity.","definitionCN":"fertility 的正式同义词，尤用于繁殖或比喻性的产出。"},{"word":"prolificacy","ipa":"/prəˈlɪfɪkəsi/","tag":"quality of being prolific","definition":"The state of producing many works, children or offspring; less biological than fertility.","definitionCN":"产出很多作品、孩子或后代的状态；比 fertility 少生物学含义。"},{"word":"abundance","ipa":"/əˈbʌndəns/","tag":"general","definition":"A large quantity; does not specifically imply the capacity to produce more, only that there is a lot.","definitionCN":"大量存在；不特指生产能力，只说数量多。"},{"word":"luxuriance","ipa":"/lʌɡˈʒʊriəns/","tag":"lush growth","definition":"The quality of growing thickly and richly; used for plants and hair, not people.","definitionCN":"生长繁茂的性质；用于植物和头发，不用于人类。"}]}]},"mnemonics":{"normalIntro":{"en":"fertility circles around the fert- root; link it to both growing plants and growing babies.","cn":"fertility 围绕 fert- 词根；把它同时跟长庄稼和生孩子联系起来。"},"normal":[{"en":"fert- means 'to bear'; fertile land bears crops, fertile bodies bear children, fertility names the property.","cn":"fert- 意为「生」；肥沃的土地生庄稼，能生的身体生孩子，fertility 命名的就是这个性质。"},{"en":"Think of Fertilizer, the substance you add to soil to boost fertility.","cn":"想想 Fertilizer（肥料）——你加到土里提升 fertility 的东西。"},{"en":"Fertility clinics treat people who cannot bear children.","cn":"Fertility 诊所治疗的是生不出孩子的人。"},{"en":"The Nile's annual flood renews its famous fertility.","cn":"尼罗河每年的洪水重新给它那著名的 fertility。"},{"en":"A fertility of ideas comes from a fertile imagination.","cn":"idea 的 fertility 来自 fertile 的想象力。"}],"abstract":[{"en":"Imagine a river delta where fresh mud arrives each year, always growing.","cn":"想象一个每年都有新泥冲刷进来的河流三角洲，永远在生长。"},{"en":"Fertility is a quiet invisible force under soil and under skin.","cn":"fertility 是土壤下和皮肤下一股安静看不见的力。"},{"en":"Numbers on a census page tracking something that declines slowly.","cn":"人口普查表上慢慢下滑的一串数字。"}]},"examples":[{"en":"The fertility of the floodplain keeps feeding a million families downstream.","cn":"冲积平原的肥力持续养活下游一百万户家庭。"},{"en":"Herbalists in the village claim the tea improves fertility.","cn":"村里的草药师说这种茶能提高生育能力。"},{"en":"Demographers expect fertility to rebound after the recession ends.","cn":"人口学家预期衰退结束后生育率会回升。"}],"dict_mnemonic":{"note":"词根记忆","text":"fer- = 生 → fertility = 生的性质","word":"fertility"},"root":"ferre（拉丁语，生、携带）→ fertilis（肥沃的）→ fertilitas → fertility。","sensesIntro":{"en":"Eight senses follow one core image: something that 'bears' — soil bears crops, bodies bear children, minds bear ideas, and statistics bears numbers.","cn":"八个义项围绕一个核心意象：某种「产出」之物——土壤产出庄稼、身体产出孩子、头脑产出想法、统计产出数字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fertile field with dark soil and green sprouts pushing through after rain.","cn":"核心意象：一场雨后，黑土上冒出嫩绿芽尖的肥沃田野。"},"chain":["SOIL BEARS CROPS","BODIES BEAR CHILDREN","STATISTICS BEAR RATES","MEDICINE BEARS HOPE","MINDS BEAR IDEAS","ART BEARS WORKS"],"branches":[{"senses":"01 · 07","en":"AGRICULTURE: soil that grows crops well, and the season or ground where growth peaks.","cn":"农业：能让庄稼长好的土壤，以及生长达到高峰的季节或地块。"},{"senses":"02 · 06","en":"BIOLOGY: the ability to conceive, and the viability of eggs or sperm.","cn":"生物学：受孕的能力，以及卵子或精子的存活能力。"},{"senses":"03","en":"STATISTICS: the birth rate measured across a population.","cn":"统计：在一个人口中测得的出生率。"},{"senses":"04","en":"MEDICINE: the treatment given to help conception.","cn":"医学：为帮助受孕而进行的治疗。"},{"senses":"05 · 08","en":"FIGURATIVE RICHNESS: an abundant imagination, and the richness of a whole body of work.","cn":"比喻性的丰富：丰沛的想象力，以及整部作品的丰厚。"}]},"affixes":{"intro":{"en":"Fertility is formed on the Latin root fert- with an abstract noun suffix -ity; the fertile family also adds -ize, -izer, and -ile.","cn":"fertility 在拉丁词根 fert- 上加抽象名词后缀 -ity 构成；fertile 家族还能加 -ize, -izer, -ile。"},"latinIntro":{"en":"fert- comes from Latin ferre 'to bear, carry', a root that also appears in confer, defer, transfer.","cn":"fert- 来自拉丁语 ferre「生、携带」，这个词根也出现在 confer, defer, transfer 里。"},"items":[{"word":"fertile","structure":"fert- + -ile","meaning":"able to bear; producing much","meaningCN":"能生的；产得多的","example":"fertile farmland","exampleCN":"肥沃的农田"},{"word":"fertilize","structure":"fert- + -ize verb","meaning":"to make fertile; to cause fertilization","meaningCN":"使肥沃；使受精","example":"fertilize the soil","exampleCN":"给土壤施肥"},{"word":"fertilizer","structure":"fertilize + -er","meaning":"substance added to soil to make it fertile","meaningCN":"加到土里让它肥沃的物质","example":"organic fertilizer","exampleCN":"有机肥"},{"word":"fertility","structure":"fertile + -ity abstract","meaning":"the quality of being fertile","meaningCN":"肥沃的性质","example":"test soil fertility","exampleCN":"检测土壤肥力"},{"word":"infertile","structure":"in- + fertile","meaning":"not able to bear offspring or crops","meaningCN":"无法生育或长庄稼的","example":"infertile couple","exampleCN":"不育夫妇"},{"word":"infertility","structure":"infertile + -ity","meaning":"inability to produce offspring","meaningCN":"不育","example":"treat infertility","exampleCN":"治疗不育"},{"word":"fertilization","structure":"fertilize + -ation","meaning":"act of fertilizing; union of sperm and egg","meaningCN":"施肥；受精","example":"in vitro fertilization","exampleCN":"体外受精"},{"word":"unfertile","structure":"un- + fertile","meaning":"not fertile; barren","meaningCN":"不肥沃的；贫瘠的","example":"unfertile land","exampleCN":"贫瘠的土地"},{"word":"fertilizable","structure":"fertilize + -able","meaning":"able to be fertilized","meaningCN":"可受精的；可施肥的","example":"fertilizable eggs","exampleCN":"可受精的卵子"}],"latinEntries":[]}},{"word":"infertile","ipa_uk":"/ɪnˈfɜːrtaɪl/","ipa_us":"/ɪnˈfɜːrrtl/","definition_zh":"不能生育的；贫瘠的；不毛的","definition_en":"not capable of producing offspring or fertile crops","core_image":"一块干裂的褐色田地，寸草不生","scene":"生态片里解说员说：Decades of drought have turned the valley into infertile desert.","sceneCN":"这里指「土地再也长不出庄稼」（第1个义项：贫瘠的、不长庄稼的）；句意为几十年的干旱把山谷变成了不毛的沙漠。","pos":[{"tag":"adj.","zh":"不能生育的；贫瘠的；不毛的"}],"collocations":[{"phrase":"infertile land","zh":"贫瘠的土地"},{"phrase":"infertile couple","zh":"不育夫妇"},{"phrase":"infertile soil","zh":"贫瘠土壤"},{"phrase":"infertile woman/man","zh":"不能生育的女性/男性"},{"phrase":"become infertile","zh":"变得不能生育/贫瘠"},{"phrase":"biologically infertile","zh":"生理上无法生育的"}],"forms":[{"label":"比较级","form":"more infertile"},{"label":"最高级","form":"most infertile"}],"derivatives":[{"word":"fertile","pos":"adj.","zh":"肥沃的；能生育的"},{"word":"infertility","pos":"n.","zh":"不育；贫瘠"},{"word":"infertilely","pos":"adv.","zh":"贫瘠地"},{"word":"fertilize","pos":"v.","zh":"使肥沃；使受精"},{"word":"unfertile","pos":"adj.","zh":"不肥沃的（稍旧）"}],"senses":[{"no":"01","title":"Land unable to grow crops","titleCN":"土地贫瘠，长不出庄稼","definition":"soil that cannot sustain agriculture, lacking water, nutrients or structure","definitionCN":"缺乏水分、养分或结构、无法支撑农业的土壤","example":"Huge stretches of the steppe are now infertile due to overgrazing.","exampleCN":"过度放牧后，草原大片大片变得贫瘠。","why":"The in- prefix reverses fertile: land that once bore crops no longer does.","whyCN":"in- 前缀反转 fertile：曾经长庄稼的土地现在不长了。"},{"no":"02","title":"Person or animal unable to reproduce","titleCN":"人或动物无法生育","definition":"biologically incapable of producing offspring, whether by low sperm count, blocked tubes or other causes","definitionCN":"生理上无法产生后代，原因包括精子少、输卵管堵塞等","example":"The vet warned that the stallion was infertile.","exampleCN":"兽医警告说这匹种马没有生育能力。","why":"The root ferre still carries 'to bear', but now describes bodies that cannot bear children.","whyCN":"词根 ferre 还是「生」，但这次指的是生不了孩子的身体。"},{"no":"03","title":"Egg or sperm that cannot unite","titleCN":"卵子或精子无法结合","definition":"gametes lacking the quality needed to form an embryo","definitionCN":"缺少形成胚胎所需性质的配子","example":"Freezing damaged the semen and made it infertile.","exampleCN":"冷冻损坏了精液，让它无法使卵子受精。","why":"At the micro level, infertility in a single gamete blocks the whole process.","whyCN":"在微观层面，一个配子的不育就能阻断整个生育过程。"},{"no":"04","title":"Figurative: a source that yields nothing","titleCN":"比喻：某个来源不出东西","definition":"used for places or ideas that produce nothing interesting or useful","definitionCN":"用于描述产不出有意思或有用的东西的地方或想法","example":"The idea looked promising but the discussion turned infertile fast.","exampleCN":"这个想法看似有希望，但讨论很快就谈不出东西了。","why":"The agricultural metaphor carries over to minds, conversations and ventures.","whyCN":"农业比喻延伸到了头脑、对话和创业上。"},{"no":"05","title":"Geographical: barren by climate","titleCN":"地理上因气候而贫瘠","definition":"regions with too little rain or the wrong temperature for any vegetation","definitionCN":"因雨水过少或温度不适而无植被的地区","example":"Scientists classify Antarctica as mostly infertile ground.","exampleCN":"科学家把南极大部分归为贫瘠土地。","why":"Climatic factors create infertility without human intervention.","whyCN":"气候因素在没有人为干预的情况下造就了贫瘠。"},{"no":"06","title":"Temporarily unable to conceive","titleCN":"暂时无法受孕","definition":"a person or animal that can recover fertility with treatment or rest","definitionCN":"经治疗或休息后能恢复生育能力的人或动物","example":"The doctor said she was temporarily infertile due to stress.","exampleCN":"医生说她因压力暂时无法受孕。","why":"Temporary infertility is distinct from permanent in fertility clinics.","whyCN":"生育诊所会区分暂时的和永久的不育。"},{"no":"07","title":"Minds producing no new ideas","titleCN":"头脑产不出新想法","definition":"used to describe creativity that has dried up","definitionCN":"形容创造力枯竭的状态","example":"After the third novel, his imagination grew infertile for a decade.","exampleCN":"写完第三本小说后，他的想象力枯竭了十年。","why":"The same agrarian metaphor, now applied to mental produce.","whyCN":"同样的农耕比喻，这次用在脑力产出上。"},{"no":"08","title":"In economics: market with no growth","titleCN":"经济上不增长的市场","definition":"a market or sector where investment yields no new jobs or expansion","definitionCN":"投资带不来新工作或扩张的市场或行业","example":"Austerity left several sectors economically infertile.","exampleCN":"紧缩政策让好几个行业在经济上不再增长。","why":"Economics borrowed the metaphor, turning agricultural productivity into market productivity.","whyCN":"经济学借用了比喻，把农业生产力改成了市场生产力。"}],"etymology":{"intro":{"en":"infertile is simply fertile with the negative in- prefix, making it a transparent antonym that follows the same Latin root.","cn":"infertile 就是 fertile 加否定前缀 in-，是一个透明的反义词，沿同样的拉丁词根。"},"items":[{"era":"LATIN","en":"Latin fertilis 'bearing abundantly' was itself not negated in classical Latin; the negation entered English later.","cn":"古典拉丁语没有 negated fertilis，否定是后来进入英语的。"},{"era":"MIDDLE ENGLISH","en":"Middle English fertile was spelled fertil, and writers began using the in- prefix to form infertil in the 14th century.","cn":"中古英语 fertile 拼为 fertil，14 世纪开始有人用 in- 前缀造 infertil。"},{"era":"EARLY MODERN","en":"Spelling settled to infertile by the 16th century, parallel to fertile.","cn":"到 16 世纪拼写固定为 infertile，与 fertile 平行。"},{"era":"SEMANTIC EXPANSION","en":"Originally applied only to land, the word broadened to bodies and minds by the 17th century.","cn":"原本只用于土地，17 世纪扩展到身体和头脑。"},{"era":"MEDICAL USE","en":"By the 19th century, doctors used infertile specifically for couples unable to conceive.","cn":"到 19 世纪，医生把 infertile 特指为无法怀孕的夫妇。"},{"era":"CURRENT","en":"Today it covers soil, bodies, gametes, minds and markets.","cn":"今天覆盖土壤、身体、配子、头脑和市场。"}]},"similar":{"note":{"en":"Group one is the fertile family with negation; group two contains formal synonyms for 'unable to produce'.","cn":"第一组是 fertile 家族的否定形式；第二组是正式的、表示「无法产出」的同义词。"},"groups":[{"heading":"NEGATED FERTILE FAMILY","entries":[{"word":"fertile","ipa":"/ˈfɜːrtaɪl/","tag":"antonym","definition":"The opposite of infertile: able to produce.","definitionCN":"infertile 的反义词：能产出的。"},{"word":"infertility","ipa":"/ˌɪnfɜːrˈtɪləti/","tag":"noun","definition":"The state of being infertile, especially of a couple or land.","definitionCN":"不育、贫瘠的状态，尤指夫妇或土地。"},{"word":"unfertile","ipa":"/ʌnˈfɜːrtaɪl/","tag":"same meaning","definition":"A less common synonym for infertile; both use negative prefixes.","definitionCN":"infertile 较不常见的同义词；二者都用否定前缀。"},{"word":"non-fertile","ipa":"/nɒn ˈfɜːrtaɪl/","tag":"technical","definition":"A technical variant, usually for specific biological contexts.","definitionCN":"技术变体，通常用于特定生物语境。"}]},{"heading":"NEAR MEANING","entries":[{"word":"barren","ipa":"/ˈbærən/","tag":"land or woman","definition":"Formal for land unable to grow crops or a woman unable to bear children.","definitionCN":"正式，指长不出庄稼的土地或无法生育的女性。"},{"word":"sterile","ipa":"/ˈsterəl/","tag":"technical","definition":"Scientific term for an organism that cannot reproduce; also means 'free of germs'.","definitionCN":"科学术语，指无法繁殖的生物；也指「无菌的」。"},{"word":"impotent","ipa":"/ˈɪmpətənt/","tag":"male only","definition":"Historically used for a man unable to have sexual intercourse leading to conception; now avoided.","definitionCN":"历史上用于指无法性交导致不育的男性；现在慎用。"},{"word":"arid","ipa":"/ˈærɪd/","tag":"land","definition":"Dry land that cannot support much vegetation; narrower than infertile.","definitionCN":"无法支撑植被的干燥土地；范围比 infertile 窄。"}]}]},"mnemonics":{"normalIntro":{"en":"in- reverses fertile, so infertile = not fertile.","cn":"in- 把 fertile 反过来，所以 infertile = 不 fertile。"},"normal":[{"en":"in- = not; fertile = able to produce → infertile = unable to produce.","cn":"in- = 不；fertile = 能产出 → infertile = 不能产出。"},{"en":"An infertile field is a field no farmer wants.","cn":"infertile 的田地没有农民想要。"},{"en":"An infertile couple visits a fertility clinic.","cn":"infertile 的夫妇去 fertility 诊所。"},{"en":"Even the best doctor sometimes cannot reverse infertility.","cn":"就算最好的医生有时也扭转不了 infertility。"},{"en":"In science fiction, an infertile earth leads to human extinction.","cn":"科幻里一个 infertile 的地球会导致人类灭绝。"}],"abstract":[{"en":"Cracked earth, dust, no green anywhere you look.","cn":"裂土、尘土、哪里都没有绿色。"},{"en":"A small empty room at the back of a hospital corridor.","cn":"医院走廊尽头一间小小的空房间。"},{"en":"A seed that falls on stone and never sprouts.","cn":"落在石头上永远不发芽的种子。"}]},"examples":[{"en":"Deforestation left large patches of once-fertile valley infertile.","cn":"森林砍伐让曾经肥沃的大片山谷变贫瘠了。"},{"en":"After two years of trying, the couple learned they were infertile.","cn":"两年努力后，这对夫妇得知他们无法生育。"},{"en":"The frozen tundra is economically infertile, but home to unique wildlife.","cn":"冻原在经济上贫瘠，却是独特野生动物的家。"}],"dict_mnemonic":{"note":"否定前缀","text":"in- + fertile = 不肥沃的、不能生育的","word":"infertile"},"root":"同 fertile（ferre），加否定前缀 in- 构成反义词。","sensesIntro":{"en":"Eight senses describe what cannot be born or grown: land cannot bear crops, bodies cannot bear children, minds cannot bear ideas, markets cannot bear growth.","cn":"八个义项讲的都是「生不出」：土地生不出庄稼、身体生不出孩子、头脑生不出想法、市场生不出增长。"},"semanticMap":{"core":{"en":"CORE IMAGE: a field of cracked earth after three years of drought, no green shoots anywhere.","cn":"核心意象：大旱三年后的裂土，哪里都没有嫩芽。"},"chain":["LAND CANNOT GROW","BODIES CANNOT BEAR","GAMETES CANNOT UNITE","CONVERSATIONS YIELD NOTHING","MINDS PRODUCE NO IDEAS","MARKETS SHOW NO GROWTH"],"branches":[{"senses":"01 · 05","en":"LAND AND CLIMATE: ground that bears no crop, whether the limit comes from soil or from weather.","cn":"土地与气候：不管是土质还是天气造成的限制，地都长不出庄稼。"},{"senses":"02 · 06","en":"BODIES: a permanent or temporary loss of the ability to conceive, as diagnosed in medicine.","cn":"身体：医学诊断出的永久或暂时丧失受孕能力。"},{"senses":"03","en":"GAMETES: a single egg or sperm that lacks what it takes to form an embryo.","cn":"配子：单个卵子或精子缺少形成胚胎所需的条件。"},{"senses":"04 · 07","en":"FIGURATIVE / MIND: sources, conversations and imaginations that produce nothing new.","cn":"比喻 / 心智：产不出新东西的来源、对话与想象力。"},{"senses":"08","en":"ECONOMICS: a market or sector where investment brings no growth.","cn":"经济：投资带不来增长的市场或行业。"}]},"affixes":{"intro":{"en":"infertile simply adds the negative prefix in- to fertile, so its morphology is transparent.","cn":"infertile 就是 fertile 加否定前缀 in-，形态完全透明。"},"latinIntro":{"en":"The root fert- is from Latin ferre 'to bear, carry'; in- is a common Latin negative prefix.","cn":"词根 fert- 来自拉丁语 ferre「生、携带」；in- 是常见的拉丁否定前缀。"},"items":[{"word":"fertile","structure":"fert- + -ile","meaning":"able to bear","meaningCN":"能生的","example":"fertile land","exampleCN":"肥沃的土地"},{"word":"infertile","structure":"in- + fertile","meaning":"not fertile","meaningCN":"不能生育的；贫瘠的","example":"infertile couple","exampleCN":"不育夫妇"},{"word":"infertility","structure":"infertile + -ity","meaning":"state of being infertile","meaningCN":"不育；贫瘠","example":"treat infertility","exampleCN":"治疗不育"},{"word":"unfertile","structure":"un- + fertile","meaning":"not fertile (older)","meaningCN":"不肥沃的（较旧）","example":"unfertile soil","exampleCN":"贫瘠土壤"},{"word":"fertilize","structure":"fert- + -ize","meaning":"to make fertile","meaningCN":"使肥沃","example":"fertilize the field","exampleCN":"给田地施肥"},{"word":"fertilizer","structure":"fertilize + -er","meaning":"substance to fertilize","meaningCN":"肥料","example":"chemical fertilizer","exampleCN":"化肥"},{"word":"fertilization","structure":"fertilize + -ation","meaning":"act of fertilizing","meaningCN":"施肥；受精","example":"in vitro fertilization","exampleCN":"体外受精"},{"word":"infertilely","structure":"infertile + -ly","meaning":"in an infertile way","meaningCN":"贫瘠地","example":"the land lay infertilely","exampleCN":"土地荒芜"},{"word":"nonfertile","structure":"non- + fertile","meaning":"not fertile (technical)","meaningCN":"不肥沃的（技术）","example":"nonfertile sand","exampleCN":"无养分的沙子"}],"latinEntries":[]}},{"word":"soil erosion","ipa_uk":"/sɔɪl ɪˈrəʊʒn/","ipa_us":"/sɔɪl ɪˈroʊʒn/","definition_zh":"土壤侵蚀","definition_en":"the wearing away of topsoil by natural forces or human activity","core_image":"斜坡上被雨水冲出一道道沟壑的裸露山坡，树根裸露","scene":"地理课纪录片里解说员说：After the forest was cleared, soil erosion turned the hillside into gullies within a decade.","sceneCN":"这里指「雨水冲走了山坡上的表层土壤」（第1个义项：自然力或人类活动把表层土带走）；句意为森林砍伐后，土壤侵蚀十年内把山坡冲出一条条沟。","pos":[{"tag":"n.","zh":"土壤侵蚀（不可数）"}],"collocations":[{"phrase":"prevent soil erosion","zh":"防止土壤侵蚀"},{"phrase":"reduce soil erosion","zh":"减少土壤侵蚀"},{"phrase":"accelerate soil erosion","zh":"加速土壤侵蚀"},{"phrase":"natural soil erosion","zh":"自然土壤侵蚀"},{"phrase":"wind-driven soil erosion","zh":"风力土壤侵蚀"},{"phrase":"soil erosion by water","zh":"水流造成的土壤侵蚀"}],"forms":[{"label":"不可数名词","form":"无复数"}],"derivatives":[{"word":"erode","pos":"v.","zh":"侵蚀、腐蚀"},{"word":"erosion","pos":"n.","zh":"侵蚀、腐蚀"},{"word":"erosive","pos":"adj.","zh":"有侵蚀性的"},{"word":"eruption","pos":"n.","zh":"火山爆发（近音但不同源）"},{"word":"erode away","pos":"phrasal v.","zh":"渐渐侵蚀掉"}],"senses":[{"no":"01","title":"Topsoil washed away by water","titleCN":"表层土被水流冲走","definition":"the most common form, where rain or river flow carries topsoil downhill into streams or oceans","definitionCN":"最常见的形式，雨水或河流把表层土带下山，流入小溪或海洋","example":"Heavy monsoon rains caused severe soil erosion in the rice fields.","exampleCN":"雨季的暴雨让稻田发生严重的土壤侵蚀。","why":"Water is the number one agent of soil erosion because it has weight and flows downhill.","whyCN":"水流是土壤侵蚀第一推手，因为它有重量且往低处流。"},{"no":"02","title":"Topsoil blown away by wind","titleCN":"表层土被风吹走","definition":"happens in dry regions where vegetation has been removed, turning fields into dust bowls","definitionCN":"发生在干旱区、植被被清除后，把农田变成尘土碗","example":"The Great Dust Bowl of the 1930s was mostly wind-driven soil erosion.","exampleCN":"1930 年代美国大沙尘暴主要是风力造成的土壤侵蚀。","why":"Wind can move fine soil particles when they are dry and unprotected.","whyCN":"干燥又没保护的细土颗粒风能吹走。"},{"no":"03","title":"Caused by human farming practices","titleCN":"由农耕方式引起","definition":"plowing too close to slopes, leaving fields bare over winter, or planting the same crop every year","definitionCN":"紧贴山坡耕作、冬季让田地裸露、年年种同一种作物","example":"Conventional farming without cover crops speeds up soil erosion.","exampleCN":"不种覆盖作物的常规耕作加速土壤侵蚀。","why":"Tilling removes the protective layer that roots and plant litter normally provide.","whyCN":"翻土破坏了根系和落叶提供的保护层。"},{"no":"04","title":"Caused by construction or mining","titleCN":"由建设或采矿引起","definition":"stripping vegetation from large areas for roads, buildings or mines exposes bare soil to rain and wind","definitionCN":"为修路、建房或采矿大面积剥离植被，让裸土暴露给风雨","example":"The highway project caused significant soil erosion on nearby hillsides.","exampleCN":"这条公路工程让附近山坡出现显著的土壤侵蚀。","why":"Construction removes vegetation in a single step, creating large bare patches at once.","whyCN":"建设在一步之内清除植被，瞬间制造大片裸土。"},{"no":"05","title":"Natural slow erosion over centuries","titleCN":"自然缓慢侵蚀","definition":"erosion that happens without human help, as glaciers retreat or rivers meander","definitionCN":"没有人为干预时发生的侵蚀，如冰川后退或河流改道","example":"Natural soil erosion shaped the Grand Canyon over millions of years.","exampleCN":"自然的土壤侵蚀在几百万年间塑成了大峡谷。","why":"Geologists see soil erosion as part of a slow natural cycle rather than a disaster.","whyCN":"地质学家把土壤侵蚀视为慢自然循环的一部分而非灾难。"},{"no":"06","title":"Social or economic analogy","titleCN":"社会/经济比喻","definition":"the slow loss of something valuable over time","definitionCN":"有价值的东西随时间慢慢流失","example":"Cultural soil erosion has been accelerated by mass media.","exampleCN":"大众传媒加速了文化根基的流失。","why":"Erosion is a powerful metaphor because it describes a gradual, invisible process.","whyCN":"侵蚀是强有力的比喻，因为它描述的是一个缓慢、看不见的过程。"},{"no":"07","title":"Coastal soil erosion","titleCN":"海岸土壤侵蚀","definition":"waves and tides carrying away sand and cliffs along shorelines","definitionCN":"海浪和潮汐带走岸边的沙子和悬崖","example":"Coastal soil erosion has forced three villages to relocate in the past decade.","exampleCN":"过去十年，海岸土壤侵蚀迫使三个村庄搬迁。","why":"Coastal erosion is driven by a different agent (waves) but produces the same kind of loss.","whyCN":"海岸侵蚀的动力是海浪，但后果同样是土壤流失。"},{"no":"08","title":"Prevention and conservation","titleCN":"防止与保护","definition":"methods to stop or reduce soil loss, including terraces, cover crops, and windbreaks","definitionCN":"防止或减少土壤流失的方法，包括梯田、覆盖作物、防风林","example":"Farmers in the Andes have used terraces to fight soil erosion for centuries.","exampleCN":"安第斯山的农民用梯田抵御土壤侵蚀已有数百年。","why":"Because erosion is natural, prevention works by keeping soil in place rather than stopping the forces.","whyCN":"因为侵蚀是自然的，防治靠的是把土留住，不是消灭风雨。"}],"etymology":{"intro":{"en":"erosion comes from Latin erodere, which itself breaks into e- (out) + rodere (to gnaw); soil erosion is a compound noun meaning 'the gnawing away of soil'.","cn":"erosion 来自拉丁语 erodere，拆成 e-（出去）+ rodere（啃）；soil erosion 是复合名词，意为「土壤被啃掉」。"},"items":[{"era":"LATIN","en":"erodere = e- (out) + rodere (to gnaw) → to gnaw out, to wear away. Past participle eresus yielded erosio, the noun for the result.","cn":"erodere = e-（出）+ rodere（啃）→ 啃出来、磨掉。过去分词 eresus 给出 erosio 这个名词。"},{"era":"FRENCH","en":"Old French borrowed erosio as érosion, keeping the meaning of 'a wearing away'.","cn":"古法语借入 erosio 为 érosion，意思是「磨掉的过程」。"},{"era":"ENGLISH (17TH C)","en":"English erosion appeared in the mid-17th century, first in geology, borrowed directly from Latin.","cn":"17 世纪中期英语出现 erosion，最早用于地质学，直接从拉丁语借入。"},{"era":"COMPOUND","en":"The phrase soil erosion started being used in the 19th century as soil conservation science emerged.","cn":"soil erosion 这个短语在 19 世纪土壤保护科学兴起时开始使用。"},{"era":"20TH C CONSERVATION","en":"The Dust Bowl of the 1930s made soil erosion a household phrase in the United States.","cn":"1930 年代的大沙尘暴让 soil erosion 在美国家喻户晓。"},{"era":"TODAY","en":"The term is central to agriculture, geography, environmental science and policy.","cn":"这个术语是农业、地理、环境科学和政策的核心词。"}]},"similar":{"note":{"en":"Group one is the erosion family of rodere root; group two lists related environmental processes.","cn":"第一组是 rodere 词根下的 erosion 家族；第二组是相关的环境过程。"},"groups":[{"heading":"SAME ROOT","entries":[{"word":"erode","ipa":"/ɪˈroʊd/","tag":"verb","definition":"To wear away gradually, as water erodes rock over time.","definitionCN":"渐渐磨掉，如水慢慢侵蚀岩石。"},{"word":"erosion","ipa":"/ɪˈroʊʒn/","tag":"noun","definition":"The general process of wearing away, not only of soil.","definitionCN":"泛指「磨掉」的过程，不限于土壤。"},{"word":"erosive","ipa":"/ɪˈroʊsɪv/","tag":"adjective","definition":"Having the power to erode; used for water, wind, acid.","definitionCN":"有侵蚀能力的；用于水、风、酸。"},{"word":"eruption","ipa":"/ɪˈrʌpʃn/","tag":"near-sound different root","definition":"Volcanic eruption comes from erumpere (to burst out), not rodere.","definitionCN":"火山爆发来自 erumpere（迸发），与 rodere 不同源。"}]},{"heading":"RELATED PROCESSES","entries":[{"word":"weathering","ipa":"/ˈweðərɪŋ/","tag":"geology","definition":"Breaking down rock in place; differs from erosion which carries material away.","definitionCN":"岩石在原地碎裂；区别于 erosion——后者把碎粒搬走。"},{"word":"sedimentation","ipa":"/ˌsedɪmenˈteɪʃn/","tag":"related process","definition":"The opposite end of erosion: eroded material is deposited somewhere.","definitionCN":"erosion 的另一端：被侵蚀的物质被沉积到别处。"},{"word":"deforestation","ipa":"/ˌdiːˌfɒrɪˈsteɪʃn/","tag":"cause","definition":"Removing forests; one of the main human causes of soil erosion.","definitionCN":"砍伐森林；人类造成土壤侵蚀的主要原因之一。"},{"word":"desertification","ipa":"/dɪˌzɜːrtɪfɪˈkeɪʃn/","tag":"consequence","definition":"Land turning to desert, often through erosion and overgrazing.","definitionCN":"土地变成沙漠，常由侵蚀和过度放牧导致。"}]}]},"mnemonics":{"normalIntro":{"en":"Soil erosion is soil being 'gnawed away' by water or wind.","cn":"soil erosion 就是土壤被水或风「啃掉」。"},"normal":[{"en":"Erode = gnaw away; erosion = the gnawing; soil erosion = gnawing of soil.","cn":"Erode = 啃掉；erosion = 啃的过程；soil erosion = 啃土壤。"},{"en":"Remember the Dust Bowl: wind took the topsoil away.","cn":"记得大沙尘暴：风把表层土刮走了。"},{"en":"Farmers fight soil erosion with terraces on hills.","cn":"农民用山上的梯田对抗 soil erosion。"},{"en":"Roots hold soil; when trees are cut, erosion wins.","cn":"树根把土抓住；树被砍了，erosion 就赢了。"},{"en":"Grand Canyon is millions of years of soil and rock erosion.","cn":"大峡谷是几百万年土壤和岩石的 erosion。"}],"abstract":[{"en":"A hillside of dirt that slowly melts into a stream after every rain.","cn":"每下一次雨就慢慢融进小溪的一个泥坡。"},{"en":"Teeth marks of wind and water across green farmland.","cn":"风和水在绿色农田上留下的牙印。"},{"en":"A painting that slowly fades where the canvas is exposed to sun.","cn":"帆布向阳处慢慢褪色的一幅画。"}]},"examples":[{"en":"The EU has spent billions on terraces and windbreaks to fight soil erosion in the Mediterranean.","cn":"欧盟在地中海花了几十亿修梯田和防风林对抗土壤侵蚀。"},{"en":"Satellite photos show that soil erosion is accelerating on deforested hillsides.","cn":"卫星照片显示被砍伐的山坡上土壤侵蚀在加速。"},{"en":"Local farmers plant cover crops each winter to prevent soil erosion.","cn":"当地农民每年冬天种覆盖作物防止土壤侵蚀。"}],"dict_mnemonic":{"note":"词根记忆","text":"e-（出）+ rodere（啃）= 啃出去 = 侵蚀","word":"erosion"},"root":"rodere（拉丁语，啃、咬）→ erodere（e- + rodere = 啃掉）→ eresus → erosio → erosion。","sensesIntro":{"en":"Eight senses describe who or what does the gnawing: water, wind, farming, construction, nature, waves, and prevention.","cn":"八个义项讲「谁」在啃：水、风、农耕、建设、自然、海浪，以及与之对抗的防治。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hillside after heavy rain, with gullies where water stripped the topsoil.","cn":"核心意象：大雨后的山坡，雨水冲出沟壑带走表层土。"},"chain":["WATER WASHES SOIL","WIND BLOWS SOIL","FARMING REMOVES ROOTS","CONSTRUCTION STRIPS LAND","NATURE ERODES SLOWLY","PEOPLE FIGHT EROSION"],"branches":[{"senses":"01 · 02 · 07","en":"AGENTS OF NATURE: WATER / WIND / WAVES","cn":"自然动力：水 / 风 / 浪"},{"senses":"03 · 04","en":"HUMAN CAUSES","cn":"人为原因"},{"senses":"05","en":"NATURAL GEOMORPHIC","cn":"自然地貌演化"},{"senses":"06","en":"METAPHORICAL LOSS","cn":"比喻性流失"},{"senses":"08","en":"PREVENTION","cn":"防治"}]},"affixes":{"intro":{"en":"erosion is derived from Latin rodere 'to gnaw'; the soil compound adds the noun modifier soil.","cn":"erosion 来自拉丁语 rodere「啃」；soil 这个复合名词前面加了修饰语 soil。"},"latinIntro":{"en":"rodere gives English rodent (gnawing animal), erode, corrosion. The soil part is plain English.","cn":"rodere 给出 rodent（啃咬动物）、erode、corrosion。soil 是英语本族词。"},"items":[{"word":"erode","structure":"e- + rodere","meaning":"to wear away","meaningCN":"侵蚀","example":"waves erode the cliff","exampleCN":"海浪侵蚀悬崖"},{"word":"erosion","structure":"erodere past participle + -ion","meaning":"a wearing away","meaningCN":"侵蚀","example":"soil erosion","exampleCN":"土壤侵蚀"},{"word":"erosive","structure":"eros- + -ive","meaning":"causing erosion","meaningCN":"有侵蚀性的","example":"erosive acid","exampleCN":"有腐蚀性的酸"},{"word":"corrode","structure":"com- + rodere","meaning":"to eat into by degrees","meaningCN":"腐蚀","example":"acid corrodes metal","exampleCN":"酸腐蚀金属"},{"word":"corrosion","structure":"corrode + -ion","meaning":"the process of corroding","meaningCN":"腐蚀","example":"rust is corrosion","exampleCN":"铁锈就是腐蚀"},{"word":"rodent","structure":"rod- + -ent","meaning":"gnawing mammal","meaningCN":"啮齿动物","example":"rats are rodents","exampleCN":"老鼠是啮齿动物"},{"word":"soil","structure":"Old English soil (noun)","meaning":"top layer of earth","meaningCN":"土壤","example":"test the soil","exampleCN":"检验土壤"},{"word":"gnaw","structure":"Germanic root (nawjan)","meaning":"to bite persistently","meaningCN":"啃","example":"rodents gnaw wood","exampleCN":"啮齿类啃木头"},{"word":"erupt","structure":"e- + rumpere","meaning":"to burst out","meaningCN":"迸发","example":"volcano erupts","exampleCN":"火山喷发"}],"latinEntries":[]}},{"word":"alluvial","ipa_uk":"/əˈluːviəl/","ipa_us":"/əˈluːviəl/","definition_zh":"冲积的；冲积土的","definition_en":"relating to sediment deposited by flowing water, especially at the mouth of a river","core_image":"河流入海口扇形展开的冲积平原，远处是茂密的芦苇和稻田","scene":"纪录片里解说员说：The Ganges delta is one of the largest alluvial plains on earth.","sceneCN":"这里指「由河水带来的泥沙堆积而成的平原」（第1个义项：冲积沉积物的）；句意为恒河三角洲是地球上最大的冲积平原之一。","pos":[{"tag":"adj.","zh":"冲积的；与冲积物有关的"}],"collocations":[{"phrase":"alluvial soil","zh":"冲积土壤"},{"phrase":"alluvial plain","zh":"冲积平原"},{"phrase":"alluvial deposit","zh":"冲积沉积物"},{"phrase":"alluvial fan","zh":"冲积扇"},{"phrase":"alluvial gold","zh":"冲积金矿（砂金）"},{"phrase":"alluvial valley","zh":"冲积河谷"}],"forms":[{"label":"副词","form":"alluvially"}],"derivatives":[{"word":"alluvium","pos":"n.","zh":"冲积物、淤积物（单数）"},{"word":"alluvia","pos":"n.","zh":"冲积物（alluvium 的复数）"},{"word":"alluvion","pos":"n.","zh":"洪水；冲积作用（较旧）"},{"word":"deluvian","pos":"adj.","zh":"洪水的、大洪水的"},{"word":"fluvial","pos":"adj.","zh":"河流的（近义）"}],"senses":[{"no":"01","title":"Pertaining to sediment laid down by rivers","titleCN":"与河流淤积的沉积物有关的","definition":"describes material carried and deposited by flowing water, not by wind or ice","definitionCN":"描述被水流搬运并沉积的物质，不包括风或冰","example":"Alluvial soils are among the most fertile for farming.","exampleCN":"冲积土壤是最肥沃的农田土壤。","why":"The root lav- means 'to wash', and a river washes sediment downstream before dropping it.","whyCN":"词根 lav- 意为「洗」，河流把泥沙冲下去再放下。"},{"no":"02","title":"Alluvial plains and deltas","titleCN":"冲积平原与三角洲","definition":"flat areas built up over thousands of years by rivers flooding their banks and dropping sediment","definitionCN":"数千年来由河流漫溢、泥沙沉积而成的平坦区域","example":"The Nile delta is a huge alluvial plain supporting 60 million people.","exampleCN":"尼罗河三角洲是养活六千万人的巨大冲积平原。","why":"Alluvial plains are the river's way of saving its sediment from washing all the way to the sea.","whyCN":"冲积平原是河流不让泥沙一路冲进海里的办法。"},{"no":"03","title":"Alluvial fans at mountain mouths","titleCN":"山口的冲积扇","definition":"fan-shaped deposits where a mountain stream suddenly slows and spreads on flatter ground","definitionCN":"山间溪流突然在平坦地面上减速散开时形成的扇形沉积","example":"The valley is dotted with alluvial fans from the surrounding mountains.","exampleCN":"山谷里点缀着周围群山形成的冲积扇。","why":"The fan shape comes from the stream opening up like a hand as it leaves the canyon.","whyCN":"扇形来自溪流离开峡谷后像手一样展开。"},{"no":"04","title":"Alluvial minerals and placer deposits","titleCN":"冲积矿物与砂矿","definition":"valuable minerals washed free from bedrock and concentrated in river beds, such as gold and diamonds","definitionCN":"从基岩里被冲出来、在河床里富集的贵矿物，如金和钻石","example":"The California gold rush was mostly mining alluvial deposits, not hard rock.","exampleCN":"加州淘金潮主要挖的是冲积砂矿，不是硬岩。","why":"Heavy minerals sink while lighter sand continues downstream; prospectors sift for the heavy ones.","whyCN":"重矿物沉底，轻沙继续往下漂；找矿人筛的就是重的那些。"},{"no":"05","title":"Alluvial aquifers underground","titleCN":"地下冲积含水层","definition":"porous sand and gravel layers laid down by ancient rivers that hold groundwater","definitionCN":"古河流沉积的多孔沙砾层，里面储存着地下水","example":"Most drinking water in the Midwest comes from alluvial aquifers.","exampleCN":"美国中西部大部分饮用水来自冲积含水层。","why":"Alluvial gravel is porous, making it an ideal natural water container.","whyCN":"冲积砾石多孔，是天然理想的储水容器。"},{"no":"06","title":"Figurative: layers of accumulated ideas","titleCN":"比喻：累积的思想层","definition":"used for layers of culture or thought built up gradually over generations","definitionCN":"用于描述几代人逐渐堆积起来的文化或思想层","example":"The city's dialect is an alluvial deposit of migrations from a dozen regions.","exampleCN":"这座城市的方言是来自十几个地区移民的冲积层。","why":"Each group arrives like a river bringing sediment, and the speech of the whole community changes.","whyCN":"每群人到达就像一条河带来泥沙，整个社区的语言就改变了。"},{"no":"07","title":"Alluvial vs colluvial distinction","titleCN":"冲积与塌积的区分","definition":"geologists distinguish alluvial (water-carried) from colluvial (gravity-carried) deposits","definitionCN":"地质学家区分水搬运的冲积和重力搬运的塌积","example":"The sample turned out to be colluvial, not alluvial as the farmer had guessed.","exampleCN":"样本原来是塌积的，不是农民猜的冲积。","why":"Different transport mechanisms leave different particle shapes and sorting.","whyCN":"不同搬运方式留下不同颗粒形状和分选程度。"},{"no":"08","title":"Agricultural use and management","titleCN":"农业利用与管理","definition":"farmers prize alluvial soils but must manage them to prevent nutrient loss and subsidence","definitionCN":"农民珍惜冲积土壤，但要防止养分流失和土地下沉","example":"Intensive irrigation is gradually depleting the alluvial aquifer.","exampleCN":"过度灌溉正在慢慢耗尽冲积含水层。","why":"Decades of agriculture draw down the ancient alluvial groundwater faster than rain can refill it.","whyCN":"几十年农业抽取古冲积地下水的速度快过雨水补充。"}],"etymology":{"intro":{"en":"alluvial comes from Latin alluere, itself from ad- (to) + lavare (to wash); the -al suffix makes it an adjective describing what has been washed.","cn":"alluvial 来自拉丁语 alluere，拆成 ad-（向）+ lavare（洗）；-al 后缀让它变成形容词，描述「被洗下来的」东西。"},"items":[{"era":"LATIN","en":"lavare = to wash. alluere = to wash against, to wash down. Latin alluvium meant 'matter deposited by water' since at least the 1st century BCE.","cn":"lavare = 洗。alluere = 冲着洗、往下冲。至少公元前 1 世纪，拉丁语 alluvium 就指「水冲下来的堆积物」。"},{"era":"16TH C ENGLISH","en":"English alluvium appeared as a noun in the 16th century in geological writing.","cn":"英语 alluvium 在 16 世纪的地质文献里作为名词出现。"},{"era":"ADJECTIVE FORM","en":"alluvial was formed by adding the Latin -alis adjective suffix, first recorded in the late 17th century.","cn":"alluvial 通过加拉丁 -alis 形容词后缀构成，最早记载于 17 世纪末。"},{"era":"GEOLOGY","en":"As geology matured in the 18th century, alluvial became a key classification for sedimentary deposits.","cn":"18 世纪地质学成熟时，alluvial 变成了沉积岩分类的关键词。"},{"era":"GOLD RUSH","en":"During the California Gold Rush, prospectors learned to distinguish alluvial gold from hard-rock veins.","cn":"加州淘金潮时，探矿人学会了区分冲积金和硬岩矿脉。"},{"era":"TODAY","en":"alluvial remains a technical term in geography, geology, and water management.","cn":"alluvial 至今仍是地理、地质和水管理领域的技术术语。"}]},"similar":{"note":{"en":"Group one shares the lav- 'to wash' root; group two are related terms for sediment deposits.","cn":"第一组是 lav-「洗」词根家族；第二组是相关的沉积物术语。"},"groups":[{"heading":"SAME ROOT (LAV- WASH)","entries":[{"word":"alluvium","ipa":"/əˈluːviəm/","tag":"noun singular","definition":"The noun: the sediment itself, especially a single deposit.","definitionCN":"名词：沉积物本身，尤指单一堆积。"},{"word":"alluvia","ipa":"/əˈluːviə/","tag":"noun plural","definition":"Plural of alluvium, multiple deposits.","definitionCN":"alluvium 的复数，多个沉积物。"},{"word":"lavatory","ipa":"/ˈlævətɔːri/","tag":"different sense same root","definition":"A place for washing; shares lav- but not the allu- direction.","definitionCN":"洗的地方；共享 lav- 词根但方向不同。"},{"word":"lava","ipa":"/ˈlɑːvə/","tag":"different root","definition":"Actually from labi 'to fall', not lavare; similarity is accidental.","definitionCN":"实际来自 labi「落」，不是 lavare；相似是巧合。"}]},{"heading":"RELATED SEDIMENT TERMS","entries":[{"word":"colluvial","ipa":"/kəˈluːviəl/","tag":"same suffix","definition":"Sediment carried by gravity, not water: a hillside slide deposit.","definitionCN":"由重力搬运的沉积物，不是水：山坡滑下的堆积。"},{"word":"fluvial","ipa":"/ˈfluːviəl/","tag":"river general","definition":"General term for things related to rivers; alluvial is a specific fluvial process.","definitionCN":"与河流有关的泛指；alluvial 是 fluvial 里的一个具体过程。"},{"word":"estuarine","ipa":"/ˈestʃuəriːn/","tag":"mixing zone","definition":"Sediment deposited where river meets tide, mixing alluvial and marine processes.","definitionCN":"河海交汇处的沉积物，混合冲积和海洋过程。"},{"word":"glacial","ipa":"/ˈɡleɪʃl/","tag":"another agent","definition":"Sediment deposited by ice, not water or wind.","definitionCN":"冰沉积的沉积物，不是水或风。"}]}]},"mnemonics":{"normalIntro":{"en":"alluvial = washed down by a river.","cn":"alluvial = 被河「洗」下来的。"},"normal":[{"en":"ad- (to) + lavare (wash) → wash down → alluvial.","cn":"ad-（向）+ lavare（洗）→ 冲下去 → alluvial。"},{"en":"Alluvial gold sits in river beds where water washed the nuggets free.","cn":"冲积金在河床里，那里的河把金块冲出来了。"},{"en":"The Mississippi and Ganges built their deltas from alluvial soil.","cn":"密西西比河和恒河用 alluvial 土壤堆出了三角洲。"},{"en":"Farmers love alluvial soil because it comes fresh every flood.","cn":"农民爱 alluvial 土壤，因为每次洪水都带来新的。"},{"en":"A geologist's notebook separates alluvial from colluvial samples.","cn":"地质学家笔记本里把 alluvial 和 colluvial 分开写。"}],"abstract":[{"en":"A river fanning out at a delta, slowing, dropping its load, building new land.","cn":"一条河在三角洲散开、减速、卸货、造新陆地。"},{"en":"Layers of fine silt stacked like pages in a very old book.","cn":"像旧书页一样一页页叠起来的细淤泥。"},{"en":"Heavy gold flakes panning down through lighter sand at the bottom of a pan.","cn":"淘金盘里在较轻的沙子中间沉底的金片。"}]},"examples":[{"en":"Flood events renew alluvial fertility every few years in the Mekong delta.","cn":"湄公河三角洲每隔几年的洪水恢复冲积土壤的肥力。"},{"en":"The city sits on alluvial deposits up to 200 meters deep, above an ancient river bed.","cn":"这座城市建在厚达 200 米的冲积沉积物上，底下是古河床。"},{"en":"Prospectors still sift the river's gravel for alluvial gold on weekends.","cn":"周末还有探矿人在河砾里筛冲积金。"}],"dict_mnemonic":{"note":"词根记忆","text":"ad- + lavare（洗）+ -al → 被冲洗下来的 → 冲积的","word":"alluvial"},"root":"lavare（拉丁语，洗）→ alluere（冲着洗）→ alluvium（冲积物）→ -al → alluvial。","sensesIntro":{"en":"Eight senses describe where the washed material ends up: plains, deltas, fans, mining beds, aquifers, culture, geological distinctions, and farms.","cn":"八个义项讲「被冲下来的东西」最终留在了哪里：平原、三角洲、扇、矿床、含水层、文化、地质区分、农场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a river depositing a fan of silt where it leaves the canyon for the flat plain.","cn":"核心意象：河流离开峡谷进入平原时堆出一个扇形泥沙堆。"},"chain":["RIVER CARRIES SEDIMENT","RIVER DROPS SEDIMENT","PLAINS AND DELTAS FORM","FANS FORM AT MOUTH","MINERALS CONCENTRATE","AQUIFERS STORE WATER"],"branches":[{"senses":"01 · 02 · 03 · 08","en":"GEOLOGICAL FORMATIONS AND THEIR USE: plains, deltas and fans are read as landforms and as farmland.","cn":"地质构造与利用：平原、三角洲与冲积扇既是地貌，也是被耕作的田地。"},{"senses":"04","en":"ECONOMIC: MINING","cn":"经济：采矿"},{"senses":"05","en":"WATER RESOURCES","cn":"水资源"},{"senses":"06","en":"CULTURAL METAPHOR","cn":"文化比喻"},{"senses":"07","en":"TERMINOLOGY","cn":"术语"}]},"affixes":{"intro":{"en":"alluvial adds the Latin adjective suffix -al to the noun alluvium, which is itself from alluere 'to wash against'.","cn":"alluvial 是名词 alluvium 加拉丁形容词后缀 -al 构成；alluvium 又来自 alluere「冲着洗」。"},"latinIntro":{"en":"lavare is a common Latin root giving English launder, lavender (from washing scent), lavatory, deluge.","cn":"lavare 是常见拉丁词根，给出 launder（洗衣）、lavatory、deluge（洪水）等。"},"items":[{"word":"lavare","structure":"Latin root","meaning":"to wash","meaningCN":"洗","example":"lavatory = place to wash","exampleCN":"洗手间"},{"word":"alluere","structure":"ad- + lavare","meaning":"to wash against / wash down","meaningCN":"冲着洗","example":"alluvial deposit","exampleCN":"冲积沉积物"},{"word":"alluvium","structure":"alluere + -um","meaning":"matter washed down by water","meaningCN":"冲积物","example":"thick alluvium","exampleCN":"厚厚的冲积层"},{"word":"alluvial","structure":"alluvium + -al","meaning":"of or relating to alluvium","meaningCN":"冲积的","example":"alluvial plain","exampleCN":"冲积平原"},{"word":"alluvion","structure":"alluere + -ion","meaning":"flooding; accretion of land by deposit","meaningCN":"洪水；土地淤积","example":"alluvion of the delta","exampleCN":"三角洲的淤积"},{"word":"lavatory","structure":"lavare + -atory","meaning":"place for washing","meaningCN":"洗手间","example":"public lavatory","exampleCN":"公共洗手间"},{"word":"deluge","structure":"de- + lavare (via French déluge)","meaning":"great flood","meaningCN":"大洪水","example":"a deluge of rain","exampleCN":"一场大雨"},{"word":"launder","structure":"lavare via French","meaning":"to wash (clothes)","meaningCN":"洗（衣服）","example":"launder shirts","exampleCN":"洗衬衫"},{"word":"lavender","structure":"lavare (wash scent)","meaning":"purple herb used for scenting laundry","meaningCN":"薰衣草","example":"lavender sachet","exampleCN":"薰衣草香包"}],"latinEntries":[]}},{"word":"astronomy","ipa_uk":"/əˈstrɒnəmi/","ipa_us":"/əˈstrɒnəmi/","definition_zh":"天文学","definition_en":"the scientific study of the universe, stars, planets and other celestial bodies","core_image":"一张从地球轨道向外看去的银河全景图，星点密密麻麻","scene":"开学第一节课老师说：Astronomy asks what the universe is made of, how it began, and where it's going.","sceneCN":"这里指「研究宇宙和天体的科学」（第1个义项：科学学科）；句意为天文学追问宇宙由什么构成、如何起源、去往何处。","pos":[{"tag":"n.","zh":"天文学（不可数）"}],"collocations":[{"phrase":"observational astronomy","zh":"观测天文学"},{"phrase":"theoretical astronomy","zh":"理论天文学"},{"phrase":"optical astronomy","zh":"光学天文学"},{"phrase":"radio astronomy","zh":"射电天文学"},{"phrase":"modern astronomy","zh":"现代天文学"},{"phrase":"study astronomy","zh":"学习天文学"}],"forms":[{"label":"不可数名词","form":"无复数"}],"derivatives":[{"word":"astronomer","pos":"n.","zh":"天文学家"},{"word":"astronomical","pos":"adj.","zh":"天文学的；巨大的"},{"word":"astrophysics","pos":"n.","zh":"天体物理学"},{"word":"astrobiology","pos":"n.","zh":"天体生物学"},{"word":"cosmology","pos":"n.","zh":"宇宙学"}],"senses":[{"no":"01","title":"The scientific discipline itself","titleCN":"作为学科本身的天文学","definition":"one of the oldest natural sciences, studying everything outside Earth's atmosphere","definitionCN":"最古老的自然科学之一，研究地球大气层以外的一切","example":"Astronomy has reshaped our picture of the universe in the last century.","exampleCN":"过去一百年里天文学重塑了我们对宇宙的认识。","why":"The Greek roots astron (star) + nomos (law) make this the 'law of stars'.","whyCN":"希腊词根 astron（星）+ nomos（法）让它成为「星辰之法」。"},{"no":"02","title":"Observational astronomy","titleCN":"观测天文学","definition":"the branch that gathers data with telescopes, cameras and detectors from the ground or space","definitionCN":"用望远镜、相机和探测器从地面或太空收集数据的分支","example":"Observational astronomy got a new eye when the Hubble telescope launched in 1990.","exampleCN":"1990 年哈勃升空给观测天文学添了一只新眼。","why":"Observational astronomy is the empirical side, gathering evidence that theorists use.","whyCN":"观测天文学是经验的一面，收集理论家使用的证据。"},{"no":"03","title":"Theoretical astronomy","titleCN":"理论天文学","definition":"the branch that builds models to explain what observations reveal","definitionCN":"建立模型解释观测结果的分支","example":"Theoretical astronomy predicts where black holes should lie in galaxy centres.","exampleCN":"理论天文学预言黑洞应该在星系中心哪里。","why":"Theory gives meaning to observations, turning data into understanding.","whyCN":"理论给观测赋予意义，把数据变成理解。"},{"no":"04","title":"Astronomy history and pre-scientific","titleCN":"前科学的天文观测（历史上）","definition":"the ancient practice of tracking skies for calendars, religion or navigation, before the scientific method","definitionCN":"科学方法出现之前，为历算、宗教或导航追踪天象的古老实践","example":"Maya astronomy predicted eclipses with remarkable accuracy without telescopes.","exampleCN":"玛雅天文学不用望远镜就以惊人准确度预测了日食月食。","why":"Early astronomy blended with astrology, religion and agriculture.","whyCN":"早期天文学与占星、宗教、农业混在一起。"},{"no":"05","title":"Popular astronomy / stargazing","titleCN":"业余天文 / 观星","definition":"the hobby or public outreach of observing the sky with small telescopes or the naked eye","definitionCN":"用小望远镜或肉眼观星的爱好或科普活动","example":"The park hosts free astronomy nights every month for the public.","exampleCN":"公园每月给公众办免费天文之夜。","why":"Popular astronomy shares the sky with non-scientists, keeping wonder alive.","whyCN":"科普天文把星空分享给非科学家，让好奇心延续。"},{"no":"06","title":"Subfields: planetary, stellar, galactic","titleCN":"子学科：行星、恒星、星系","definition":"astronomy splits into subfields by object studied: planets, stars, galaxies, the universe as a whole","definitionCN":"按研究对象划分的子学科：行星、恒星、星系、宇宙整体","example":"She chose galactic astronomy, studying how the Milky Way formed.","exampleCN":"她选了星系天文学，研究银河系如何形成。","why":"Each subfield brings its own tools and questions, but all belong under the same root.","whyCN":"每个子学科有自己的工具和问题，但都在同一词根之下。"},{"no":"07","title":"Astrology vs astronomy","titleCN":"占星与天文的区分","definition":"astronomy is the scientific study; astrology uses celestial positions to predict human affairs and is not a science","definitionCN":"astronomy 是科学研究；占星用天体位置预言人类事务，不是科学","example":"Most universities offer astronomy, none offer astrology as a science.","exampleCN":"大多数大学教 astronomy，没有哪所大学把占星作为科学开设。","why":"The -logy ending in astrology sounds scientific but does not mean it uses the scientific method.","whyCN":"astrology 里的 -logy 听起来科学但不代表它用科学方法。"},{"no":"08","title":"Influencing other sciences","titleCN":"影响其他学科","definition":"astronomy overlaps with physics, chemistry, geology, biology and information science","definitionCN":"astronomy 与物理、化学、地质、生物、信息科学有交叉","example":"Discoveries in astronomy often drive new inventions in sensing and computing.","exampleCN":"天文学的发现常常推动传感和计算的新发明。","why":"The universe is the largest laboratory; everything physical here is also physical 'out there'.","whyCN":"宇宙是最大的实验室；这里一切物理事物在「外面」也是物理的。"}],"etymology":{"intro":{"en":"astronomy comes from Greek: astron 'star' + nomos 'law, custom' → 'the law of stars'; it arrived in Latin as astronomia and entered English around the 13th century.","cn":"astronomy 来自希腊语：astron「星」+ nomos「法」→「星辰之法」；经拉丁语 astronomia，13 世纪进入英语。"},"items":[{"era":"GREEK","en":"Aristotle used astronomia to mean the study of celestial motions; nomos meant 'the law that governs'.","cn":"亚里士多德用 astronomia 指对天体运动的研究；nomos 意为「支配之法」。"},{"era":"LATIN","en":"Latin borrowed astronomia directly from Greek, keeping both the word and the meaning.","cn":"拉丁语直接从希腊语借入 astronomia，词和意思都不变。"},{"era":"MIDDLE ENGLISH","en":"Middle English astronomie (13th century) was the standard spelling, borrowed through Old French astronomie.","cn":"中古英语 astronomie（13 世纪）是标准拼写，经古法语 astronomie 借入。"},{"era":"EARLY MODERN","en":"Spelling shifted to astronomy by the 16th century, matching the Greek -nomy suffix pattern.","cn":"到 16 世纪拼写变成 astronomy，对齐希腊 -nomy 后缀形式。"},{"era":"SCIENTIFIC REVOLUTION","en":"Copernicus and Kepler redefined astronomy in the 16th and 17th centuries as mathematical physics of the heavens.","cn":"哥白尼和开普勒在 16-17 世纪把 astronomy 重新定义为天上的数学物理。"},{"era":"MODERN","en":"Today astronomy spans from subatomic particles to the structure of the cosmos.","cn":"今天 astronomy 从亚原子粒子延伸到宇宙结构。"}]},"similar":{"note":{"en":"Group one holds astronomy-derived words; group two holds related 'sky science' and related -nomy / -logy terms.","cn":"第一组是 astronomy 派生的词；第二组是相关的「天空科学」和相近的 -nomy / -logy 术语。"},"groups":[{"heading":"SAME ROOT FAMILY","entries":[{"word":"astronomer","ipa":"/əˈstrɒnəmər/","tag":"person","definition":"A person who works in astronomy.","definitionCN":"做 astronomy 的人。"},{"word":"astronomical","ipa":"/ˌæstrəˈnɒmɪkl/","tag":"adjective","definition":"Of astronomy; informally, huge in size.","definitionCN":"天文学的；口语里表示「极大的」。"},{"word":"astrophysics","ipa":"/ˌæstrəʊˈfɪzɪks/","tag":"subfield","definition":"Physics applied to astronomical objects; technically a subfield.","definitionCN":"用物理研究天体；严格说是 astronomy 的子学科。"},{"word":"astrobiology","ipa":"/ˌæstrəʊbaɪˈɒlədʒi/","tag":"interdisciplinary","definition":"The study of life in the universe; also called exobiology.","definitionCN":"研究宇宙中的生命；也叫 exobiology。"}]},{"heading":"RELATED FIELDS","entries":[{"word":"astrology","ipa":"/əˈstrɒlədʒi/","tag":"often confused","definition":"Not a science; uses celestial positions to interpret human affairs.","definitionCN":"非科学；用天体位置解读人类事务。"},{"word":"cosmology","ipa":"/kɒzˈmɒlədʒi/","tag":"subfield","definition":"The part of astronomy that studies the origin and structure of the whole universe.","definitionCN":"研究整个宇宙起源和结构的 astronomy 分支。"},{"word":"cosmogony","ipa":"/kɒzˈmɒɡəni/","tag":"narrower","definition":"The specific study of how the universe began; narrower than cosmology.","definitionCN":"专门研究宇宙如何起源；范围比 cosmology 窄。"},{"word":"cosmography","ipa":"/kɒzˈmɒɡrəfi/","tag":"description","definition":"Describing and mapping the universe rather than modelling its physics.","definitionCN":"描述和绘制宇宙，而非建模其物理。"}]}]},"mnemonics":{"normalIntro":{"en":"astron- = star, -nomy = law → astronomy = the law of stars.","cn":"astron- = 星，-nomy = 法 → astronomy = 星辰之法。"},"normal":[{"en":"astron (Greek for star) + nomos (Greek for law) = astronomy.","cn":"astron（希腊语「星」）+ nomos（希腊语「法」）= astronomy。"},{"en":"An astronomer follows the laws of stars.","cn":"天文学家追随星辰之法。"},{"en":"People once called astronomy 'the science of the stars'.","cn":"人们曾经把 astronomy 叫「星辰的科学」。"},{"en":"Astronomy uses telescopes; astrology uses horoscopes.","cn":"Astronomy 用望远镜；占星用星盘。"},{"en":"Kepler wrote the laws of planetary motion — laws of stars.","cn":"开普勒写了行星运动定律——星辰之法。"}],"abstract":[{"en":"A clear night, the Milky Way overhead, a telescope pointing somewhere deep.","cn":"晴朗的夜，头顶银河，望远镜指向深处某处。"},{"en":"A thousand-year quest to figure out where we are and why.","cn":"一场绵延千年的追问：我们在哪、为什么。"},{"en":"Something ancient, vast, and always pointing up.","cn":"一种古老、浩瀚、永远向上指的东西。"}]},"examples":[{"en":"Radio astronomy began in the 1930s when engineers accidentally picked up cosmic radio noise.","cn":"射电天文学始于 1930 年代，工程师无意中接收到宇宙射电噪声。"},{"en":"Astronomy is a team science; modern observations involve telescopes on every continent and in space.","cn":"astronomy 是团队科学；现代观测涉及每个大陆和太空的望远镜。"},{"en":"Her PhD combined astronomy with statistics to hunt for exoplanets.","cn":"她的博士结合了天文学和统计来寻找系外行星。"}],"dict_mnemonic":{"note":"词根记忆","text":"astron-（星）+ -nomy（法）= 星辰之法 = 天文学","word":"astronomy"},"root":"astron（希腊语，星）+ nomos（法）→ astronomia → astronomy。","sensesIntro":{"en":"Eight senses map the many ways we study the sky: observing, theorising, history, popular enthusiasm, subfields, distinguishing from astrology, and influence on other sciences.","cn":"八个义项覆盖我们研究天空的种种方式：观测、理论、历史、业余爱好、子学科、与占星区分、对其他科学的影响。"},"semanticMap":{"core":{"en":"CORE IMAGE: a telescope pointed at a dark sky, pulling faint stars into bright focus.","cn":"核心意象：指向暗空的望远镜，把暗淡的星辰拉成清晰的焦点。"},"chain":["OBSERVE THE SKY","THURISE ABOUT IT","TRACK HISTORIC SKIES","INVOLVE THE PUBLIC","SPLIT INTO SUBFIELDS","CONNECT TO OTHER SCIENCES"],"branches":[{"senses":"01 · 02","en":"DISCIPLINE AND OBSERVATION: the field itself, plus the work of watching and measuring the sky.","cn":"学科与观测：这门学科本身，以及观测测量天空的工作。"},{"senses":"03","en":"THEORETICAL: the branch that builds models and predictions.","cn":"理论：负责建立模型与预言的分支。"},{"senses":"04","en":"HISTORICAL: pre-scientific sky watching and its records.","cn":"历史：前科学时期的天象观测及其记录。"},{"senses":"05","en":"POPULAR / OUTREACH: amateur stargazing and public explanation.","cn":"科普 / 业余：业余观星与面向公众的解释。"},{"senses":"06 · 07 · 08","en":"CLASSIFICATION / BOUNDARIES / INFLUENCE: subfields, the line against astrology, and effects on other sciences.","cn":"分类 / 边界 / 影响：子学科、与占星的界线，以及对其他学科的影响。"}]},"affixes":{"intro":{"en":"astronomy is built from Greek astron 'star' plus the Greek suffix -nomy 'law, system of rules'; many astronomy words share astron-.","cn":"astronomy 由希腊 astron「星」加希腊后缀 -nomy「法、规则体系」构成；许多 astronomy 相关词都共享 astron-。"},"latinIntro":{"en":"astron is purely Greek, not Latin; the Latin 'star' is stella, which gives stellar.","cn":"astron 纯粹来自希腊，不是拉丁语；拉丁语的「星」是 stella，给出 stellar。"},"items":[{"word":"astron","structure":"Greek root","meaning":"star","meaningCN":"星","example":"astron- prefix","exampleCN":"astron- 前缀"},{"word":"astronomy","structure":"astron- + -nomy","meaning":"study of the laws of stars","meaningCN":"天文学","example":"study astronomy","exampleCN":"学习天文学"},{"word":"astronomer","structure":"astronom- + -er","meaning":"one who studies stars","meaningCN":"天文学家","example":"professional astronomer","exampleCN":"职业天文学家"},{"word":"astronomical","structure":"astronom- + -ical","meaning":"relating to astronomy","meaningCN":"天文学的；巨大的","example":"astronomical cost","exampleCN":"天文数字的成本"},{"word":"astrophysics","structure":"astro- + physics","meaning":"physics of astronomical objects","meaningCN":"天体物理学","example":"degree in astrophysics","exampleCN":"天体物理学位"},{"word":"astrophysical","structure":"astrophysics + -al","meaning":"relating to astrophysics","meaningCN":"天体物理的","example":"astrophysical model","exampleCN":"天体物理模型"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who practices astrophysics","meaningCN":"天体物理学家","example":"leading astrophysicist","exampleCN":"顶尖天体物理学家"},{"word":"astrobiology","structure":"astro- + biology","meaning":"biology of extraterrestrial life","meaningCN":"天体生物学","example":"astrobiology conference","exampleCN":"天体生物学会议"},{"word":"astrochemistry","structure":"astro- + chemistry","meaning":"chemistry of astronomical environments","meaningCN":"天体化学","example":"astrochemistry research","exampleCN":"天体化学研究"},{"word":"astronaut","structure":"astro- + nautes","meaning":"one who navigates among the stars","meaningCN":"宇航员","example":"training astronaut","exampleCN":"正在训练的宇航员"}],"latinEntries":[]}},{"word":"astronomical","ipa_uk":"/ˌæstrəˈnɒmɪkl/","ipa_us":"/ˌæstrəˈnɒmɪkl/","definition_zh":"天文学的；天文数字的","definition_en":"relating to astronomy; (informal) extremely large","core_image":"哈勃望远镜拍摄的深空照片——密密麻麻的星系像撒了一把糖","scene":"新闻里解说员说：The new fusion plant will require an astronomical investment before it can produce a single watt.","sceneCN":"这里指「数量极其巨大的」（第2个义项：非正式，表示天文数字）；句意为这座新聚变电站要投入天文数字的钱才能产生一瓦电。","pos":[{"tag":"adj.","zh":"天文学的；（口语）天文数字的"}],"collocations":[{"phrase":"astronomical observation","zh":"天文观测"},{"phrase":"astronomical telescope","zh":"天文望远镜"},{"phrase":"astronomical model","zh":"天文学模型"},{"phrase":"astronomical sum","zh":"天文数字的金额"},{"phrase":"astronomical cost","zh":"天文数字的成本"},{"phrase":"astronomical number","zh":"天文数字"}],"forms":[{"label":"副词","form":"astronomically"}],"derivatives":[{"word":"astronomy","pos":"n.","zh":"天文学"},{"word":"astronomer","pos":"n.","zh":"天文学家"},{"word":"astrophysical","pos":"adj.","zh":"天体物理的"},{"word":"astronautical","pos":"adj.","zh":"航天的"},{"word":"astronautically","pos":"adv.","zh":"航天地"}],"senses":[{"no":"01","title":"Relating to the science of astronomy","titleCN":"与天文学有关的","definition":"the core technical sense: of, belonging to, or using methods of astronomy","definitionCN":"核心技术义项：属于天文学的、使用天文学方法的","example":"The observatory was built for astronomical observations of the southern sky.","exampleCN":"这座天文台是为南半球的天文观测而建的。","why":"This is the literal adjective: anything connected to astronomy is astronomical.","whyCN":"这就是字面形容词：跟 astronomy 有关的就是 astronomical。"},{"no":"02","title":"Extremely large or huge","titleCN":"极大的、天文数字的","definition":"informal usage: so large it dwarfs normal human-scale numbers, like distances in space","definitionCN":"非正式用法：大到超过人类日常数字尺度，像宇宙里的距离那样","example":"The stadium renovation cost an astronomical sum of money.","exampleCN":"体育场改造花了天文数字的钱。","why":"Astronomical numbers are the distances and sizes we talk about in astronomy: light-years, billions of stars.","whyCN":"天文数字就是 astronomy 里用的距离和大小：光年、几十亿颗星。"},{"no":"03","title":"Astronomical instruments and methods","titleCN":"天文仪器与方法","definition":"equipment and techniques used to observe or calculate celestial positions and movements","definitionCN":"用于观测或计算天体位置和运动的设备与方法","example":"Ancient astronomers used simple astronomical instruments like the astrolabe.","exampleCN":"古代天文学家使用星盘这类简单天文仪器。","why":"The adjective applies to the tools that let us do astronomy, not just the subject itself.","whyCN":"这个形容词也用于做 astronomy 的工具，不只是主题本身。"},{"no":"04","title":"Astronomical scale of the universe","titleCN":"宇宙的天文尺度","definition":"the unimaginable scale of time, distance and energy that astronomy deals with","definitionCN":"astronomy 涉及的时间、距离、能量的难以想象的尺度","example":"The expansion of the universe happens on astronomical timescales — billions of years.","exampleCN":"宇宙膨胀发生在天文尺度的时间上——几十亿年。","why":"In science, astronomical often reminds us that we are dealing with numbers beyond everyday experience.","whyCN":"科学里 astronomical 常提醒我们正在处理超出日常经验的数字。"},{"no":"05","title":"Historic astronomical events","titleCN":"历史上的天文事件","definition":"events visible to the naked eye — eclipses, comets, supernovae — recorded across cultures and centuries","definitionCN":"肉眼可见的天文事件——日食、彗星、超新星——在各种文化和世纪中被记录","example":"The 1882 transit of Venus was an astronomical event observed across the globe.","exampleCN":"1882 年金星凌日是一场全球观测的天文事件。","why":"Historic astronomical events bring the science out of the observatory and into public memory.","whyCN":"历史天文事件把科学从天文台带进了公众记忆。"},{"no":"06","title":"Astronomical observations today","titleCN":"今天的天文观测","definition":"data collected by modern ground-based and space telescopes across the electromagnetic spectrum","definitionCN":"现代地面和太空望远镜在整个电磁波谱上收集的数据","example":"Astronomical observations from Hubble transformed our view of galaxy formation.","exampleCN":"哈勃的天文观测改变了我们对星系形成的看法。","why":"Observations remain the foundation of astronomical knowledge, even as theory grows.","whyCN":"观测始终是天文知识的基础，哪怕理论在长大。"},{"no":"07","title":"Astronomical vs astrological","titleCN":"天文的 vs 占星的","definition":"astronomical means scientific; astrological means interpreting human affairs from celestial positions","definitionCN":"astronomical 指科学的；astrological 指用天体位置解读人类事务的","example":"Astronomical charts differ fundamentally from astrological horoscopes.","exampleCN":"天文图和占星星盘有根本区别。","why":"The distinction matters because both use the sky, but only one is a science.","whyCN":"这个区分重要，因为两者都看天空但只有一个是科学。"},{"no":"08","title":"Astronomical investment in research","titleCN":"天文级规模的科研投入","definition":"large international partnerships building observatories that cost billions of dollars over decades","definitionCN":"耗资数十亿、历时数十年的大型国际联合天文台","example":"The James Webb Space Telescope was an astronomical investment spanning 25 years and many nations.","exampleCN":"韦伯太空望远镜是跨越 25 年、多国参与的天文级投资。","why":"Big science on a cosmic scale requires budgets that seem astronomical themselves.","whyCN":"宇宙尺度上的大科学需要的预算本身也显得很 astronomical。"}],"etymology":{"intro":{"en":"astronomical is a Greek-derived adjective: astron (star) + nomos (law) + -ical (adjective suffix), meaning 'pertaining to the law of stars'.","cn":"astronomical 是希腊来源的形容词：astron（星）+ nomos（法）+ -ical（形容词后缀），意为「与星辰之法有关的」。"},"items":[{"era":"GREEK","en":"astronomikos existed in Greek, from astronomia 'law of stars'.","cn":"希腊语已有 astronomikos，来自 astronomia「星辰之法」。"},{"era":"LATIN","en":"Latin borrowed astronomicus as a direct calque.","cn":"拉丁语直接借入 astronomicus。"},{"era":"MIDDLE ENGLISH","en":"Middle English astronomik appeared in the 14th century.","cn":"中古英语 astronomik 在 14 世纪出现。"},{"era":"EARLY MODERN","en":"astronomical appeared alongside astronomy in the 16th century.","cn":"astronomical 与 astronomy 一起在 16 世纪出现。"},{"era":"EXTENSION TO SIZE","en":"The 'extremely large' sense developed in the 18th century, from the scale of numbers in astronomy.","cn":"18 世纪发展出「极大的」含义，来自 astronomy 里数字的尺度。"},{"era":"TODAY","en":"Both the scientific and the informal 'huge' sense are common.","cn":"科学义项和口语「极大的」义项今天都常用。"}]},"similar":{"note":{"en":"Group one shares the astronom- root; group two collects 'very large' synonyms and other 'astron-' adjectives.","cn":"第一组共享 astronom- 词根；第二组收集「极大的」同义词和其他 astron- 形容词。"},"groups":[{"heading":"SAME ROOT FAMILY","entries":[{"word":"astronomy","ipa":"/əˈstrɒnəmi/","tag":"noun","definition":"The science that astronomical things belong to.","definitionCN":"astronomical 事物所属的科学。"},{"word":"astronomer","ipa":"/əˈstrɒnəmər/","tag":"person","definition":"Someone who works with astronomical data.","definitionCN":"处理 astronomical 数据的人。"},{"word":"astrophysical","ipa":"/ˌæstrəʊˈfɪzɪkl/","tag":"specific subfield","definition":"Of or relating to astrophysics — physics of celestial bodies.","definitionCN":"与天体物理有关的。"},{"word":"astronautical","ipa":"/ˌæstrəˈnɔːtɪkl/","tag":"space travel","definition":"Of spacecraft and space travel, not of stars themselves.","definitionCN":"关于航天器和航天的，不是关于恒星本身的。"}]},{"heading":"RELATED SENSES","entries":[{"word":"colossal","ipa":"/kəˈlɒsl/","tag":"very large","definition":"Used for huge physical things, like mountains or statues.","definitionCN":"用于巨大的物理事物，如山或雕像。"},{"word":"cosmic","ipa":"/ˈkɒzmɪk/","tag":"same field","definition":"Relating to the whole universe; often used figuratively for immense scale.","definitionCN":"与整个宇宙有关的；常比喻极大尺度。"},{"word":"galactic","ipa":"/ɡəˈlæktɪk/","tag":"same field","definition":"Relating to galaxies; sometimes used figuratively for huge amounts.","definitionCN":"关于星系的；有时比喻巨大数额。"},{"word":"astronomically","ipa":"/ˌæstrəˈnɒmɪkli/","tag":"adverb","definition":"Used to intensify size or distance in scientific writing.","definitionCN":"用于强化科学写作中的大小或距离。"}]}]},"mnemonics":{"normalIntro":{"en":"astronomical = of the stars; stars are far and big → astronomical = huge.","cn":"astronomical = 星辰的；星辰远又大 → astronomical = 极大的。"},"normal":[{"en":"astron- = star + -nomical = following law → astronomical.","cn":"astron- = 星 + -nomical = 遵法 → astronomical。"},{"en":"Stars are astronomical in both their science and their distance.","cn":"星辰在科学上和尺度上都是 astronomical。"},{"en":"An astronomical number is a number as big as distances between stars.","cn":"astronomical 数字就是像恒星间距离那么大的数字。"},{"en":"The Hubble telescope makes astronomical observations.","cn":"哈勃望远镜做 astronomical 观测。"},{"en":"Astronomical budgets fund projects on the scale of the universe.","cn":"Astronomical 规模的预算资助宇宙尺度的项目。"}],"abstract":[{"en":"A number written with so many zeros it fades off the page like stars into space.","cn":"一个写着太多零、像星星一样淡出纸边的数字。"},{"en":"Looking up from a telescope into a sky with no bottom.","cn":"从望远镜里望向无边无际的夜空。"},{"en":"A small coin held up against an enormous galaxy.","cn":"一枚小硬币贴在一个巨大的星系图前。"}]},"examples":[{"en":"The festival featured talks from leading astronomers and live astronomical observations.","cn":"节庆有顶尖天文学家的报告和实时天文观测。"},{"en":"The country's national debt reached astronomical proportions.","cn":"这个国家的国债达到了天文数字。"},{"en":"Astronomical spectroscopy can tell us what a distant star is made of.","cn":"天文光谱学能告诉我们一颗遥远恒星由什么构成。"}],"dict_mnemonic":{"note":"词根记忆","text":"astron（星）+ -nomical（法的）→ 星辰之法的 → 天文学的；星辰尺度的 → 极大的","word":"astronomical"},"root":"astron（希腊语，星）+ nomos（法）→ astronomikos → astronomical。","sensesIntro":{"en":"Eight senses split cleanly: four belong to the science, four describe the figurative 'huge' scale associated with space.","cn":"八个义项清楚地分开：四个属于科学本身，四个描述与宇宙相关的比喻性「巨大」尺度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a galaxy image from Hubble, thousands of points of light on a black background, incomprehensibly far.","cn":"核心意象：哈勃拍的星系图，黑底上几千个光点，远得难以想象。"},"chain":["OF THE SCIENCE","TOO BIG FOR DAILY LIFE","INSTRUMENTS OF STUDY","TIMESCALES OF THE UNIVERSE","HISTORIC NAKED-EYE EVENTS","BIG-SCALE INVESTMENTS"],"branches":[{"senses":"01","en":"THE DISCIPLINE: of, or belonging to, the science of astronomy itself.","cn":"学科本体：属于天文学这门科学本身。"},{"senses":"03 · 06","en":"INSTRUMENTS AND OBSERVATION: the equipment, methods and data used to watch the sky.","cn":"仪器与观测：用来观测天空的设备、方法与数据。"},{"senses":"05","en":"HISTORIC EVENTS: eclipses, comets and supernovae recorded by the naked eye.","cn":"历史事件：肉眼记录下来的日食、彗星与超新星。"},{"senses":"02 · 04 · 08","en":"SCALE: sizes, timespans and budgets far beyond everyday numbers.","cn":"尺度：远超日常数字的大小、时间跨度与预算。"},{"senses":"07","en":"BOUNDARY WITH ASTROLOGY: describing the science, never the reading of human affairs in the sky.","cn":"与占星的边界：指科学，绝不指从天象解读人事。"}]},"affixes":{"intro":{"en":"astronomical adds the -ical adjective suffix to astronom-; the root astron 'star' is shared across dozens of astronomy words.","cn":"astronomical 在 astronom- 上加 -ical 形容词后缀；词根 astron「星」在几十个天文词里共享。"},"latinIntro":{"en":"astr- is Greek; Latin 'star' is stella, which gives stellar.","cn":"astr- 来自希腊语；拉丁语的「星」是 stella，给出 stellar。"},"items":[{"word":"astron","structure":"Greek root","meaning":"star","meaningCN":"星","example":"astron- prefix","exampleCN":"astron- 前缀"},{"word":"astronomy","structure":"astron- + -nomy","meaning":"science of stars","meaningCN":"天文学","example":"study astronomy","exampleCN":"学习天文学"},{"word":"astronomical","structure":"astronom- + -ical","meaning":"pertaining to astronomy","meaningCN":"天文学的；极大的","example":"astronomical figure","exampleCN":"天文数字"},{"word":"astronomically","structure":"astronomical + -ly","meaning":"in an astronomical way","meaningCN":"天文地；巨大地","example":"astronomically large","exampleCN":"天文级地大"},{"word":"astronomer","structure":"astronom- + -er","meaning":"one who studies stars","meaningCN":"天文学家","example":"amateur astronomer","exampleCN":"业余天文学家"},{"word":"astrophysics","structure":"astro- + physics","meaning":"physics of stars","meaningCN":"天体物理学","example":"astrophysics degree","exampleCN":"天体物理学位"},{"word":"astrophysical","structure":"astrophysics + -al","meaning":"of astrophysics","meaningCN":"天体物理的","example":"astrophysical model","exampleCN":"天体物理模型"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"senior astrophysicist","exampleCN":"资深天体物理学家"},{"word":"astronaut","structure":"astro- + nautes","meaning":"star sailor","meaningCN":"宇航员","example":"experienced astronaut","exampleCN":"经验丰富的宇航员"}],"latinEntries":[]}},{"word":"astronomer","ipa_uk":"/əˈstrɒnəmər/","ipa_us":"/əˈstrɒnəmər/","definition_zh":"天文学家","definition_en":"a scientist who studies the universe, stars, planets and other celestial bodies","core_image":"一个戴着眼镜、头发花白的老头站在大型望远镜前，抬头望天","scene":"纪录片里解说员说：Edwin Hubble, the astronomer after whom the great telescope was named, proved the universe is expanding.","sceneCN":"这里指「职业是研究天体的科学家」（第1个义项：专业天文学家）；句意为哈勃望远镜命名的那位天文学家证明了宇宙在膨胀。","pos":[{"tag":"n.","zh":"天文学家"}],"collocations":[{"phrase":"professional astronomer","zh":"职业天文学家"},{"phrase":"amateur astronomer","zh":"业余天文学家"},{"phrase":"observational astronomer","zh":"观测天文学家"},{"phrase":"theoretical astronomer","zh":"理论天文学家"},{"phrase":"leading astronomer","zh":"顶尖天文学家"},{"phrase":"ancient astronomer","zh":"古代天文学家"}],"forms":[{"label":"复数","form":"astronomers"}],"derivatives":[{"word":"astronomy","pos":"n.","zh":"天文学"},{"word":"astronomical","pos":"adj.","zh":"天文学的；巨大的"},{"word":"astrobiologist","pos":"n.","zh":"天体生物学家"},{"word":"astrophysicist","pos":"n.","zh":"天体物理学家"},{"word":"cosmologist","pos":"n.","zh":"宇宙学家"}],"senses":[{"no":"01","title":"Professional working in the field","titleCN":"职业天文学家","definition":"a scientist with advanced training in astronomy, employed by observatories, universities or space agencies","definitionCN":"受过高等天文学训练，被天文台、大学或航天机构雇佣的科学家","example":"The astronomer stayed up all night collecting data on a rare comet.","exampleCN":"那位天文学家熬夜收集一颗罕见彗星的数据。","why":"Like other -er professions, astronomer names the person who does astronomy.","whyCN":"和其他 -er 职业一样，astronomer 就是做 astronomy 的人。"},{"no":"02","title":"Amateur astronomer","titleCN":"业余天文学家","definition":"a person who observes the sky as a hobby, often with modest equipment but serious enthusiasm","definitionCN":"以观星为爱好的人，设备可能不高级但热情很高","example":"An amateur astronomer in Australia spotted a new asteroid before any professional.","exampleCN":"一位澳大利亚业余天文学家比任何职业的都早发现了一颗新小行星。","why":"Amateur astronomers can out-professionals when the sky is dark and the target is faint.","whyCN":"业余天文学家能超过职业的，特别是在天空漆黑、目标又暗的时候。"},{"no":"03","title":"Observational vs theoretical","titleCN":"观测 vs 理论","definition":"subspecialties: observational astronomers collect data; theoretical astronomers build models","definitionCN":"子专业：观测天文学家收集数据，理论天文学家建立模型","example":"She is an observational astronomer who specialises in measuring exoplanet sizes.","exampleCN":"她是专门测量系外行星大小的观测天文学家。","why":"Astronomy has the classic split between those who gather evidence and those who explain it.","whyCN":"天文学有经典的分工：收集证据的人和解释证据的人。"},{"no":"04","title":"Historic astronomers","titleCN":"历史上的天文学家","definition":"people across cultures who studied the sky before modern science, including Copernicus, Galileo, Kepler, Tycho Brahe","definitionCN":"现代科学之前研究天空的跨文化人物，如哥白尼、伽利略、开普勒、第谷","example":"Ancient Arab astronomers gave us most of the star names we still use today.","exampleCN":"古代阿拉伯天文学家给了我们今天仍在使用的大部分星名。","why":"Historic astronomers are part of the long tradition that modern astronomy builds on.","whyCN":"历史天文学家是现代天文学所依赖的悠久传统的一部分。"},{"no":"05","title":"Astronomer vs astrophysicist","titleCN":"天文学家 vs 天体物理学家","definition":"the boundaries blur; astrophysicists study the physics of celestial objects, astronomers can work in observation or theory broadly","definitionCN":"边界模糊：天体物理学家研究天体物理；天文学家可广泛做观测或理论","example":"Many astronomers today are also astrophysicists — the overlap is large.","exampleCN":"今天许多天文学家也是天体物理学家——重叠很大。","why":"Both -ist professions share the astron- root, but astrophysicists explicitly study the 'physics' part.","whyCN":"两种 -ist 职业共享 astron- 词根，但 astrophysicist 明确研究 physics 那部分。"},{"no":"06","title":"Astronomer as public scientist","titleCN":"作为公共科学家的天文学家","definition":"many astronomers are active science communicators, appearing in documentaries and public talks","definitionCN":"许多天文学家是活跃的科学传播者，出现在纪录片和公共演讲里","example":"The astronomer is a regular on late-night science shows.","exampleCN":"这位天文学家是深夜科学节目的常客。","why":"Astronomy has broad public appeal — everyone looks up — so astronomers are often the face of science.","whyCN":"天文学有广泛公众吸引力——人人抬头看——所以天文学家常成为科学的脸面。"},{"no":"07","title":"Astronomer at a research facility","titleCN":"科研机构里的天文学家","definition":"a staff member of an observatory, space agency or research institute, handling data across projects","definitionCN":"天文台、航天机构或研究所的职员，处理跨项目的数据","example":"The observatory employs 12 astronomers to run its flagship telescope.","exampleCN":"这座天文台雇了 12 位天文学家运营它的旗舰望远镜。","why":"Big science requires teams, so astronomers work as staff rather than as lone geniuses.","whyCN":"大科学需要团队，所以天文学家是作为职员工作，不是独行天才。"},{"no":"08","title":"Children / dreamers using the word","titleCN":"孩子或梦想家的用法","definition":"used informally for anyone fascinated by the sky, not just qualified scientists","definitionCN":"非正式地指任何对天空着迷的人，不只合格科学家","example":"As a child I wanted to be an astronomer; now I just look up from the balcony.","exampleCN":"小时候我想当天文学家；现在就从阳台上抬头看看。","why":"The word carries wonder, so it's used by dreamers as well as by specialists.","whyCN":"这个词带着浪漫感，所以梦想家和专业人士都用。"}],"etymology":{"intro":{"en":"astronomer adds the English -er agent suffix to astronomy, which itself comes from Greek astron (star) + nomos (law).","cn":"astronomer 在 astronomy 上加英语 -er 施事后缀；astronomy 本身来自希腊 astron（星）+ nomos（法）。"},"items":[{"era":"GREEK","en":"Greek astronomos meant 'one versed in the laws of stars'.","cn":"希腊语 astronomos 意为「精通星辰之法的人」。"},{"era":"LATIN","en":"Latin astronomus was borrowed directly, meaning 'an astronomer'.","cn":"拉丁语直接借入 astronomus，意为「天文学家」。"},{"era":"MIDDLE ENGLISH","en":"Middle English astronomer (14th century) came via Old French astronomier.","cn":"中古英语 astronomer（14 世纪）经古法语 astronomier 而来。"},{"era":"EARLY MODERN","en":"The spelling settled to astronomer, matching astronom- + -er.","cn":"拼写固定为 astronomer，对齐 astronom- + -er。"},{"era":"20TH C SPECIALISATION","en":"As astronomy split into subfields, astronomer kept its broad sense while astrophysicist and cosmologist became narrower terms.","cn":"当 astronomy 分成子学科时，astronomer 保持广义，而 astrophysicist 和 cosmologist 变得更窄。"},{"era":"TODAY","en":"Professional, amateur, historic and popular senses all remain active.","cn":"职业、业余、历史、大众的义项今天都仍在使用。"}]},"similar":{"note":{"en":"Group one shares the astron- root with -er / -ist professions; group two are other celestial professionals.","cn":"第一组共享 astron- 词根的 -er / -ist 职业；第二组是其他天体领域的专业人士。"},"groups":[{"heading":"SAME ROOT -ER / -IST PROFESSIONS","entries":[{"word":"astronomer","ipa":"/əˈstrɒnəmər/","tag":"broad","definition":"General term for someone who studies the sky.","definitionCN":"泛指研究天空的人。"},{"word":"astrophysicist","ipa":"/ˌæstrəʊˈfɪzɪsɪst/","tag":"specific","definition":"Someone who studies the physics of celestial bodies; subset of astronomer.","definitionCN":"研究天体物理的人；astronomer 的子集。"},{"word":"cosmologist","ipa":"/kɒzˈmɒlədʒɪst/","tag":"subfield","definition":"Astronomer who studies the origin and structure of the whole universe.","definitionCN":"研究整个宇宙起源和结构的天文学家。"},{"word":"astrobiologist","ipa":"/ˌæstrəʊbaɪˈɒlədʒɪst/","tag":"cross-discipline","definition":"Studies life in the universe; not strictly an astronomer.","definitionCN":"研究宇宙中的生命；严格说不算 astronomer。"}]},{"heading":"RELATED PROFESSIONS","entries":[{"word":"astronaut","ipa":"/ˈæstrənɔːt/","tag":"space travel","definition":"Flies spacecraft; not a scientist, though many have astronomy backgrounds.","definitionCN":"驾驶航天器的；不是科学家，虽然很多有天文背景。"},{"word":"astrologer","ipa":"/əˈstrɒlədʒər/","tag":"not science","definition":"Uses celestial positions for divination; not a scientist.","definitionCN":"用天体位置占卜；不是科学家。"},{"word":"space scientist","ipa":"/speɪs ˈsaɪəntɪst/","tag":"broad","definition":"Bigger category including astronomers, planetary scientists, etc.","definitionCN":"更大的类别，包括天文学家、行星科学家等。"},{"word":"observatory director","ipa":"/əbˈzɜːrvətɔːri dəˈrɛktər/","tag":"administrative","definition":"Often an astronomer by training who manages the facility.","definitionCN":"通常是训练有素的天文学家，同时管理天文台。"}]}]},"mnemonics":{"normalIntro":{"en":"An astronomer is someone who does astronomy.","cn":"An astronomer 就是做 astronomy 的人。"},"normal":[{"en":"astronomy + -er = astronomer, just like teacher = teach + -er.","cn":"astronomy + -er = astronomer，就像 teacher = teach + -er。"},{"en":"Astronomers use telescopes; astrologers use horoscopes.","cn":"Astronomers 用望远镜；astrologers 用星盘。"},{"en":"Amateur astronomers find comets too — you don't need a PhD.","cn":"业余天文学家也能发现彗星——不一定要博士。"},{"en":"Edwin Hubble is the astronomer after whom the telescope is named.","cn":"Edwin Hubble 就是哈勃望远镜名字的那位 astronomer。"},{"en":"The astronomer stays up all night because the sky is darkest then.","cn":"天文学家熬夜因为那时天空最黑。"}],"abstract":[{"en":"A single person in the dark, looking up through glass at light that left a star before the Earth was born.","cn":"黑暗中的一个人，透过玻璃看着早在地球诞生前就离开恒星的光。"},{"en":"A notebook full of numbers, a red headlamp, cold coffee at 3am.","cn":"一本写满数字的笔记本、红色头灯、凌晨三点的冷咖啡。"},{"en":"Tiny, alone, and looking upward out of sheer habit.","cn":"微小、孤独、纯粹出于习惯地向上看。"}]},"examples":[{"en":"The astronomer's paper on black hole imaging won the biggest prize in physics that year.","cn":"这位天文学家关于黑洞成像的论文那年拿了物理领域最大的奖。"},{"en":"My cousin is an amateur astronomer who drives to the desert every new moon.","cn":"我表弟是业余天文学家，每个新月都开车去沙漠。"},{"en":"Astronomers from 20 nations collaborated to build the Event Horizon Telescope.","cn":"20 个国家的天文学家合作建了事件视界望远镜。"}],"dict_mnemonic":{"note":"施事后缀","text":"astronomy（天文学）+ -er（做...的人）= 天文学家","word":"astronomer"},"root":"astron + nomos → astronomy → + -er → astronomer。","sensesIntro":{"en":"Eight senses describe who astronomers are: professional, amateur, observational, theoretical, historic, boundary-vs-astrophysicist, public communicators, and dreamers.","cn":"八个义项讲 astronomer 是谁：职业的、业余的、观测的、理论的、历史上的、与天体物理学家的边界、公共传播者、梦想家。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lone figure at a telescope eyepiece, lit only by a faint red lamp and the stars overhead.","cn":"核心意象：目镜前一个孤独的身影，只有微弱红灯和头顶的星光照着。"},"chain":["PROFESSIONAL","AMATEUR","OBSERVATIONAL","THEORETICAL","HISTORIC","PUBLIC SCIENTIST"],"branches":[{"senses":"01 · 07","en":"PROFESSIONAL / STAFF","cn":"职业 / 机构"},{"senses":"02","en":"AMATEUR","cn":"业余"},{"senses":"03","en":"SUBSPECIALTIES","cn":"子专业"},{"senses":"04","en":"HISTORIC","cn":"历史"},{"senses":"05 · 06 · 08","en":"BOUNDARY / COMMUNICATION / DREAM","cn":"边界 / 科普 / 梦想"}]},"affixes":{"intro":{"en":"astronomer is astronomy + -er; the -er suffix turns a science name into the person who practises it.","cn":"astronomer 就是 astronomy + -er；-er 后缀把一门科学变成做它的人。"},"latinIntro":{"en":"The astron- root is Greek; -er is English but has Latin cognate -or (as in actor).","cn":"astron- 来自希腊；-er 是英语但有拉丁同源 -or（如 actor）。"},"items":[{"word":"astronomy","structure":"astron- + -nomy","meaning":"the science","meaningCN":"天文学","example":"study astronomy","exampleCN":"学习天文学"},{"word":"astronomer","structure":"astronomy + -er","meaning":"one who does astronomy","meaningCN":"天文学家","example":"professional astronomer","exampleCN":"职业天文学家"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"senior astrophysicist","exampleCN":"资深天体物理学家"},{"word":"cosmologist","structure":"cosmology + -ist","meaning":"one who does cosmology","meaningCN":"宇宙学家","example":"leading cosmologist","exampleCN":"顶尖宇宙学家"},{"word":"astrobiologist","structure":"astrobiology + -ist","meaning":"one who does astrobiology","meaningCN":"天体生物学家","example":"astrobiologist at NASA","exampleCN":"NASA 天体生物学家"},{"word":"astronaut","structure":"astro- + nautes","meaning":"star sailor","meaningCN":"宇航员","example":"experienced astronaut","exampleCN":"经验丰富的宇航员"},{"word":"astronomical","structure":"astronom- + -ical","meaning":"relating to astronomy","meaningCN":"天文学的；极大的","example":"astronomical cost","exampleCN":"天文数字的成本"},{"word":"astronomically","structure":"astronomical + -ly","meaning":"in an astronomical way","meaningCN":"天文地；巨大地","example":"astronomically high","exampleCN":"天文级地高"},{"word":"astronautics","structure":"astronaut + -ics","meaning":"science of space flight","meaningCN":"航天学","example":"degree in astronautics","exampleCN":"航天学位"}],"latinEntries":[]}},{"word":"astrophysics","ipa_uk":"/ˌæstrəʊˈfɪzɪks/","ipa_us":"/ˌæstrəˈfɪzɪks/","definition_zh":"天体物理学","definition_en":"the branch of astronomy that studies the physical properties of celestial bodies","core_image":"一张恒星内部结构剖面示意图：核反应区、辐射层、对流层","scene":"系主任在新生大会上说：Astrophysics asks how stars shine, how black holes form, and whether we're alone.","sceneCN":"这里指「天体物理这个学科」（第1个义项：天文学下研究天体物理性质的子学科）；句意为天体物理追问恒星如何发光、黑洞如何形成、我们是否孤独。","pos":[{"tag":"n.","zh":"天体物理学（不可数）"}],"collocations":[{"phrase":"theoretical astrophysics","zh":"理论天体物理"},{"phrase":"observational astrophysics","zh":"观测天体物理"},{"phrase":"high-energy astrophysics","zh":"高能天体物理"},{"phrase":"space astrophysics","zh":"空间天体物理"},{"phrase":"cosmic astrophysics","zh":"宇宙天体物理"},{"phrase":"pursue astrophysics","zh":"攻读天体物理"}],"forms":[{"label":"不可数名词","form":"无复数"}],"derivatives":[{"word":"astrophysical","pos":"adj.","zh":"天体物理的"},{"word":"astrophysicist","pos":"n.","zh":"天体物理学家"},{"word":"astronomy","pos":"n.","zh":"天文学（上一级学科）"},{"word":"physics","pos":"n.","zh":"物理学（共享根）"},{"word":"astrobiology","pos":"n.","zh":"天体生物学"}],"senses":[{"no":"01","title":"The interdisciplinary science itself","titleCN":"天体物理作为跨学科的学科","definition":"combines physics and astronomy to explain the structure, evolution and properties of stars, galaxies and the universe","definitionCN":"结合物理和天文学，解释恒星、星系和宇宙的结构、演化和性质","example":"Astrophysics asks questions both physics and astronomy alone cannot answer.","exampleCN":"天体物理问的问题单独物理或天文都答不了。","why":"astrophysics is 'astro' (sky) + 'physics' — physics applied to everything in the sky.","whyCN":"astrophysics 就是 astro（天空）+ physics —— 用到天上的一切的物理。"},{"no":"02","title":"Inside stars: stellar structure","titleCN":"恒星内部结构","definition":"the study of what goes on inside stars, from nuclear fusion in the core to convection at the surface","definitionCN":"研究恒星内部发生什么，从核心核聚变到表面对流","example":"Astrophysics predicts that our Sun will swell into a red giant in five billion years.","exampleCN":"天体物理预言我们的太阳五十亿年后会膨胀成红巨星。","why":"Without astrophysics, we would not know why stars shine or how long they live.","whyCN":"没有天体物理我们不知道恒星为什么发光、能活多久。"},{"no":"03","title":"Black holes, neutron stars and exotic objects","titleCN":"黑洞、中子星等奇特天体","definition":"objects where extreme gravity or density demands both relativity and quantum mechanics","definitionCN":"极端引力或密度的天体，需要同时用相对论和量子力学","example":"Gravitational wave astronomy has become a powerful new tool for astrophysics.","exampleCN":"引力波天文学已成为天体物理强大的新工具。","why":"These objects were first predicted by theory, then later observed — the classic astrophysics cycle.","whyCN":"这些天体先由理论预言，后被观测到——典型的天体物理循环。"},{"no":"04","title":"Origin of the universe: Big Bang and cosmology","titleCN":"宇宙起源：大爆炸与宇宙学","definition":"the branch of astrophysics that studies the beginning and large-scale structure of the cosmos","definitionCN":"天体物理里研究宇宙起源和大尺度结构的分支","example":"Cosmic microwave background radiation is the oldest evidence in astrophysics.","exampleCN":"宇宙微波背景辐射是天体物理里最古老的证据。","why":"This branch crosses into cosmology; many cosmologists are trained as astrophysicists.","whyCN":"这个分支跨到宇宙学；许多宇宙学家也是天体物理学家出身。"},{"no":"05","title":"Planetary and solar system physics","titleCN":"行星与太阳系物理","definition":"the physics of planets, moons, asteroids and comets, including their atmospheres and interiors","definitionCN":"行星、卫星、小行星、彗星的物理，包括它们的大气和内部","example":"Astrophysics explains why Jupiter has bands and why Mars lost its atmosphere.","exampleCN":"天体物理解释木星为什么有条纹、火星为什么失去了大气。","why":"This subfield overlaps with planetary science and geophysics of other worlds.","whyCN":"这个子学科和行星科学、其他行星的地球物理重叠。"},{"no":"06","title":"Astrophysical research tools","titleCN":"天体物理研究工具","definition":"telescopes across the electromagnetic spectrum: radio, infrared, optical, UV, X-ray, gamma-ray","definitionCN":"覆盖整个电磁波谱的望远镜：射电、红外、光学、紫外、X 射线、伽马射线","example":"The event horizon telescope was a global effort to produce the first black hole image.","exampleCN":"事件视界望远镜是全球合力，产出了首张黑洞图像。","why":"Each wavelength tells us different things; no single telescope sees the full picture.","whyCN":"每个波长告诉我们不同的事；没有一台望远镜能看全图。"},{"no":"07","title":"Astrophysics vs astronomy","titleCN":"天体物理 vs 天文学","definition":"astronomy is the broader study; astrophysics is the part that explains celestial behaviour using physics","definitionCN":"天文学是更广义的研究；天体物理是其中用物理解释天体行为的部分","example":"All astrophysicists are astronomers, but not all astronomers are astrophysicists.","exampleCN":"所有天体物理学家都是天文学家，但不是所有天文学家都是天体物理学家。","why":"The -physics suffix says: here, we use the laws of physics to understand the sky.","whyCN":"-physics 后缀说：这里我们用物理定律理解天空。"},{"no":"08","title":"Careers in astrophysics","titleCN":"天体物理的职业","definition":"university research, observatory work, space agency missions, scientific computing","definitionCN":"大学科研、天文台工作、航天任务、科学计算","example":"Many astrophysicists spend half their time writing code and half writing papers.","exampleCN":"许多天体物理学家一半时间写代码一半时间写论文。","why":"Modern astrophysics is as much computer science and statistics as it is physics.","whyCN":"现代天体物理既是物理也是计算机科学和统计。"}],"etymology":{"intro":{"en":"astrophysics is a compound: Greek astron (star) + English physics (from Greek physikos 'natural'). It was coined in the mid-19th century.","cn":"astrophysics 是复合词：希腊 astron（星）+ 英语 physics（来自希腊 physikos「自然的」）。19 世纪中期造词。"},"items":[{"era":"COINED","en":"The term was coined in the 1860s as astronomy became mathematical physics.","cn":"这个词在 1860 年代天文学变成数学物理时被造出来。"},{"era":"GREEK ROOTS","en":"astron (star) + physikos (natural, of nature) via physics (natural science).","cn":"astron（星）+ physikos（自然的）→ physics（自然科学）。"},{"era":"20TH C GROWTH","en":"The field exploded in the 20th century with nuclear physics explaining starlight and general relativity explaining gravity.","cn":"20 世纪核物理解释了星光、广义相对论解释了引力，这个领域爆炸式增长。"},{"era":"SPACE AGE","en":"Space telescopes launched from the 1960s gave astrophysicists data no ground observatory could match.","cn":"1960 年代起发射的太空望远镜给天体物理学家带来地面天文台无法比拟的数据。"},{"era":"21ST C BREAKTHROUGHS","en":"Gravitational waves, exoplanets and black hole imaging have defined the 21st century of astrophysics.","cn":"引力波、系外行星、黑洞成像定义了 21 世纪的天体物理。"},{"era":"TODAY","en":"Astrophysics is the dominant theoretical and experimental branch of modern astronomy.","cn":"天体物理是现代天文学里占主导的理论和实验分支。"}]},"similar":{"note":{"en":"Group one shares the astro- prefix; group two compares astrophysics to parent and sibling disciplines.","cn":"第一组共享 astro- 前缀；第二组把天体物理和其母体及兄弟学科对比。"},"groups":[{"heading":"SAME astro- PREFIX","entries":[{"word":"astrophysicist","ipa":"/ˌæstrəʊˈfɪzɪsɪst/","tag":"person","definition":"One who works in astrophysics.","definitionCN":"做天体物理的人。"},{"word":"astrophysical","ipa":"/ˌæstrəʊˈfɪzɪkl/","tag":"adjective","definition":"Of or relating to astrophysics.","definitionCN":"与天体物理有关的。"},{"word":"astrochemistry","ipa":"/ˌæstrəʊˈkemɪstri/","tag":"sibling","definition":"Chemistry in space; not exactly physics but shares astro-.","definitionCN":"太空化学；不完全是物理但共享 astro-。"},{"word":"astrobiology","ipa":"/ˌæstrəʊbaɪˈɒlədʒi/","tag":"sibling","definition":"Biology in space; searches for extraterrestrial life.","definitionCN":"太空生物；寻找地外生命。"}]},{"heading":"PARENT / SIBLING FIELDS","entries":[{"word":"astronomy","ipa":"/əˈstrɒnəmi/","tag":"parent","definition":"The broader parent discipline; all astrophysicists are astronomers.","definitionCN":"更广义的母学科；所有天体物理学家都是天文学家。"},{"word":"physics","ipa":"/ˈfɪzɪks/","tag":"other parent","definition":"The science of matter and energy; astrophysics applies physics to space.","definitionCN":"研究物质和能量的科学；天体物理把物理用到太空。"},{"word":"cosmology","ipa":"/kɒzˈmɒlədʒi/","tag":"overlap","definition":"Study of the whole universe; strongly overlaps with astrophysics.","definitionCN":"研究整个宇宙；与天体物理强烈重叠。"},{"word":"planetary science","ipa":"/ˈplænətri ˈsaɪəns/","tag":"subfield","definition":"Broader than planetary astrophysics; includes geology and chemistry of other worlds.","definitionCN":"比行星天体物理更宽；包括其他行星的地质和化学。"}]}]},"mnemonics":{"normalIntro":{"en":"Astrophysics = physics applied to the stars.","cn":"Astrophysics = 用到恒星上的物理。"},"normal":[{"en":"astro (stars) + physics = astrophysics.","cn":"astro（星）+ physics = 天体物理。"},{"en":"All astrophysicists use physics to explain what goes on up there.","cn":"所有天体物理学家用物理解释天上发生了什么。"},{"en":"Black holes are an astrophysics question; astrology is not.","cn":"黑洞是天体物理问题；占星不是。"},{"en":"The Event Horizon Telescope gave astrophysics its first black hole picture.","cn":"事件视界望远镜给了天体物理首张黑洞照片。"},{"en":"Astrophysics needs both telescopes (data) and equations (models).","cn":"天体物理既需要望远镜（数据）也需要方程（模型）。"}],"abstract":[{"en":"A star's interior: a furnace of pressure and heat, held together by gravity against its own explosion.","cn":"恒星内部：压力和热量的熔炉，被引力拉住不让它自己炸开。"},{"en":"Equations on a chalkboard pointing outward into black space.","cn":"黑板上的方程指向外面黑色的空间。"},{"en":"Light that has travelled billions of years arriving at a mirror on a mountain top.","cn":"飘了几十亿年的光落在山顶的镜面上。"}]},"examples":[{"en":"Her PhD project combined astrophysics and machine learning to find exoplanets in old data.","cn":"她的博士项目结合天体物理和机器学习在旧数据里找系外行星。"},{"en":"Astrophysics teaches us that every element in our bodies was forged inside a star.","cn":"天体物理告诉我们身体里的每个元素都曾在恒星内部被锻造过。"},{"en":"Gravitational wave observatories have opened an entirely new window on astrophysics.","cn":"引力波观测站给天体物理打开了一扇全新的窗。"}],"dict_mnemonic":{"note":"复合词记忆","text":"astro（星）+ physics（物理）= 天体物理","word":"astrophysics"},"root":"astron（希腊语，星）+ physikos（自然的）→ physics → astrophysics。","sensesIntro":{"en":"Eight senses map the subject matter of astrophysics: the whole field, inside stars, exotic objects, cosmology, planets, tools, boundary with astronomy, and careers.","cn":"八个义项讲天体物理的研究对象：整个学科、恒星内部、奇特天体、宇宙学、行星、研究工具、与 astronomy 的边界、职业。"},"semanticMap":{"core":{"en":"CORE IMAGE: a computer simulation of a black hole warping space around it, light bending in arcs.","cn":"核心意象：黑洞扭曲周围空间的计算机模拟，光弯成弧形。"},"chain":["WHOLE FIELD","STELLAR INTERIORS","EXOTIC OBJECTS","ORIGIN OF UNIVERSE","PLANETARY PHYSICS","TOOLS & BOUNDARIES"],"branches":[{"senses":"01","en":"THE FIELD","cn":"学科整体"},{"senses":"02 · 03","en":"STELLAR / EXOTIC","cn":"恒星 / 奇特天体"},{"senses":"04","en":"COSMOLOGY","cn":"宇宙学"},{"senses":"05","en":"PLANETARY","cn":"行星"},{"senses":"06 · 07 · 08","en":"TOOLS / BOUNDARY / CAREERS","cn":"工具 / 边界 / 职业"}]},"affixes":{"intro":{"en":"astrophysics is a straightforward compound: astro- (Greek 'star') + physics (natural science).","cn":"astrophysics 是直接的复合词：astro-（希腊语「星」）+ physics（自然科学）。"},"latinIntro":{"en":"Both astron and physikos are Greek; Latin 'physics' was borrowed from Greek physica.","cn":"astron 和 physikos 都是希腊语；拉丁语的 physics 从希腊 physica 借入。"},"items":[{"word":"astron","structure":"Greek root","meaning":"star","meaningCN":"星","example":"astron- prefix","exampleCN":"astron- 前缀"},{"word":"physics","structure":"Greek physikos + -ics","meaning":"science of nature","meaningCN":"物理学","example":"study physics","exampleCN":"学习物理"},{"word":"astrophysics","structure":"astro- + physics","meaning":"physics of stars","meaningCN":"天体物理学","example":"astrophysics research","exampleCN":"天体物理研究"},{"word":"astrophysical","structure":"astrophysics + -al","meaning":"relating to astrophysics","meaningCN":"天体物理的","example":"astrophysical model","exampleCN":"天体物理模型"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"senior astrophysicist","exampleCN":"资深天体物理学家"},{"word":"astrochemistry","structure":"astro- + chemistry","meaning":"chemistry of stars","meaningCN":"天体化学","example":"astrochemistry lab","exampleCN":"天体化学实验室"},{"word":"astrobiology","structure":"astro- + biology","meaning":"biology in space","meaningCN":"天体生物学","example":"astrobiology conference","exampleCN":"天体生物学会议"},{"word":"astrolinguistics","structure":"astro- + linguistics","meaning":"search for extraterrestrial languages","meaningCN":"寻找地外语言的研究","example":"SETI uses astrolinguistics","exampleCN":"SETI 用天体语言学"},{"word":"astronomy","structure":"astron- + -nomy","meaning":"broader science of stars","meaningCN":"天文学","example":"intro astronomy","exampleCN":"天文学入门"},{"word":"cosmology","structure":"cosmos + -logy","meaning":"study of the universe","meaningCN":"宇宙学","example":"cosmology course","exampleCN":"宇宙学课程"}],"latinEntries":[]}},{"word":"astrophysical","ipa_uk":"/ˌæstrəʊˈfɪzɪkl/","ipa_us":"/ˌæstrəˈfɪzɪkl/","definition_zh":"天体物理的","definition_en":"relating to astrophysics or the physical properties of celestial bodies","core_image":"NASA 发布的星云物理模型截图，标注着温度、密度、磁场箭头","scene":"课本里说：The Doppler effect is an astrophysical tool that lets us measure whether distant galaxies are approaching or receding.","sceneCN":"这里指「与天体物理相关的」（第1个义项：属于天体物理的）；句意为多普勒效应是天体物理的工具，让我们能测遥远星系是在靠近还是远离。","pos":[{"tag":"adj.","zh":"天体物理的；与天体物理有关的"}],"collocations":[{"phrase":"astrophysical model","zh":"天体物理模型"},{"phrase":"astrophysical observation","zh":"天体物理观测"},{"phrase":"astrophysical property","zh":"天体物理性质"},{"phrase":"astrophysical tool","zh":"天体物理工具"},{"phrase":"astrophysical origin","zh":"天体物理起源"},{"phrase":"astrophysical data","zh":"天体物理数据"}],"forms":[{"label":"副词","form":"astrophysically"}],"derivatives":[{"word":"astrophysics","pos":"n.","zh":"天体物理学"},{"word":"astrophysicist","pos":"n.","zh":"天体物理学家"},{"word":"astronomical","pos":"adj.","zh":"天文学的；极大的（近义）"},{"word":"cosmological","pos":"adj.","zh":"宇宙学的"},{"word":"theoretical","pos":"adj.","zh":"理论的（共享学科性质）"}],"senses":[{"no":"01","title":"Of or relating to astrophysics","titleCN":"与天体物理有关的","definition":"the core technical adjective; anything that belongs to astrophysics is astrophysical","definitionCN":"核心技术形容词：属于天体物理的任何事物都是 astrophysical","example":"The course covered the main astrophysical tools used to study black holes.","exampleCN":"课程覆盖了研究黑洞用到的主要天体物理工具。","why":"This is the plain adjective form: astrophysics + -al = astrophysical.","whyCN":"就是普通形容词形式：astrophysics + -al = astrophysical。"},{"no":"02","title":"Physical properties of celestial bodies","titleCN":"天体的物理性质","definition":"not only the science, but the actual physical properties of stars, planets, galaxies","definitionCN":"不只是学科，也指恒星、行星、星系实际的物理性质","example":"Astronomers can now measure the astrophysical properties of exoplanets.","exampleCN":"天文学家现在能测量系外行星的物理性质。","why":"The adjective describes both the science and the reality the science studies.","whyCN":"这个形容词同时描述学科和学科所研究的现实。"},{"no":"03","title":"Astrophysical models and theories","titleCN":"天体物理模型与理论","definition":"mathematical models that predict how celestial bodies should behave under the laws of physics","definitionCN":"预言天体在物理定律下如何行为的数学模型","example":"Astrophysical models correctly predicted the existence of neutron stars long before they were observed.","exampleCN":"天体物理模型在观测之前很久就正确预言了中子星的存在。","why":"Astrophysical models are the bridge between physics equations and what astronomers see.","whyCN":"天体物理模型是物理方程和天文学家所观测之间的桥。"},{"no":"04","title":"Astrophysical origin of elements","titleCN":"元素的天体物理起源","definition":"nucleosynthesis: how each element was forged in stars, supernovae or the Big Bang","definitionCN":"核合成：每种元素如何在恒星、超新星或大爆炸中被锻造出来","example":"Gold and platinum come from neutron star mergers, an astrophysical origin only recently confirmed.","exampleCN":"金和铂来自中子星并合——一个最近才被证实的天体物理起源。","why":"Every atom heavier than iron needs an astrophysical explanation.","whyCN":"每个比铁重的原子都需要一个天体物理解释。"},{"no":"05","title":"Astrophysical observation and data","titleCN":"天体物理观测与数据","definition":"the data that telescopes and spacecraft collect, before interpretation by theory","definitionCN":"望远镜和航天器收集的数据，还没经理论解释","example":"The astrophysical data from the Hubble telescope has reshaped every subfield of astronomy.","exampleCN":"哈勃望远镜的天体物理数据重塑了天文学每个子学科。","why":"Astrophysical data is the raw material that astrophysicists spend careers interpreting.","whyCN":"天体物理数据是天体物理学家花一辈子解释的原材料。"},{"no":"06","title":"Astrophysical vs astronomical","titleCN":"天体物理的 vs 天文的","definition":"astronomical means relating to astronomy broadly; astrophysical means using physics specifically","definitionCN":"astronomical 指广义的天文学；astrophysical 特指用物理的","example":"The observations were astronomical; the interpretation was astrophysical.","exampleCN":"观测是天文的；解释是天体物理的。","why":"The narrower -physics suffix signals that here, physics is doing the heavy lifting.","whyCN":"更窄的 -physics 后缀说明这里主要靠物理来干活。"},{"no":"07","title":"Astrophysical scale of the universe","titleCN":"宇宙的天体物理尺度","definition":"used for scales, temperatures and energies that appear only in astronomical contexts","definitionCN":"用于只在天文语境下出现的尺度、温度和能量","example":"Black hole mergers release astrophysical amounts of energy in a fraction of a second.","exampleCN":"黑洞并合在一瞬间释放天体物理级别的能量。","why":"Like astronomical, astrophysical can describe scale, though more often tied to physics.","whyCN":"和 astronomical 一样，astrophysical 也能描述尺度，但更常跟物理挂钩。"},{"no":"08","title":"In non-scientific writing","titleCN":"非科学写作中的用法","definition":"sometimes used loosely to mean 'immense' or 'cosmic' in popular science or journalism","definitionCN":"偶尔在科普或新闻里松散地表示「巨大的」或「宇宙级的」","example":"The task ahead was astrophysical in scale — rebuilding an entire scientific field.","exampleCN":"前方的任务是天体物理级的——重建整个科学领域。","why":"Writers reach for astrophysical when astronomical feels too mundane or too tied to naked-eye observing.","whyCN":"当 astronomical 觉得太普通、太口语化时，写作者就用 astrophysical。"}],"etymology":{"intro":{"en":"astrophysical simply adds the -al adjective suffix to astrophysics, itself a 19th-century compound of astro- + physics.","cn":"astrophysical 就是 astrophysics 加 -al 形容词后缀；astrophysics 本身是 19 世纪造的 astro- + physics 复合词。"},"items":[{"era":"19TH C COINAGE","en":"astrophysics was coined in the 1860s; astrophysical as its adjective form followed within a decade.","cn":"astrophysics 1860 年代造词；其形容词 astrophysical 十年内就出现了。"},{"era":"GREEK ROOTS","en":"Both astron 'star' and physikos 'natural' are Greek; the compound is modern.","cn":"astron「星」和 physikos「自然的」都是希腊语；复合是现代的。"},{"era":"20TH C USE","en":"Became common in textbooks and research papers in the mid-20th century.","cn":"20 世纪中期在教科书和科研论文里变得常见。"},{"era":"EXTENSION","en":"The 'cosmic scale' sense developed alongside the growth of popular science writing.","cn":"「宇宙级尺度」的义项随着科普写作的成长发展起来。"},{"era":"TODAY","en":"Both scientific and loose popular senses remain in use.","cn":"科学义和松散的科普义今天都在使用。"},{"era":"RELATED","en":"Compare to astronomical, which has a longer and broader history.","cn":"对比 astronomical——它有更长更广的历史。"}]},"similar":{"note":{"en":"Group one are same-root adjectives; group two are adjectives for astronomical / cosmic scale.","cn":"第一组是同词根的形容词；第二组是表示天文 / 宇宙尺度的形容词。"},"groups":[{"heading":"SAME ROOT ADJECTIVES","entries":[{"word":"astronomical","ipa":"/ˌæstrəˈnɒmɪkl/","tag":"broader","definition":"Relating to astronomy broadly; can mean huge.","definitionCN":"广义的天文学的；可指巨大的。"},{"word":"astrophysical","ipa":"/ˌæstrəʊˈfɪzɪkl/","tag":"physics-specific","definition":"Relating to astrophysics specifically, using physics as the tool.","definitionCN":"特指天体物理的，以物理为工具。"},{"word":"cosmological","ipa":"/ˌkɒzməˈlɒdʒɪkl/","tag":"subset","definition":"Of cosmology; narrower than astrophysical but overlapping.","definitionCN":"宇宙学的；比 astrophysical 窄但有重叠。"},{"word":"theoretical","ipa":"/ˌθɪəˈretɪkl/","tag":"shared property","definition":"Describes models and predictions, whether in astrophysics or elsewhere.","definitionCN":"描述模型和预言，不论在天体物理还是其他学科。"}]},{"heading":"SCALE ADJECTIVES","entries":[{"word":"cosmic","ipa":"/ˈkɒzmɪk/","tag":"informal scale","definition":"Relating to the whole universe; often used loosely for immense scale.","definitionCN":"与整个宇宙有关的；常松散表示极大尺度。"},{"word":"galactic","ipa":"/ɡəˈlæktɪk/","tag":"same field","definition":"Relating to galaxies; can be used figuratively for huge amounts.","definitionCN":"与星系有关的；可比喻巨大数额。"},{"word":"interstellar","ipa":"/ˌɪntəˈstelər/","tag":"astro","definition":"Between stars; used in astrophysics and science fiction.","definitionCN":"恒星之间的；用于天体物理和科幻。"},{"word":"universal","ipa":"/ˌjuːnɪˈvɜːrsl/","tag":"broader","definition":"True everywhere; overlapping with cosmic scale sense.","definitionCN":"无处不真的；与宇宙尺度义项有重叠。"}]}]},"mnemonics":{"normalIntro":{"en":"astrophysical = of astrophysics.","cn":"astrophysical = 天体物理的。"},"normal":[{"en":"astrophysics + -al = astrophysical, just like physics + -al = physical.","cn":"astrophysics + -al = astrophysical，就像 physics + -al = physical。"},{"en":"An astrophysical model is the maths of a star or galaxy.","cn":"天体物理模型就是恒星或星系的数学模型。"},{"en":"Astrophysical observations use telescopes across the electromagnetic spectrum.","cn":"天体物理观测用覆盖整个电磁波谱的望远镜。"},{"en":"Gold has an astrophysical origin — neutron star mergers.","cn":"金有天体物理起源——中子星并合。"},{"en":"The Big Bang is the ultimate astrophysical event.","cn":"大爆炸是终极的天体物理事件。"}],"abstract":[{"en":"An equation that fits perfectly the star's light curve.","cn":"完美拟合恒星光变曲线的一个方程。"},{"en":"Spectrum of a distant galaxy plotted on a chalkboard.","cn":"黑板上画着遥远星系的光谱。"},{"en":"Metal forged in a supernova a billion years ago, now in your necklace.","cn":"十亿年前超新星里锻造的金属，现在在你的项链里。"}]},"examples":[{"en":"The conference focused on astrophysical techniques for measuring dark matter.","cn":"会议聚焦测量暗物质的天体物理技术。"},{"en":"His thesis advanced several astrophysical models of gamma-ray bursts.","cn":"他的论文推进了伽马射线暴的好几个天体物理模型。"},{"en":"Astrophysical observations reveal that most of the universe is dark energy.","cn":"天体物理观测揭示宇宙大部分是暗能量。"}],"dict_mnemonic":{"note":"形容词后缀","text":"astrophysics（天体物理）+ -al（...的）= 天体物理的","word":"astrophysical"},"root":"astrophysics + -al → astrophysical。","sensesIntro":{"en":"Eight senses range from the plain adjective of the science, through physical properties, models, data and origins, to a loose 'cosmic scale' extension.","cn":"八个义项从学科的普通形容词，经过物理性质、模型、数据、起源，到松散的「宇宙级尺度」延伸。"},"semanticMap":{"core":{"en":"CORE IMAGE: a star's light bent by a massive galaxy cluster, a textbook illustration of an astrophysical effect.","cn":"核心意象：恒星的光被巨大星系团弯曲，天体物理效应的教科书插图。"},"chain":["THE SCIENCE","PHYSICAL PROPERTIES","MODELS","ORIGIN OF ELEMENTS","OBSERVATION DATA","BOUNDARY / SCALE"],"branches":[{"senses":"01","en":"THE FIELD: work that belongs to astrophysics as a discipline.","cn":"学科归属：属于天体物理这门学科的工作。"},{"senses":"02 · 04 · 05","en":"OBJECTS, PROCESSES AND DATA: properties of stars and galaxies, the forging of elements, telescope readings.","cn":"对象、过程与数据：恒星与星系的性质、元素的生成、望远镜读数。"},{"senses":"03","en":"MODELS: mathematics that predicts how celestial bodies must behave.","cn":"模型：预测天体必然如何运动的数学。"},{"senses":"06 · 07","en":"BOUNDARY AND SCALE: against astronomy, and magnitudes no earthly lab reaches.","cn":"边界与尺度：与天文学的界限，以及地面实验室达不到的量级。"},{"senses":"08","en":"POPULAR USE: a loose word for 'immense' in journalism and popular science.","cn":"流行用法：新闻与科普里松散表示「巨大」的词。"}]},"affixes":{"intro":{"en":"astrophysical simply adds the -al adjective suffix to astrophysics; the root is shared with astronomy.","cn":"astrophysical 就是 astrophysics 加 -al 形容词后缀；词根与 astronomy 共享。"},"latinIntro":{"en":"Greek astron + Greek physikos; -al is Latin -alis.","cn":"希腊 astron + 希腊 physikos；-al 来自拉丁语 -alis。"},"items":[{"word":"astrophysics","structure":"astro- + physics","meaning":"physics of stars","meaningCN":"天体物理学","example":"study astrophysics","exampleCN":"学习天体物理"},{"word":"astrophysical","structure":"astrophysics + -al","meaning":"relating to astrophysics","meaningCN":"天体物理的","example":"astrophysical origin","exampleCN":"天体物理起源"},{"word":"astrophysically","structure":"astrophysical + -ly","meaning":"in an astrophysical way","meaningCN":"天体物理地","example":"astrophysically important","exampleCN":"天体物理上重要的"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"leading astrophysicist","exampleCN":"顶尖天体物理学家"},{"word":"astronomy","structure":"astron- + -nomy","meaning":"broader parent science","meaningCN":"天文学","example":"intro astronomy","exampleCN":"天文学入门"},{"word":"astronomical","structure":"astronom- + -ical","meaning":"of astronomy; huge","meaningCN":"天文学的；极大的","example":"astronomical cost","exampleCN":"天文数字的成本"},{"word":"cosmological","structure":"cosmology + -ical","meaning":"of cosmology","meaningCN":"宇宙学的","example":"cosmological model","exampleCN":"宇宙学模型"},{"word":"cosmic","structure":"cosmos + -ic","meaning":"of the universe","meaningCN":"宇宙的","example":"cosmic event","exampleCN":"宇宙事件"},{"word":"stellar","structure":"Latin stella + -ar","meaning":"of stars","meaningCN":"恒星的","example":"stellar evolution","exampleCN":"恒星演化"},{"word":"galactic","structure":"Greek galaxias + -ic","meaning":"of galaxies","meaningCN":"星系的","example":"galactic centre","exampleCN":"星系中心"}],"latinEntries":[]}},{"word":"astrophysicist","ipa_uk":"/ˌæstrəʊˈfɪzɪsɪst/","ipa_us":"/ˌæstrəˈfɪzɪsɪst/","definition_zh":"天体物理学家","definition_en":"a scientist who works in astrophysics, applying physics to understand celestial bodies","core_image":"一位戴着眼镜、拿着激光笔的女性科学家在会议室里展示黑洞合并的模拟动画","scene":"新闻专访里说：The astrophysicist spent a decade building the telescope that captured the first black hole image.","sceneCN":"这里指「职业是天体物理科学家的人」（第1个义项）；句意为这位天体物理学家花了十年建望远镜拍首张黑洞图。","pos":[{"tag":"n.","zh":"天体物理学家"}],"collocations":[{"phrase":"leading astrophysicist","zh":"顶尖天体物理学家"},{"phrase":"theoretical astrophysicist","zh":"理论天体物理学家"},{"phrase":"observational astrophysicist","zh":"观测天体物理学家"},{"phrase":"senior astrophysicist","zh":"资深天体物理学家"},{"phrase":"become an astrophysicist","zh":"成为天体物理学家"},{"phrase":"collaborating astrophysicists","zh":"合作中的天体物理学家"}],"forms":[{"label":"复数","form":"astrophysicists"}],"derivatives":[{"word":"astrophysics","pos":"n.","zh":"天体物理学"},{"word":"astrophysical","pos":"adj.","zh":"天体物理的"},{"word":"astronomer","pos":"n.","zh":"天文学家（广义）"},{"word":"cosmologist","pos":"n.","zh":"宇宙学家（子专业）"},{"word":"physicist","pos":"n.","zh":"物理学家（另一母体）"}],"senses":[{"no":"01","title":"Professional scientist in astrophysics","titleCN":"职业天体物理学家","definition":"a person with a PhD or equivalent in astrophysics, conducting research at a university, observatory or space agency","definitionCN":"拥有天体物理博士或同等资格的人，在大学、天文台或航天机构做研究","example":"The astrophysicist was awarded a MacArthur fellowship for her work on dark matter.","exampleCN":"这位天体物理学家因为暗物质研究拿到了麦克阿瑟奖。","why":"Like other -ist professions, astrophysicist is the person who practises astrophysics.","whyCN":"和其他 -ist 职业一样，astrophysicist 就是做 astrophysics 的人。"},{"no":"02","title":"Theoretical vs observational","titleCN":"理论 vs 观测","definition":"the two broad camps: theoretical astrophysicists build models; observational astrophysicists run telescopes and analyse data","definitionCN":"两大类：理论天体物理学家建模型；观测天体物理学家运营望远镜、分析数据","example":"She is a theoretical astrophysicist who studies how black holes affect their surroundings.","exampleCN":"她是研究黑洞如何影响周围环境的理论天体物理学家。","why":"The split mirrors the whole field; both groups rely on each other.","whyCN":"这个分工就是整个学科的缩影；两组互相依赖。"},{"no":"03","title":"Astrophysicist vs astronomer","titleCN":"天体物理学家 vs 天文学家","definition":"all astrophysicists are astronomers, but not all astronomers are astrophysicists — the -physics suffix signals the specialised training","definitionCN":"所有天体物理学家都是天文学家，但不是所有天文学家都是天体物理学家——-physics 后缀说明是专门训练过的","example":"Many radio astronomers are not astrophysicists; they collect data for theorists.","exampleCN":"许多射电天文学家不是天体物理学家；他们给理论家收集数据。","why":"The distinction matters for hiring and funding, even if the public uses the words interchangeably.","whyCN":"这个区分在招聘和经费上有意义，哪怕公众把两词通用。"},{"no":"04","title":"Career path to astrophysicist","titleCN":"成为天体物理学家的路径","definition":"physics → PhD in astrophysics → postdoc → faculty or observatory staff; five to ten years of advanced study","definitionCN":"物理本科 → 天体物理博士 → 博士后 → 教职或天文台职员；五到十年的深造","example":"It takes roughly a decade of study and research to become a professional astrophysicist.","exampleCN":"成为职业天体物理学家需要大约十年的学习和研究。","why":"The combined demands of physics, astronomy, computing and statistics make it a long road.","whyCN":"物理、天文、计算、统计都得懂，道路就长。"},{"no":"05","title":"Cosmologists as astrophysicists","titleCN":"宇宙学家作为天体物理学家的子集","definition":"many cosmologists (who study the origin of the universe) are trained astrophysicists","definitionCN":"许多宇宙学家（研究宇宙起源）都是天体物理训练出身","example":"The astrophysicist won the Nobel Prize for discoveries in cosmology.","exampleCN":"这位天体物理学家因为宇宙学发现拿了诺贝尔奖。","why":"Cosmology overlaps heavily with astrophysics, so the titles are often interchangeable.","whyCN":"宇宙学与天体物理重叠很大，所以头衔常可互换。"},{"no":"06","title":"Astrophysicist in industry or private sector","titleCN":"产业界的天体物理学家","definition":"growing roles in aerospace, satellite design, data science and climate modelling","definitionCN":"航天、卫星设计、数据科学和气候建模里越来越多的职位","example":"The aerospace company hired two astrophysicists to model space debris trajectories.","exampleCN":"航天公司雇了两个天体物理学家建模太空碎片轨迹。","why":"Industry values astrophysicists' skills in computing, modelling and working with large datasets.","whyCN":"产业界看重天体物理学家在计算、建模和大数据库工作上的能力。"},{"no":"07","title":"Public-facing astrophysicists","titleCN":"面向公众的天体物理学家","definition":"many become science communicators, appear in documentaries, give public talks","definitionCN":"许多成为科学传播者，出现在纪录片里，给公众做报告","example":"The astrophysicist hosts a weekly podcast about black holes and the universe.","exampleCN":"这位天体物理学家主持每周一期的黑洞和宇宙播客。","why":"Astrophysics captures public imagination; those who can explain it are in demand.","whyCN":"天体物理抓住公众的想象力；能讲明白的人就有市场。"},{"no":"08","title":"Diversity in astrophysics","titleCN":"天体物理领域的多样性","definition":"historically male-dominated, but progress continues with more women and underrepresented groups entering the field","definitionCN":"历史上男性主导，但随着更多女性和代表性不足群体进入，持续取得进步","example":"She is one of a growing number of female astrophysicists leading major space missions.","exampleCN":"她是越来越多主导重大航天任务的女性天体物理学家之一。","why":"Like most STEM fields, astrophysics is actively working to improve diversity.","whyCN":"和大多 STEM 学科一样，天体物理正在积极提升多样性。"}],"etymology":{"intro":{"en":"astrophysicist adds the -ist agent suffix to astrophysics, making it 'one who practises astrophysics'.","cn":"astrophysicist 在 astrophysics 上加 -ist 施事后缀，意为「做天体物理的人」。"},"items":[{"era":"19TH C COINAGE","en":"astrophysics was coined 1860s; astrophysicist followed before 1900.","cn":"astrophysics 1860 年代造词；astrophysicist 在 1900 年前就出现了。"},{"era":"GREEK -IST","en":"The -ist suffix is from Greek -istes, 'one who does'.","cn":"-ist 后缀来自希腊语 -istes「做...的人」。"},{"era":"20TH C SPECIALISATION","en":"As the field grew in the 20th century, astrophysicist became a distinct career from the broader astronomer.","cn":"20 世纪学科成长时，astrophysicist 成为了区别于广义 astronomer 的独立职业。"},{"era":"NOBEL PRIZES","en":"The first Nobel Prize in astrophysics went to Zwicky and Baade indirectly; direct Nobels followed in the 1970s and later.","cn":"天体物理首个诺贝尔奖间接给了 Zwicky 和 Baade；后来 1970 年代起有直接得奖。"},{"era":"TODAY","en":"Around a thousand professional astrophysicists work worldwide.","cn":"全球有约一千名职业天体物理学家。"},{"era":"TREND","en":"More astrophysicists work in data science and industry than ever before.","cn":"今天做数据科学和产业的天体物理学家比以前多了。"}]},"similar":{"note":{"en":"Group one are person roles in the astron- / astro- family; group two are other physics-related -ist professions.","cn":"第一组是 astron- / astro- 家族的人物角色；第二组是其他物理相关的 -ist 职业。"},"groups":[{"heading":"astro- / astron- PROFESSIONS","entries":[{"word":"astrophysicist","ipa":"/ˌæstrəʊˈfɪzɪsɪst/","tag":"physics-specific","definition":"Uses physics to study celestial bodies.","definitionCN":"用物理研究天体的人。"},{"word":"astronomer","ipa":"/əˈstrɒnəmər/","tag":"broader","definition":"General term for someone who studies the sky; astrophysicist is a subset.","definitionCN":"研究天空的人的泛指；astrophysicist 是子集。"},{"word":"cosmologist","ipa":"/kɒzˈmɒlədʒɪst/","tag":"subfield","definition":"Studies the whole universe; typically an astrophysicist by training.","definitionCN":"研究整个宇宙的；通常是天体物理训练出身。"},{"word":"astrobiologist","ipa":"/ˌæstrəʊbaɪˈɒlədʒɪst/","tag":"cross-discipline","definition":"Studies life in space; not strictly an astrophysicist.","definitionCN":"研究太空生命；严格说不算天体物理学家。"}]},{"heading":"RELATED -IST PROFESSIONS","entries":[{"word":"physicist","ipa":"/ˈfɪzɪsɪst/","tag":"other parent","definition":"General practitioner of physics; astrophysicists are a subset.","definitionCN":"一般的物理从业者；astrophysicist 是子集。"},{"word":"astronaut","ipa":"/ˈæstrənɔːt/","tag":"space travel","definition":"Flies spacecraft, not necessarily a scientist.","definitionCN":"驾驶航天器，不一定是科学家。"},{"word":"engineer","ipa":"/ˌendʒɪˈnɪr/","tag":"industry partner","definition":"Builds telescopes and spacecraft that astrophysicists use.","definitionCN":"造天体物理学家用的望远镜和航天器。"},{"word":"mathematician","ipa":"/ˌmæθməˈtɪʃn/","tag":"close collaborator","definition":"Develops the mathematical tools astrophysicists use to model space.","definitionCN":"开发天体物理学家用来建模的数学工具。"}]}]},"mnemonics":{"normalIntro":{"en":"An astrophysicist does astrophysics.","cn":"An astrophysicist 就是做 astrophysics 的人。"},"normal":[{"en":"astrophysics + -ist = astrophysicist, like physics + -ist = physicist.","cn":"astrophysics + -ist = astrophysicist，就像 physics + -ist = physicist。"},{"en":"All astrophysicists are astronomers, but not all astronomers are astrophysicists.","cn":"所有天体物理学家都是天文学家，但不是所有天文学家都是天体物理学家。"},{"en":"The Event Horizon Telescope team included hundreds of astrophysicists.","cn":"事件视界望远镜团队有几百位天体物理学家。"},{"en":"Astrophysicists need both physics and astronomy training.","cn":"天体物理学家需要物理和天文双重训练。"},{"en":"Neil deGrasse Tyson is a famous astrophysicist and science communicator.","cn":"Neil deGrasse Tyson 是著名的天体物理学家和科普人。"}],"abstract":[{"en":"A small face in a big control room, looking up at a wall of monitors.","cn":"一个小脸在一个大控制室里，抬头看一整墙的显示器。"},{"en":"A whiteboard full of equations, a half-finished mug of coffee.","cn":"写满方程的白板、半杯没喝完的咖啡。"},{"en":"Someone who spends their life looking at things that happened before Earth existed.","cn":"一个花一生时间看地球诞生前就发生的事的人。"}]},"examples":[{"en":"The astrophysicist's paper on gravitational waves won the Breakthrough Prize that year.","cn":"这位天体物理学家关于引力波的论文那年拿了突破奖。"},{"en":"Many astrophysicists now work half their time writing code to analyse large datasets.","cn":"许多天体物理学家现在一半时间写代码分析大数据集。"},{"en":"She was the only astrophysicist invited to the panel on future space missions.","cn":"她是唯一被请来参加未来航天任务圆桌的天体物理学家。"}],"dict_mnemonic":{"note":"施事后缀","text":"astrophysics（天体物理）+ -ist（...的人）= 天体物理学家","word":"astrophysicist"},"root":"astro + physics + -ist → astrophysicist。","sensesIntro":{"en":"Eight senses describe the astrophysicist: professional role, theoretical vs observational split, boundary with astronomer, career path, cosmologists, industry roles, public science communication, and diversity.","cn":"八个义项讲 astrophysicist 是谁：职业角色、理论观测分工、与 astronomer 的边界、职业路径、宇宙学家、产业角色、公共科普、多样性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person in a control room at night, reading data on a screen that shows what a telescope saw hours earlier.","cn":"核心意象：夜里控制室里的一个人，读着屏幕上望远镜几小时前看到的数据。"},"chain":["PROFESSIONAL ROLE","THEORETICAL VS OBSERVATIONAL","BOUNDARY VS ASTRONOMER","CAREER PATH","PUBLIC & INDUSTRY","DIVERSITY"],"branches":[{"senses":"01 · 02","en":"PROFESSIONAL ROLES","cn":"职业角色"},{"senses":"03","en":"BOUNDARY","cn":"边界"},{"senses":"04","en":"CAREER PATH","cn":"职业路径"},{"senses":"05","en":"SUBFIELD (COSMOLOGISTS)","cn":"子专业"},{"senses":"06 · 07 · 08","en":"INDUSTRY / PUBLIC SCIENCE / DIVERSITY","cn":"产业 / 公共科普 / 多样性"}]},"affixes":{"intro":{"en":"astrophysicist is astrophysics + -ist; -ist is a common English suffix for practitioners.","cn":"astrophysicist 就是 astrophysics + -ist；-ist 是常见的施事后缀。"},"latinIntro":{"en":"Greek -istes → Latin -ista → English -ist, giving us physicist, biologist, pianist and hundreds more.","cn":"希腊 -istes → 拉丁 -ista → 英语 -ist，给出 physicist, biologist, pianist 等几百个词。"},"items":[{"word":"astrophysics","structure":"astro- + physics","meaning":"the science","meaningCN":"天体物理学","example":"study astrophysics","exampleCN":"学习天体物理"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"senior astrophysicist","exampleCN":"资深天体物理学家"},{"word":"physicist","structure":"physics + -ist","meaning":"one who does physics","meaningCN":"物理学家","example":"theoretical physicist","exampleCN":"理论物理学家"},{"word":"astronomer","structure":"astronomy + -er","meaning":"one who does astronomy","meaningCN":"天文学家","example":"amateur astronomer","exampleCN":"业余天文学家"},{"word":"cosmologist","structure":"cosmology + -ist","meaning":"one who does cosmology","meaningCN":"宇宙学家","example":"leading cosmologist","exampleCN":"顶尖宇宙学家"},{"word":"astrobiologist","structure":"astrobiology + -ist","meaning":"one who does astrobiology","meaningCN":"天体生物学家","example":"astrobiologist at NASA","exampleCN":"NASA 天体生物学家"},{"word":"astronaut","structure":"astro- + nautes","meaning":"star sailor","meaningCN":"宇航员","example":"experienced astronaut","exampleCN":"经验丰富的宇航员"},{"word":"astrophysicist","structure":"astrophysics + -ist","meaning":"one who does astrophysics","meaningCN":"天体物理学家","example":"collaborating astrophysicists","exampleCN":"合作中的天体物理学家"},{"word":"physicist","structure":"physics + -ist","meaning":"one who does physics","meaningCN":"物理学家","example":"condensed matter physicist","exampleCN":"凝聚态物理学家"},{"word":"biologist","structure":"biology + -ist","meaning":"one who does biology","meaningCN":"生物学家","example":"marine biologist","exampleCN":"海洋生物学家"}],"latinEntries":[]}},{"word":"universe","ipa_uk":"/ˈjuːnɪvɜːrs/","ipa_us":"/ˈjuːnɪvɜːrs/","definition_zh":"宇宙；全世界；领域","definition_en":"all existing matter and space considered as a whole; the cosmos","core_image":"一张宇宙演化时间线图：Big Bang 到今天的 138 亿年","scene":"诗人在诗里写：In the vast universe, one small blue dot spins with everything we know.","sceneCN":"这里指「所有存在的事物的总和」（第1个义项）；句意为在浩瀚的宇宙里，一个小小的蓝点载着我们所知的一切旋转。","pos":[{"tag":"n.","zh":"宇宙；全世界；整个领域"}],"collocations":[{"phrase":"the universe","zh":"宇宙（常带 the）"},{"phrase":"known universe","zh":"已知宇宙"},{"phrase":"entire universe","zh":"整个宇宙"},{"phrase":"parallel universe","zh":"平行宇宙"},{"phrase":"observable universe","zh":"可观测宇宙"},{"phrase":"the universe of...","zh":"...的世界 / 领域"}],"forms":[{"label":"复数","form":"universes"}],"derivatives":[{"word":"universal","pos":"adj.","zh":"普遍的；宇宙的"},{"word":"universally","pos":"adv.","zh":"普遍地"},{"word":"universe-sized","pos":"adj.","zh":"宇宙级大的"},{"word":"cosmos","pos":"n.","zh":"宇宙（同义）"},{"word":"cosmic","pos":"adj.","zh":"宇宙的（近义）"}],"senses":[{"no":"01","title":"All matter, space and time that exists","titleCN":"所有存在的物质、空间和时间","definition":"the whole of everything, from the smallest particles to the largest structures, from the Big Bang to any future end","definitionCN":"一切的整体，从最小粒子到最大结构，从大爆炸到任何未来的终结","example":"The universe began with the Big Bang roughly 13.8 billion years ago.","exampleCN":"宇宙大约 138 亿年前由大爆炸开始。","why":"uni- = one; universe = turned into one whole, all things considered together.","whyCN":"uni- = 一；universe = 合为一的整体，所有事物放在一起看。"},{"no":"02","title":"The observable universe","titleCN":"可观测宇宙","definition":"the part of the whole universe that we can in principle see, given the speed of light and the age of the universe","definitionCN":"考虑光速和宇宙年龄后原则上我们能看到的那部分宇宙","example":"The observable universe contains roughly two trillion galaxies.","exampleCN":"可观测宇宙大约有两万亿个星系。","why":"The observable universe is finite, even if the whole universe might be infinite.","whyCN":"可观测宇宙是有限的，哪怕整个宇宙可能无限。"},{"no":"03","title":"Figurative: someone's world or sphere","titleCN":"比喻：某人的世界或活动领域","definition":"the particular area or group of things that someone cares about or operates in","definitionCN":"某人关心的或在其中活动的特定领域或事物组","example":"For six months her whole universe was her baby and nothing else.","exampleCN":"六个月里她整个世界只有她的宝宝，别的都没兴趣。","why":"People use universe for the bounded, self-contained sphere of their own concerns.","whyCN":"人们用 universe 来指自己关心的那个封闭、自足的小世界。"},{"no":"04","title":"All people or the human world","titleCN":"全人类、全世界","definition":"the whole of humanity, every person everywhere","definitionCN":"全人类，所有地方的所有人","example":"The event was watched by half the universe, or so the broadcaster claimed.","exampleCN":"这场赛事据说有半个 universe（全世界）的人在看。","why":"Universe can shrink to just the human world, especially in journalism and fiction.","whyCN":"Universe 可以缩小到人类世界本身，特别是在新闻和小说里。"},{"no":"05","title":"Parallel or alternate universes","titleCN":"平行或替代宇宙","definition":"in physics and fiction, other universes that exist alongside our own, with different histories or laws of physics","definitionCN":"在物理和科幻里，与我们的宇宙并存、历史或物理定律不同的其他宇宙","example":"Many physicists now take the idea of parallel universes seriously.","exampleCN":"许多物理学家现在认真对待平行宇宙的想法。","why":"The word universe was originally singular, but theories of multiverse extended it.","whyCN":"Universe 本来是单数的，但多元宇宙理论把它扩展了。"},{"no":"06","title":"The universe of mathematics / ideas","titleCN":"数学 / 想法的宇宙","definition":"the complete set of all possible things in an abstract system","definitionCN":"抽象系统中所有可能事物的完整集合","example":"Game theory explores the universe of possible strategies in competitive situations.","exampleCN":"博弈论探索竞争情况下可能策略的宇宙。","why":"Mathematicians and logicians talk about a universe of discourse, the domain of all possible values.","whyCN":"数学家和逻辑学家说「话语宇宙」——所有可能取值的域。"},{"no":"07","title":"End of the universe","titleCN":"宇宙的终结","definition":"scientific scenarios for how the universe might end: heat death, big rip, big crunch","definitionCN":"关于宇宙如何终结的科学场景：热寂、大撕裂、大坍缩","example":"The heat death scenario has the universe growing cold and dark in a trillion trillion years.","exampleCN":"热寂场景里宇宙在一万亿亿年后变冷变暗。","why":"Cosmologists study the future of the universe just as they study its past.","whyCN":"宇宙学家既研究宇宙的过去也研究它的未来。"},{"no":"08","title":"The universe and meaning of life","titleCN":"宇宙与生命意义","definition":"philosophical or popular-science reflection on our place in the whole cosmos","definitionCN":"哲学或科普式地反思我们在整个宇宙中的位置","example":"Carl Sagan wrote that the universe is within us because we are made of star stuff.","exampleCN":"Carl Sagan 写道宇宙就在我们之中，因为我们由星尘构成。","why":"Universe evokes both scale and intimacy: we are huge compared to atoms but tiny compared to it.","whyCN":"Universe 同时唤起尺度和亲密：我们比原子大得多但比宇宙小得多。"}],"etymology":{"intro":{"en":"universe comes from Latin universus = un- (one) + versus (turned), meaning 'turned into one whole, combined'.","cn":"universe 来自拉丁语 universus = un-（一）+ versus（转），意为「合为一个整体、结合在一起」。"},"items":[{"era":"LATIN","en":"Latin universus was an adjective meaning 'all together, the whole'. It was used as early as Cicero to mean 'the world' or 'the whole of nature'.","cn":"拉丁语 universus 是形容词，意为「全部在一起的、整个的」。早在西塞罗时代就用来指「世界」或「自然整体」。"},{"era":"FRENCH","en":"Old French univers borrowed it, still meaning 'the whole world, the heavens and earth'.","cn":"古法语借入 univers，还是指「整个世界、天地」。"},{"era":"MIDDLE ENGLISH","en":"Middle English universe / univers (14th century) kept the sense of 'the whole world'.","cn":"中古英语 universe / univers（14 世纪）保持「整个世界」的意思。"},{"era":"COPERNICAN SHIFT","en":"After Copernicus, universe expanded in meaning: Earth was no longer the centre, so universe now meant the whole cosmic system.","cn":"哥白尼之后 universe 含义扩展：地球不再是中心，所以 universe 现在指整个宇宙体系。"},{"era":"MODERN SCIENCE","en":"20th-century cosmology defined universe as everything that exists, including space and time themselves.","cn":"20 世纪宇宙学把 universe 定义为一切存在之物，包括空间和时间本身。"},{"era":"FICTION","en":"Fictional use of parallel universes dates to the 1920s, multiverse to the 1960s.","cn":"平行宇宙的科幻用法可追溯到 1920 年代，多元宇宙到 1960 年代。"}]},"similar":{"note":{"en":"Group one are near-synonyms for the cosmos; group two are figurative 'world' senses.","cn":"第一组是宇宙的近义；第二组是「世界」的比喻义。"},"groups":[{"heading":"COSMOS NEAR-SYNONYMS","entries":[{"word":"cosmos","ipa":"/ˈkɒzmɒs/","tag":"more poetic","definition":"From Greek kosmos 'order'; often used poetically, slightly less scientific than universe.","definitionCN":"来自希腊语 kosmos「秩序」；常带诗意，比 universe 少些科学味。"},{"word":"cosmic","ipa":"/ˈkɒzmɪk/","tag":"adjective","definition":"Relating to the cosmos; adjective form of cosmos.","definitionCN":"与宇宙有关的；cosmos 的形容词形式。"},{"word":"galaxy","ipa":"/ˈɡæləksi/","tag":"smaller scale","definition":"A single gravitationally bound system of stars; much smaller than the universe.","definitionCN":"一个引力绑定的恒星系统；比宇宙小得多。"},{"word":"the world","ipa":"/ðə wɜːld/","tag":"human-centred","definition":"Usually means Earth and its inhabitants, not the whole cosmos.","definitionCN":"通常指地球和人类，不是整个宇宙。"}]},{"heading":"FIGURATIVE 'WORLD' SENSE","entries":[{"word":"world","ipa":"/wɜːld/","tag":"same figurative","definition":"Someone's world = what they care about; same sense as universe in 'her whole universe'.","definitionCN":"某人的世界 = 他关心的东西；与 universe 的比喻义相同。"},{"word":"sphere","ipa":"/sfɪər/","tag":"domain","definition":"Someone's area of activity or influence, like their universe.","definitionCN":"某人活动或影响的领域，就像他们的 universe。"},{"word":"orbit","ipa":"/ˈɔːrbɪt/","tag":"around someone","definition":"The people who revolve around a famous or powerful person.","definitionCN":"围绕名人或权贵的一群人。"},{"word":"circle","ipa":"/ˈsɜːkl/","tag":"social group","definition":"A bounded social group; universe can describe the same kind of enclosed sphere.","definitionCN":"封闭的社交圈；universe 可指类似的封闭球体。"}]}]},"mnemonics":{"normalIntro":{"en":"Universe = turned into one. uni- = one, versus = turned.","cn":"Universe = 合为一。uni- = 一，versus = 转。"},"normal":[{"en":"uni- (one) + versus (turned) = turned into one whole = universe.","cn":"uni-（一）+ versus（转）= 合为一的整体 = universe。"},{"en":"Everything that exists is one whole: the universe.","cn":"所有存在的东西是一个整体：宇宙。"},{"en":"The observable universe is what we can see; the whole universe might be bigger.","cn":"可观测宇宙是我们能看到的；整个宇宙可能更大。"},{"en":"In parallel universes, you made different choices.","cn":"在平行宇宙里，你做了不同选择。"},{"en":"Your whole universe is the people and things you care about.","cn":"你的整个 universe 就是你关心的人和事。"}],"abstract":[{"en":"A tiny blue dot spinning inside an unimaginably vast dark ball.","cn":"一个难以想象的巨大黑球里转着一个小蓝点。"},{"en":"An expanding balloon with galaxies painted on its surface — every point moves away from every other.","cn":"一个表面画着星系、正在膨胀的气球——每个点都在远离其他每个点。"},{"en":"Something that is, then isn't — a question about the end.","cn":"存在着，然后不存在——关于终结的一个问题。"}]},"examples":[{"en":"Cosmologists calculate the universe to be 13.8 billion years old, give or take 100 million.","cn":"宇宙学家算出宇宙 138 亿岁，误差一亿年。"},{"en":"His universe was music; everything else came second.","cn":"他的整个世界就是音乐；别的都排第二。"},{"en":"The universe of open-source software is vast and constantly expanding.","cn":"开源软件的 universe 庞大且不断扩展。"}],"dict_mnemonic":{"note":"词根记忆","text":"uni-（一）+ versus（转）= 合为一的整体 = 宇宙","word":"universe"},"root":"un-（拉丁语，一）+ versus（转，vertere）→ universus（合为一的）→ universe。","sensesIntro":{"en":"Eight senses zoom in and out: the whole cosmos, the observable part, figurative personal worlds, all humanity, parallel universes, mathematical domains, ending scenarios, and meaning-making.","cn":"八个义项拉近拉远：整个宇宙、可观测部分、比喻的个人世界、全人类、平行宇宙、数学域、终结场景、意义建构。"},"semanticMap":{"core":{"en":"CORE IMAGE: the Hubble Ultra Deep Field, thousands of tiny galaxies on a black canvas.","cn":"核心意象：哈勃极深场，黑底上几千个微末星系。"},"chain":["WHOLE COSMOS","OBSERVABLE PART","FIGURATIVE PERSONAL WORLD","ALL HUMANITY","PARALLEL UNIVERSES","ENDING / MEANING"],"branches":[{"senses":"01 · 02","en":"THE COSMOS","cn":"宇宙本身"},{"senses":"03 · 04","en":"FIGURATIVE / HUMAN","cn":"比喻 / 人类"},{"senses":"05","en":"THEORETICAL PHYSICS","cn":"理论物理"},{"senses":"06","en":"MATHEMATICS","cn":"数学"},{"senses":"07 · 08","en":"COSMOLOGY / PHILOSOPHY","cn":"宇宙学 / 哲学"}]},"affixes":{"intro":{"en":"universe comes from Latin universus: un- (one) + vers- (turned) + -us (suffix).","cn":"universe 来自拉丁语 universus：un-（一）+ vers-（转）+ -us（后缀）。"},"latinIntro":{"en":"vertere 'to turn' is one of the most productive Latin roots, giving convert, revert, reverse, versatile, version, versus and dozens more.","cn":"vertere「转」是最多产的拉丁词根之一，给出 convert, revert, reverse, versatile, version, versus 等几十个词。"},"items":[{"word":"vertere","structure":"Latin root","meaning":"to turn","meaningCN":"转","example":"convert = con- + vertere","exampleCN":"convert = con- + vertere"},{"word":"versus","structure":"Latin past participle","meaning":"turned","meaningCN":"被转","example":"adversus = turned against","exampleCN":"adversus = 转过来反对"},{"word":"universus","structure":"un- + versus","meaning":"turned into one","meaningCN":"合为一的","example":"Latin for 'the whole'","exampleCN":"拉丁语「整个」"},{"word":"universe","structure":"universus → French → English","meaning":"all existing matter and space","meaningCN":"宇宙","example":"the whole universe","exampleCN":"整个宇宙"},{"word":"universal","structure":"universe + -al","meaning":"applying everywhere","meaningCN":"普遍的","example":"universal truth","exampleCN":"普遍真理"},{"word":"convert","structure":"con- + vertere","meaning":"to turn together → change form","meaningCN":"转变","example":"convert pounds to dollars","exampleCN":"把英镑换成美元"},{"word":"reverse","structure":"re- + vertere","meaning":"to turn back","meaningCN":"反转","example":"reverse a decision","exampleCN":"推翻决定"},{"word":"diverse","structure":"di- + vertere","meaning":"turned different ways","meaningCN":"多样的","example":"diverse community","exampleCN":"多元社区"},{"word":"invert","structure":"in- + vertere","meaning":"to turn upside down","meaningCN":"倒转","example":"invert a cup","exampleCN":"倒转一个杯子"},{"word":"version","structure":"versus + -ion","meaning":"a turning → a particular form","meaningCN":"版本","example":"new version","exampleCN":"新版本"}],"latinEntries":[]}},{"word":"universal","ipa_uk":"/ˌjuːnɪˈvɜːrsl/","ipa_us":"/ˌjuːnɪˈvɜːrsl/","definition_zh":"普遍的；宇宙的；万用的","definition_en":"applying to all cases or all people; relating to the universe as a whole","core_image":"一张元素周期表叠在哈勃极深场上，表示物理法则在任何地方都相同","scene":"物理课堂上老师说：The laws of physics appear to be universal — they work the same way on Earth and in the farthest galaxy.","sceneCN":"这里指「在任何地方都一样适用的」（第1个义项：普遍适用的）；句意为物理定律似乎是 universal 的——在地球和最遥远的星系表现一样。","pos":[{"tag":"adj.","zh":"普遍的；宇宙的；万用的"}],"collocations":[{"phrase":"universal law","zh":"普遍法则"},{"phrase":"universal truth","zh":"普遍真理"},{"phrase":"universal language","zh":"通用语言"},{"phrase":"universal problem","zh":"普遍问题"},{"phrase":"universal remote","zh":"万能遥控器"},{"phrase":"universal access","zh":"普及使用"}],"forms":[{"label":"副词","form":"universally"},{"label":"名词","form":"universality"}],"derivatives":[{"word":"universe","pos":"n.","zh":"宇宙"},{"word":"universality","pos":"n.","zh":"普遍性"},{"word":"universally","pos":"adv.","zh":"普遍地"},{"word":"universalize","pos":"v.","zh":"使普遍化"},{"word":"universalism","pos":"n.","zh":"普遍主义"}],"senses":[{"no":"01","title":"Applying to all cases or everywhere","titleCN":"适用于所有情况或所有地方的","definition":"true or valid without exception; applying in every context and every location","definitionCN":"无一例外成立；在每个语境和每个地点都适用","example":"Critics of the theory argue it does not hold as a universal law.","exampleCN":"该理论的批评者认为它不构成普遍法则。","why":"uni- = one; universal = applies to the whole 'one' of all cases.","whyCN":"uni- = 一；universal = 适用于所有情况这个「一」的整体。"},{"no":"02","title":"Relating to the whole universe","titleCN":"与整个宇宙有关的","definition":"describes things that exist at the cosmic scale, not just on Earth","definitionCN":"描述宇宙尺度上存在的事物，不只是地球上的","example":"The event was universal — galaxies across the sky recorded it in their chemical makeup.","exampleCN":"这次事件是宇宙级的——整个天空的星系都在自己的化学成分里记录了它。","why":"The adjective can return to the noun universe, meaning 'relating to the whole cosmos'.","whyCN":"这个形容词可以返回名词 universe，意为「关于整个宇宙的」。"},{"no":"03","title":"Including or affecting everyone","titleCN":"包含或影响所有人的","definition":"not limited to one group or place; shared by all people everywhere","definitionCN":"不限于某个群体或地方；所有地方所有人共享的","example":"The pain of losing a parent is a universal human experience.","exampleCN":"失去父母的痛苦是普遍的人类经历。","why":"Universal human experiences are the ones that cross cultures and history.","whyCN":"普遍人类经历是跨越文化和历史的那些。"},{"no":"04","title":"Usable for many different things (universal tool)","titleCN":"万用的（工具）","definition":"designed or suited for several different uses; not specialized","definitionCN":"为好几种不同用途设计或适合的；非专门化的","example":"A Swiss Army knife is a universal tool for travellers.","exampleCN":"瑞士军刀是旅行者的万用工具。","why":"This sense extends the 'all cases' meaning to objects that handle many tasks.","whyCN":"这个义项把「所有情况」的意思延伸到能处理好多任务的物体上。"},{"no":"05","title":"Universal suffrage / access","titleCN":"普选 / 普及使用","definition":"the principle that all people (in a society) should have the same right or access","definitionCN":"社会里所有人都应有相同权利或使用权的原则","example":"The movement campaigned for universal health care coverage.","exampleCN":"这场运动争取全民医保。","why":"Political universal senses describe rights that should not exclude anyone.","whyCN":"政治上的 universal 义项描述不应该排除任何人的权利。"},{"no":"06","title":"In logic: a statement about all members","titleCN":"逻辑学里关于所有成员的陈述","definition":"a proposition that claims something is true of every member of a set (symbolised ∀)","definitionCN":"声称一个陈述对某个集合的每个成员都为真的命题（符号 ∀）","example":"In first-order logic, 'all swans are white' is a universal statement.","exampleCN":"在一阶逻辑里，「所有天鹅都是白的」是一个全称陈述。","why":"This is the precise sense of universal: ranging over all members of a domain.","whyCN":"这是 universal 最精确的含义：对一个域内所有成员都适用。"},{"no":"07","title":"Universal vs particular","titleCN":"普遍 vs 特殊","definition":"philosophical pair: universal statements describe many things; particular statements describe one thing","definitionCN":"哲学对子：普遍陈述描述很多东西；特殊陈述描述一件东西","example":"The philosopher asked whether universals exist separately from particular objects.","exampleCN":"这位哲学家问共相是否独立于个别物体存在。","why":"Plato and Aristotle began the 2,300-year debate about universals.","whyCN":"柏拉图和亚里士多德开了关于共相的 2300 年辩论。"},{"no":"08","title":"Universal in popular culture","titleCN":"流行文化里的 universal","definition":"used to mean widely appealing or understood by many different groups","definitionCN":"用来表示广泛吸引人、被不同群体理解的","example":"The song became a universal hit across languages and borders.","exampleCN":"这首歌跨越语言和边界成为全民热歌。","why":"In marketing and entertainment, universal means 'everyone likes or gets it'.","whyCN":"在市场和娱乐里，universal 就是「人人喜欢或人人懂」。"}],"etymology":{"intro":{"en":"universal comes from Latin universalis, an adjective from universus (whole, turned into one).","cn":"universal 来自拉丁语 universalis——universus（整体、合为一的）的形容词。"},"items":[{"era":"LATIN","en":"un- (one) + vers- (turned) + -alis (adjective suffix) → universalis = 'of the whole, general'.","cn":"un-（一）+ vers-（转）+ -alis（形容词后缀）→ universalis =「整体的、一般的」。"},{"era":"FRENCH","en":"Old French universel kept the same meanings.","cn":"古法语 universel 保持相同意思。"},{"era":"MIDDLE ENGLISH","en":"Middle English universal (14th century) was used in philosophy and theology.","cn":"中古英语 universal（14 世纪）在哲学和神学里使用。"},{"era":"EARLY MODERN","en":"Expanded to science with Newton's universal gravitation (17th century).","cn":"随牛顿的万有引力扩展到科学领域（17 世纪）。"},{"era":"19TH C POLITICS","en":"Universal suffrage and universal education became key political terms.","cn":"普选和普及教育成为关键政治术语。"},{"era":"TODAY","en":"Legal, scientific, philosophical, political and popular senses all remain active.","cn":"法律、科学、哲学、政治、流行文化的义项今天都活跃。"}]},"similar":{"note":{"en":"Group one are same-root universal family; group two are near-synonyms for 'applying to all'.","cn":"第一组是同词根的 universal 家族；第二组是表示「适用于所有」的近义。"},"groups":[{"heading":"SAME ROOT FAMILY","entries":[{"word":"universe","ipa":"/ˈjuːnɪvɜːrs/","tag":"noun","definition":"The whole that universal describes.","definitionCN":"universal 描述的那个整体。"},{"word":"universally","ipa":"/ˌjuːnɪˈvɜːrsəli/","tag":"adverb","definition":"In a universal way; everywhere or by everyone.","definitionCN":"普遍地；到处或人人都。"},{"word":"universality","ipa":"/ˌjuːnɪvɜːrsˈæləti/","tag":"noun","definition":"The quality of being universal.","definitionCN":"普遍性。"},{"word":"universalize","ipa":"/ˌjuːnɪvɜːrsəˈlaɪz/","tag":"verb","definition":"To make something universal.","definitionCN":"使普遍化。"}]},{"heading":"NEAR SYNONYMS","entries":[{"word":"general","ipa":"/ˈdʒenrəl/","tag":"broader","definition":"Applies to most cases; universal means all cases without exception.","definitionCN":"适用于大多数情况；universal 指无一例外。"},{"word":"omnipresent","ipa":"/ˌɒmnɪˈpreznt/","tag":"formal","definition":"Present everywhere; stronger than universal about location.","definitionCN":"无所不在的；在地点上比 universal 更强。"},{"word":"cosmic","ipa":"/ˈkɒzmɪk/","tag":"universe sense","definition":"Relating to the whole universe; overlaps with the 'relating to cosmos' sense.","definitionCN":"与整个宇宙有关的；与 universal 的宇宙义项重叠。"},{"word":"global","ipa":"/ˈɡləʊbl/","tag":"Earth sense","definition":"Applies to the whole Earth; narrower than universal about scope.","definitionCN":"适用于整个地球；范围上比 universal 窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Universal = of the universe / all cases. uni- = one, vers- = turned.","cn":"Universal = 宇宙的 / 所有情况的。uni- = 一，vers- = 转。"},"normal":[{"en":"universe + -al = universal, just like universe + -ally = universally.","cn":"universe + -al = universal，就像 universe + -ally = universally。"},{"en":"Universal laws of physics work everywhere in the universe.","cn":"物理的 universal 法则在宇宙任何地方都有效。"},{"en":"A universal remote works with many different devices.","cn":"万能遥控器能控制很多不同设备。"},{"en":"Universal health care is for everyone, without exception.","cn":"全民医保是给每个人的，无一例外。"},{"en":"In logic, a universal statement is about all members of a set.","cn":"在逻辑里，全称陈述是关于一个集合所有成员的。"}],"abstract":[{"en":"A single law written on a chalkboard, equally valid in every galaxy.","cn":"黑板上写着一个法则，在每个星系都同等有效。"},{"en":"One key that fits every lock.","cn":"一把能开所有锁的钥匙。"},{"en":"Everybody on Earth singing the same note, in their own language.","cn":"地球上每个人用自己的语言唱同一个音。"}]},"examples":[{"en":"The speed of light is a universal constant that appears in every equation of relativity.","cn":"光速是一个 universal 常数，出现在每个相对论方程里。"},{"en":"Her paintings have a universal appeal that crosses cultural boundaries.","cn":"她的画作有 cross-cultural 的 universal 吸引力。"},{"en":"Universal basic income is being tested in several countries.","cn":"全民基本收入正在几个国家试点。"}],"dict_mnemonic":{"note":"形容词后缀","text":"universe（宇宙）+ -al（...的）= 宇宙的 / 普遍的","word":"universal"},"root":"un-（拉丁语，一）+ versus（转）→ universus → universalis → universal。","sensesIntro":{"en":"Eight senses range from 'applies everywhere' through 'relating to the cosmos', 'including everyone', 'usable for many purposes', political rights, logic, philosophy and pop culture.","cn":"八个义项从「到处适用」经过「关于宇宙」、「包括所有人」、「万用」、政治权利、逻辑、哲学，到流行文化。"},"semanticMap":{"core":{"en":"CORE IMAGE: one equation on a blackboard that is valid everywhere — on Earth and across every galaxy.","cn":"核心意象：黑板上一个在任何地方——地球上、每个星系里——都成立的方程。"},"chain":["APPLIES EVERYWHERE","RELATING TO THE COSMOS","INCLUDING EVERYONE","USABLE FOR MANY PURPOSES","LOGIC / PHILOSOPHY","POP CULTURE"],"branches":[{"senses":"01","en":"ALL CASES / EVERYWHERE","cn":"所有情况 / 到处"},{"senses":"02","en":"COSMIC","cn":"宇宙级"},{"senses":"03 · 04 · 05","en":"HUMAN / POLITICAL / TOOLS","cn":"人类 / 政治 / 工具"},{"senses":"06 · 07","en":"LOGIC / PHILOSOPHY","cn":"逻辑 / 哲学"},{"senses":"08","en":"POP CULTURE","cn":"流行文化"}]},"affixes":{"intro":{"en":"universal adds the Latin adjective suffix -alis to universus (whole, one); the root un- + vertere is very productive.","cn":"universal 是在 universus（整体、一）上加拉丁形容词后缀 -alis；词根 un- + vertere 非常多产。"},"latinIntro":{"en":"vertere 'to turn' gives convert, revert, reverse, versatile, version, versus, etc. un- means 'one' or 'not'.","cn":"vertere「转」给出 convert, revert, reverse, versatile, version, versus 等。un- 意为「一」或「不」。"},"items":[{"word":"universe","structure":"un- + vers- + -e","meaning":"the whole","meaningCN":"宇宙","example":"the whole universe","exampleCN":"整个宇宙"},{"word":"universal","structure":"universe + -al","meaning":"of the whole; applying to all","meaningCN":"宇宙的；普遍的","example":"universal law","exampleCN":"普遍法则"},{"word":"universally","structure":"universal + -ly","meaning":"in a universal way","meaningCN":"普遍地","example":"universally loved","exampleCN":"人人喜爱的"},{"word":"universality","structure":"universal + -ity","meaning":"the quality of being universal","meaningCN":"普遍性","example":"question universality","exampleCN":"质疑普遍性"},{"word":"universalize","structure":"universal + -ize","meaning":"to make universal","meaningCN":"使普遍化","example":"universalize education","exampleCN":"普及教育"},{"word":"convert","structure":"con- + vertere","meaning":"to turn together","meaningCN":"转变","example":"convert currency","exampleCN":"换汇"},{"word":"reverse","structure":"re- + vertere","meaning":"to turn back","meaningCN":"反转","example":"reverse course","exampleCN":"改变方向"},{"word":"diverse","structure":"di- + vertere","meaning":"turned different ways","meaningCN":"多样的","example":"diverse group","exampleCN":"多元群体"},{"word":"invert","structure":"in- + vertere","meaning":"to turn upside down","meaningCN":"倒转","example":"invert sugar","exampleCN":"转化糖"},{"word":"version","structure":"versus + -ion","meaning":"a particular form","meaningCN":"版本","example":"latest version","exampleCN":"最新版本"}],"latinEntries":[]}},{"word":"cosmos","ipa_uk":"/ˈkɒzmɒs/","ipa_us":"/ˈkɒzmoʊs/","definition_zh":"宇宙；和谐的秩序","definition_en":"the universe as an ordered whole; an ordered system","core_image":"星空下一个旋转的星系，配上古代四元素（水、土、气、火）的装饰画","scene":"诗人在诗行里写：From the smallest atom to the farthest galaxy, the cosmos hums with hidden order.","sceneCN":"这里指「整个有秩序的宇宙」（第1个义项）；句意为从最小的原子到最远的星系，宇宙都在隐秘的秩序里嗡嗡作响。","pos":[{"tag":"n.","zh":"宇宙；有秩序的整体；（小写 c 时）花簇"}],"collocations":[{"phrase":"the cosmos","zh":"宇宙（常带 the）"},{"phrase":"the entire cosmos","zh":"整个宇宙"},{"phrase":"order of the cosmos","zh":"宇宙的秩序"},{"phrase":"cosmos flower","zh":"大波斯菊（小写 c）"},{"phrase":"known cosmos","zh":"已知宇宙"},{"phrase":"cosmos of ideas","zh":"想法的宇宙"}],"forms":[{"label":"复数","form":"cosmoses"},{"label":"花","form":"cosmos flowers"}],"derivatives":[{"word":"cosmic","pos":"adj.","zh":"宇宙的"},{"word":"cosmology","pos":"n.","zh":"宇宙学"},{"word":"cosmologist","pos":"n.","zh":"宇宙学家"},{"word":"cosmogony","pos":"n.","zh":"宇宙起源论"},{"word":"microcosm","pos":"n.","zh":"小宇宙、缩影"}],"senses":[{"no":"01","title":"The universe as an ordered whole","titleCN":"作为有秩序整体的宇宙","definition":"the whole of all matter and energy, seen not as chaos but as a system with underlying order and laws","definitionCN":"所有物质和能量的整体，不是混沌的，而是一个有内在秩序和法则的系统","example":"Ancient Greek philosophers believed the cosmos was held together by geometric harmony.","exampleCN":"古希腊哲学家相信宇宙由几何和谐维系在一起。","why":"kosmos originally meant 'order, arrangement, ornament' before it meant 'the universe'.","whyCN":"kosmos 原意是「秩序、安排、装饰」，后来才指「宇宙」。"},{"no":"02","title":"Cosmos flower (lowercase)","titleCN":"大波斯菊（小写 c）","definition":"a flowering plant of the genus Cosmos, with daisy-like blooms in pink, white or orange","definitionCN":"Cosmos 属的开花植物，有粉色、白色或橙色的雏菊状花朵","example":"She planted cosmos along the fence and they bloomed all summer.","exampleCN":"她沿围栏种了大波斯菊，整个夏天都在开。","why":"The plant was named cosmos because its petals resemble the orderly arrangement of a starburst.","whyCN":"这种花被命名为 cosmos 是因为它的花瓣像星爆的秩序排列。"},{"no":"03","title":"Figurative: any ordered system","titleCN":"比喻：任何有秩序的系统","definition":"any interconnected set of things that feels coherent and patterned","definitionCN":"任何相互关联、感觉连贯有模式的事物集","example":"Her paintings suggest a cosmos where everything is connected by invisible threads.","exampleCN":"她的画暗示了一个万物被看不见的线连接的有序宇宙。","why":"Cosmos carries the sense of ordered system even when scaled down to human size.","whyCN":"Cosmos 即使缩小到人类尺度也带着「有秩序系统」的感觉。"},{"no":"04","title":"Universe vs cosmos","titleCN":"universe vs cosmos","definition":"universe is the scientific word for everything that exists; cosmos adds the sense of order, harmony and design","definitionCN":"universe 是科学词，指一切存在之物；cosmos 增加了秩序、和谐、设计的感觉","example":"Cosmologists study the universe, but poets write about the cosmos.","exampleCN":"宇宙学家研究 universe，而诗人写 cosmos。","why":"The poetic, ordered tone of cosmos comes straight from its Greek root.","whyCN":"cosmos 的诗意、有序的语气直接来自它的希腊词根。"},{"no":"05","title":"Microcosm: a small cosmos","titleCN":"microcosm：小宇宙","definition":"a small system that mirrors the larger cosmos; often used for a community or a single person","definitionCN":"反映大宇宙的小系统；常用于社区或单个人","example":"The city was a microcosm of the whole country's tensions.","exampleCN":"这座城市是整个国家紧张局势的缩影。","why":"microcosm uses the same cosmos root to describe a scaled-down version.","whyCN":"microcosm 用同一个 cosmos 词根描述缩小的版本。"},{"no":"06","title":"Cosmos in religion and philosophy","titleCN":"宗教与哲学里的 cosmos","definition":"used to describe God's creation or a moral order that governs both the heavens and human life","definitionCN":"用来描述上帝的创造或同时支配天上和人间生活的道德秩序","example":"The Stoics taught that living in accordance with the cosmos was the highest good.","exampleCN":"斯多葛学派教导说与宇宙和谐一致地生活是最高的善。","why":"Cosmos carries ethical weight that universe does not, because it means 'ordered by design'.","whyCN":"Cosmos 带有 universe 没有的伦理重量，因为它的意思是「有设计地安排的」。"},{"no":"07","title":"Cosmos in science fiction","titleCN":"科幻里的 cosmos","definition":"used to evoke vastness and wonder, slightly more poetic than universe or galaxy","definitionCN":"用来唤起浩瀚和惊叹，比 universe 或 galaxy 更有诗意","example":"The spaceship vanished into the cosmos, never to be seen again.","exampleCN":"飞船消失在宇宙中，再也没出现。","why":"Writers reach for cosmos when they want scale to feel beautiful as well as large.","whyCN":"写作者用 cosmos 时想要尺度不仅大还要美。"},{"no":"08","title":"Plural cosmoses","titleCN":"复数 cosmoses","definition":"the standard English plural; sometimes used in science fiction for multiple universes","definitionCN":"英语标准复数；科幻里有时指多个宇宙","example":"The theory predicts that our cosmos is just one of many cosmoses.","exampleCN":"该理论预言我们的宇宙只是众多宇宙之一。","why":"The plural is a natural English adaptation; Greek kosmoi exists but is rarely used in English.","whyCN":"复数是自然的英语形式；希腊语 kosmoi 存在但英语里很少用。"}],"etymology":{"intro":{"en":"cosmos comes from Greek kosmos, which originally meant 'order, arrangement, ornament' before it came to mean 'the ordered universe'.","cn":"cosmos 来自希腊语 kosmos，原意是「秩序、安排、装饰」，后来才指「有秩序的宇宙」。"},"items":[{"era":"GREEK ORIGIN","en":"Homeric Greek kosmos meant 'orderly arrangement, ornament'. By the 5th century BCE it meant 'the world as an ordered whole'.","cn":"荷马时代希腊语 kosmos 意为「有序的安排、装饰」。到公元前 5 世纪意为「作为有序整体的世界」。"},{"era":"LATIN","en":"Latin borrowed kosmos directly, keeping both the 'order' and 'universe' senses.","cn":"拉丁语直接借入 kosmos，保留了「秩序」和「宇宙」两种意思。"},{"era":"OLD FRENCH","en":"Old French cosmos kept the Greek meaning of 'ordered universe'.","cn":"古法语 cosmos 保持希腊语「有秩序的宇宙」含义。"},{"era":"MIDDLE ENGLISH","en":"Middle English cosmos appeared in the 14th century via Old French.","cn":"中古英语 cosmos 14 世纪经古法语出现。"},{"era":"FLOWER","en":"The Cosmos plant genus was named in the 18th century from the Greek word for the universe.","cn":"Cosmos 属植物在 18 世纪以希腊语宇宙一词命名。"},{"era":"TODAY","en":"Poets, philosophers and gardeners use cosmos; scientists prefer universe.","cn":"诗人、哲学家、园丁用 cosmos；科学家更常用 universe。"}]},"similar":{"note":{"en":"Group one shares the cosm- root; group two compares cosmos to universe, galaxy and other cosmic terms.","cn":"第一组共享 cosm- 词根；第二组把 cosmos 和 universe, galaxy 等宇宙术语对比。"},"groups":[{"heading":"SAME cosm- ROOT","entries":[{"word":"cosmic","ipa":"/ˈkɒzmɪk/","tag":"adjective","definition":"Of or relating to the cosmos.","definitionCN":"与宇宙有关的。"},{"word":"cosmology","ipa":"/kɒzˈmɒlədʒi/","tag":"science","definition":"Study of the origin and structure of the cosmos.","definitionCN":"研究宇宙起源和结构的学科。"},{"word":"cosmologist","ipa":"/kɒzˈmɒlədʒɪst/","tag":"person","definition":"One who studies cosmology.","definitionCN":"研究宇宙学的人。"},{"word":"cosmogony","ipa":"/kɒzˈmɒɡəni/","tag":"narrower","definition":"Specific study of how the cosmos began.","definitionCN":"专门研究宇宙如何起源。"}]},{"heading":"RELATED COSMIC TERMS","entries":[{"word":"universe","ipa":"/ˈjuːnɪvɜːrs/","tag":"scientific","definition":"Scientific word for all that exists; less poetic than cosmos.","definitionCN":"表示一切存在之物的科学词；比 cosmos 少些诗意。"},{"word":"galaxy","ipa":"/ˈɡæləksi/","tag":"smaller","definition":"A single system of stars; much smaller than either cosmos or universe.","definitionCN":"一个恒星系统；比 cosmos 和 universe 都小得多。"},{"word":"order","ipa":"/ˈɔːrdər/","tag":"etymological core","definition":"The underlying sense of cosmos: arrangement, not chaos.","definitionCN":"cosmos 的底层含义：有序、非混沌。"},{"word":"chaos","ipa":"/ˈkeɪɒs/","tag":"opposite","definition":"The opposite of cosmos in ancient Greek; shapeless, formless matter.","definitionCN":"古希腊语中 cosmos 的对立；无形、无定形之物。"}]}]},"mnemonics":{"normalIntro":{"en":"Cosmos = ordered universe, not chaos.","cn":"Cosmos = 有秩序的宇宙，不是混沌。"},"normal":[{"en":"Greek kosmos meant 'order' before it meant 'universe'.","cn":"希腊语 kosmos 先意为「秩序」，后意为「宇宙」。"},{"en":"Cosmos vs chaos: universe with vs without order.","cn":"Cosmos vs chaos：有 vs 无秩序的宇宙。"},{"en":"Microcosm is a small cosmos, like a city reflecting the country.","cn":"Microcosm 是一个小 cosmos，像城市反映国家。"},{"en":"The cosmos flower is named for its orderly petals.","cn":"大波斯菊以它有序的花瓣命名为 cosmos。"},{"en":"Poets write about the cosmos; scientists about the universe.","cn":"诗人写 cosmos；科学家写 universe。"}],"abstract":[{"en":"Ancient Greek philosophers gathering under the stars, listening for harmony.","cn":"古希腊哲学家聚在星空下，谛听和谐之声。"},{"en":"A single daisy, petals perfectly arranged around a centre.","cn":"一朵雏菊，花瓣完美地绕中心排列。"},{"en":"Everything connected by invisible threads, humming in tune.","cn":"万物被看不见的线连着，嗡嗡地共鸣。"}]},"examples":[{"en":"The Hubble image of the deep cosmos contains over ten thousand galaxies.","cn":"哈勃的深空宇宙图像里包含一万多个星系。"},{"en":"According to Stoic philosophy, we should live in harmony with the cosmos.","cn":"按斯多葛哲学，我们应与宇宙和谐生活。"},{"en":"She grew cosmos along the garden path where they caught the afternoon sun.","cn":"她在花园小径旁种了大波斯菊，在下午阳光下盛开。"}],"dict_mnemonic":{"note":"词根记忆","text":"希腊语 kosmos（秩序、装饰）→ 有秩序的宇宙 = cosmos","word":"cosmos"},"root":"kosmos（希腊语，秩序、装饰）→ cosmos。","sensesIntro":{"en":"Eight senses balance the scientific universe, the poetic ordered whole, the flower, figurative systems, microcosm, philosophy, sci-fi and the plural.","cn":"八个义项平衡了科学的宇宙、诗意的有序整体、花、比喻系统、小宇宙、哲学、科幻和复数。"},"semanticMap":{"core":{"en":"CORE IMAGE: stars arranged in a galaxy spiral, order out of apparent chaos.","cn":"核心意象：星系螺旋里排列的恒星，从看似混沌中显现秩序。"},"chain":["ORDERED UNIVERSE","COSMOS FLOWER","FIGURATIVE SYSTEM","VS UNIVERSE","MICROCOSM","PHILOSOPHY / SCI-FI"],"branches":[{"senses":"01 · 04","en":"THE ORDERED WHOLE: the universe read as order rather than plain extent, which is what separates it from universe.","cn":"有序整体：被读作秩序而非单纯范围的宇宙，这正是它与 universe 的分界。"},{"senses":"02","en":"THE FLOWER: the garden genus Cosmos, unrelated to the sky sense.","cn":"花卉：园艺里的波斯菊属，与天空义无关。"},{"senses":"03 · 05","en":"FIGURATIVE SYSTEMS AND MICROCOSM: any coherent whole, including a small one that mirrors the large.","cn":"比喻系统与小宇宙：任何自洽整体，包括映照大宇宙的小整体。"},{"senses":"06 · 07","en":"RELIGION, PHILOSOPHY AND SCIENCE FICTION: creation and moral order, then fictional vastness.","cn":"宗教、哲学与科幻：造物与道德秩序，再到虚构的浩瀚。"},{"senses":"08","en":"PLURAL FORM: cosmoses, the standard English plural, also used for multiple universes.","cn":"复数形式：cosmoses，英语标准复数，也指多个宇宙。"}]},"affixes":{"intro":{"en":"cosmos comes from Greek kosmos 'order, ornament, universe'; the cosmo- prefix is productive in English science.","cn":"cosmos 来自希腊语 kosmos「秩序、装饰、宇宙」；cosmo- 前缀在英语科学里多产。"},"latinIntro":{"en":"kosmos is purely Greek; Latin borrowed it directly without modification.","cn":"kosmos 纯希腊语；拉丁语直接借入没改。"},"items":[{"word":"kosmos","structure":"Greek root","meaning":"order, ornament, universe","meaningCN":"秩序、装饰、宇宙","example":"Greek kosmos = universe","exampleCN":"希腊语宇宙"},{"word":"cosmos","structure":"kosmos → English","meaning":"ordered universe; flower genus","meaningCN":"有秩序的宇宙；大波斯菊属","example":"the whole cosmos","exampleCN":"整个宇宙"},{"word":"cosmic","structure":"kosmos + -ic","meaning":"relating to the cosmos","meaningCN":"宇宙的","example":"cosmic event","exampleCN":"宇宙事件"},{"word":"cosmology","structure":"kosmos + -logy","meaning":"study of the cosmos","meaningCN":"宇宙学","example":"study cosmology","exampleCN":"学习宇宙学"},{"word":"cosmologist","structure":"kosmos + -logy + -ist","meaning":"one who studies cosmology","meaningCN":"宇宙学家","example":"leading cosmologist","exampleCN":"顶尖宇宙学家"},{"word":"cosmogony","structure":"kosmos + -gony","meaning":"study of the origin of the cosmos","meaningCN":"宇宙起源论","example":"ancient cosmogony","exampleCN":"古代宇宙起源论"},{"word":"microcosm","structure":"micro- + kosmos","meaning":"small universe","meaningCN":"小宇宙、缩影","example":"city as microcosm","exampleCN":"城市作为缩影"},{"word":"macrokosm","structure":"macro- + kosmos","meaning":"the big universe","meaningCN":"大宇宙","example":"macrocosm of nature","exampleCN":"自然的大宇宙"},{"word":"chaos","structure":"Greek opposite","meaning":"unordered matter","meaningCN":"混沌","example":"out of chaos","exampleCN":"从混沌中"},{"word":"cosmos flower","structure":"genus name","meaning":"flowering plant","meaningCN":"大波斯菊","example":"cosmos in bloom","exampleCN":"盛开的大波斯菊"}],"latinEntries":[]}},{"word":"cosmic","ipa_uk":"/ˈkɒzmɪk/","ipa_us":"/ˈkɒzmɪk/","definition_zh":"宇宙的；巨大的；至关重要的","definition_en":"relating to the cosmos; huge in scale or significance","core_image":"X 射线天文望远镜拍到的星系碰撞图，配着人类尺度下的一双手示意大小","scene":"纪录片里解说员说：The collision of two galaxies is a cosmic event that plays out over hundreds of millions of years.","sceneCN":"这里指「宇宙尺度上的」（第1个义项）；句意为两个星系的碰撞是一个在几亿年间展开的 cosmic 事件。","pos":[{"tag":"adj.","zh":"宇宙的；巨大的；至关重要的"}],"collocations":[{"phrase":"cosmic event","zh":"宇宙事件"},{"phrase":"cosmic scale","zh":"宇宙尺度"},{"phrase":"cosmic dust","zh":"宇宙尘"},{"phrase":"cosmic radiation","zh":"宇宙辐射"},{"phrase":"cosmic importance","zh":"至关重要"},{"phrase":"cosmic background","zh":"宇宙背景辐射"}],"forms":[{"label":"副词","form":"cosmically"}],"derivatives":[{"word":"cosmos","pos":"n.","zh":"宇宙；有序整体"},{"word":"cosmology","pos":"n.","zh":"宇宙学"},{"word":"cosmologist","pos":"n.","zh":"宇宙学家"},{"word":"cosmicly","pos":"adv.","zh":"宇宙级地"},{"word":"cosmogonic","pos":"adj.","zh":"宇宙起源的"}],"senses":[{"no":"01","title":"Relating to the cosmos or outer space","titleCN":"与宇宙或外太空有关的","definition":"the core scientific sense; anything that happens beyond Earth and its atmosphere","definitionCN":"核心科学义项：地球和大气层以外发生的任何事","example":"Cosmic radiation constantly bombards the upper atmosphere.","exampleCN":"宇宙辐射不断轰击高层大气。","why":"cosmic = of the cosmos, just like galactic = of a galaxy.","whyCN":"cosmic = 宇宙的，就像 galactic = 星系的。"},{"no":"02","title":"On an immense scale","titleCN":"巨大尺度的","definition":"informal usage: so large or so huge that it dwarfs normal human-scale numbers or events","definitionCN":"非正式用法：大到超过人类日常尺度的数字或事件","example":"The budget gap was cosmic — billions of dollars over what anyone had projected.","exampleCN":"预算缺口是 cosmic 的——比任何人预期的多几十亿美元。","why":"Like astronomical, cosmic can refer to things on the scale of the universe.","whyCN":"和 astronomical 一样，cosmic 可以指宇宙尺度的东西。"},{"no":"03","title":"Cosmic dust, rays, background radiation","titleCN":"宇宙尘、宇宙射线、宇宙背景辐射","definition":"scientific compounds: cosmic describes anything in space — dust, rays, noise, microwave background","definitionCN":"科学复合词：cosmic 描述太空里的一切——尘、射线、噪声、微波背景","example":"Cosmic microwave background radiation is the echo of the Big Bang.","exampleCN":"宇宙微波背景辐射是大爆炸的回声。","why":"The adjective is widely attached to nouns in astronomy and astrophysics.","whyCN":"这个形容词在天文和天体物理里广泛跟名词搭配。"},{"no":"04","title":"Cosmic importance or significance","titleCN":"至关重要","definition":"used for events or decisions that seem as important as anything in the universe","definitionCN":"用于重要得像宇宙里最关键的事件或决定","example":"To a child, losing a favourite toy can feel of cosmic importance.","exampleCN":"对小孩来说，丢了最喜欢的玩具可能觉得是 cosmic 级别的事。","why":"Hyperbole borrows the largest scale to mean the most important.","whyCN":"夸张借最大的尺度来指最重要的。"},{"no":"05","title":"Cosmic justice or cosmic order","titleCN":"宇宙正义或宇宙秩序","definition":"used to describe a moral or natural order that is larger than human society","definitionCN":"用来描述比人类社会更大的道德或自然秩序","example":"Some people believe in cosmic justice that balances the wrongs of this life.","exampleCN":"有些人相信 cosmic 正义会平衡这一世的冤屈。","why":"Cosmic carries the 'ordered whole' sense from its Greek root kosmos.","whyCN":"Cosmic 带着希腊语词根 kosmos 的「有序整体」含义。"},{"no":"06","title":"Cosmic vs astronomical vs galactic","titleCN":"cosmic vs astronomical vs galactic","definition":"cosmic = whole universe; astronomical = of astronomy or huge; galactic = of galaxies; the scales grow smaller","definitionCN":"cosmic = 整个宇宙；astronomical = 天文学的或巨大的；galactic = 星系的；尺度逐个变小","example":"Cosmic events span billions of galaxies; galactic events span one galaxy.","exampleCN":"Cosmic 事件跨越几十亿星系；galactic 事件只跨一个星系。","why":"The progression maps nicely: cosmic > astronomical > galactic.","whyCN":"这个阶梯很清楚：cosmic > astronomical > galactic。"},{"no":"07","title":"Cosmic in popular culture and New Age","titleCN":"流行文化和新世纪运动里的 cosmic","definition":"used for anything feeling mystical, universal or out of the ordinary","definitionCN":"用来指神秘的、普遍的或不普通的事物","example":"The festival had a cosmic vibe — everyone felt connected to something bigger.","exampleCN":"那个节日有一种 cosmic 的氛围——人人觉得和更伟大的东西连上了。","why":"New Age culture picked up cosmic because it evokes vastness, mystery and unity.","whyCN":"新世纪运动喜欢 cosmic 因为它唤起浩瀚、神秘、合一。"},{"no":"08","title":"Cosmic rays and particle physics","titleCN":"宇宙射线与粒子物理","definition":"high-energy particles from space that hit Earth's atmosphere; studied by particle physicists","definitionCN":"来自太空、轰击地球大气的高能粒子；由粒子物理学家研究","example":"Cosmic rays discovered new fundamental particles before accelerators could.","exampleCN":"宇宙射线在加速器之前就发现了新的基本粒子。","why":"Cosmic rays are nature's own particle accelerator — cheaper and more powerful than anything we can build.","whyCN":"宇宙射线是大自然自己的粒子加速器——比我们能造的都便宜且强大。"}],"etymology":{"intro":{"en":"cosmic is the adjective of cosmos: Greek kosmos (ordered universe) + -ic adjective suffix.","cn":"cosmic 是 cosmos 的形容词：希腊语 kosmos（有秩序的宇宙）+ -ic 形容词后缀。"},"items":[{"era":"GREEK ROOT","en":"kosmos 'order, ornament, universe' → cosmic via Latin and French.","cn":"kosmos「秩序、装饰、宇宙」→ 经拉丁语和法语 → cosmic。"},{"era":"EARLY MODERN","en":"cosmic appeared in English in the early 17th century, borrowed from Latin cosmicus.","cn":"cosmic 17 世纪早期进入英语，借自拉丁语 cosmicus。"},{"era":"SCIENCE EXPANSION","en":"With the growth of astrophysics in the 20th century, cosmic became attached to dozens of scientific compounds.","cn":"20 世纪天体物理成长时，cosmic 与几十个科学复合词搭在一起。"},{"era":"FIGURATIVE","en":"The 'huge scale' sense developed alongside astronomical and galactic in the 20th century.","cn":"「巨大尺度」的义项在 20 世纪和 astronomical, galactic 一起发展起来。"},{"era":"NEW AGE","en":"New Age writers and musicians adopted cosmic in the 1960s and 1970s.","cn":"1960-70 年代新世纪作家和音乐人采用 cosmic。"},{"era":"TODAY","en":"Scientific, figurative and New Age senses all remain active.","cn":"科学、比喻、新世纪的义项今天都活跃。"}]},"similar":{"note":{"en":"Group one shares the cosm- root; group two compares cosmic to other scale adjectives.","cn":"第一组共享 cosm- 词根；第二组把 cosmic 和其他尺度形容词对比。"},"groups":[{"heading":"SAME cosm- ROOT","entries":[{"word":"cosmos","ipa":"/ˈkɒzmɒs/","tag":"noun","definition":"The noun that cosmic describes.","definitionCN":"cosmic 描述的那个名词。"},{"word":"cosmology","ipa":"/kɒzˈmɒlədʒi/","tag":"science","definition":"Study of the cosmos; cosmic events are often studied here.","definitionCN":"宇宙学；cosmic 事件常在其中研究。"},{"word":"cosmologist","ipa":"/kɒzˈmɒlədʒɪst/","tag":"person","definition":"One who studies cosmology.","definitionCN":"宇宙学家。"},{"word":"cosmogony","ipa":"/kɒzˈmɒɡəni/","tag":"narrower","definition":"Study of how the cosmos began.","definitionCN":"宇宙起源论。"}]},{"heading":"SCALE ADJECTIVES","entries":[{"word":"astronomical","ipa":"/ˌæstrəˈnɒmɪkl/","tag":"same sense","definition":"Huge in scale; of astronomy. Overlaps strongly with cosmic.","definitionCN":"巨大尺度的；天文学的。与 cosmic 强烈重叠。"},{"word":"galactic","ipa":"/ɡəˈlæktɪk/","tag":"smaller scale","definition":"Of galaxies; smaller than cosmic, bigger than stellar.","definitionCN":"星系的；比 cosmic 小，比 stellar 大。"},{"word":"stellar","ipa":"/ˈstelər/","tag":"stars","definition":"Of stars themselves; smaller than galactic or cosmic.","definitionCN":"恒星本身的；比 galactic 或 cosmic 小。"},{"word":"universal","ipa":"/ˌjuːnɪˈvɜːrsl/","tag":"different sense","definition":"Applying everywhere; different angle from cosmic's 'scale' sense.","definitionCN":"到处适用的；与 cosmic 的「尺度」义角度不同。"}]}]},"mnemonics":{"normalIntro":{"en":"cosmic = of the cosmos.","cn":"cosmic = 宇宙的。"},"normal":[{"en":"cosmos + -ic = cosmic, just like physics + -ic = physic (archaic for physical).","cn":"cosmos + -ic = cosmic。"},{"en":"Cosmic rays come from outer space.","cn":"宇宙射线来自太空。"},{"en":"The cosmic microwave background is the echo of the Big Bang.","cn":"宇宙微波背景是大爆炸的回声。"},{"en":"A cosmic event is so big it dwarfs everything else.","cn":"一个 cosmic 事件大到其他一切都渺小。"},{"en":"Cosmic justice balances the wrongs of the whole universe.","cn":"宇宙正义平衡整个宇宙的冤屈。"}],"abstract":[{"en":"The quiet hum of radiation left over from the beginning.","cn":"开端留下的辐射的安静嗡嗡声。"},{"en":"Something vast, ancient, and indifferent — that still gives us our atoms.","cn":"浩瀚、古老、冷漠的存在——但给了我们身上的每一个原子。"},{"en":"A word that can describe a supernova or a song, a budget gap or a love affair.","cn":"一个可以描述超新星或一首歌、预算缺口或一段爱情的词。"}]},"examples":[{"en":"Cosmic dust is one of the key ingredients for forming new stars and planets.","cn":"宇宙尘是形成新恒星和行星的关键成分之一。"},{"en":"To a four-year-old, finding their lost teddy bear feels of cosmic importance.","cn":"对四岁小孩来说，找到丢失的泰迪熊感觉是 cosmic 级别的事。"},{"en":"The team detected a burst of cosmic rays that could not be explained by known sources.","cn":"团队探测到一次无法用已知来源解释的宇宙射线爆发。"}],"dict_mnemonic":{"note":"形容词后缀","text":"cosmos（宇宙）+ -ic（...的）= 宇宙的","word":"cosmic"},"root":"kosmos（希腊语，秩序、宇宙）→ cosmic。","sensesIntro":{"en":"Eight senses move from the strict scientific adjective, through scale, compounds, importance, justice, terminology, New Age and particle physics.","cn":"八个义项从严格科学形容词出发，经过尺度、复合词、重要性、正义、术语、新世纪、粒子物理。"},"semanticMap":{"core":{"en":"CORE IMAGE: Earth as a blue dot against the black cosmos, speckled with galaxies.","cn":"核心意象：地球是宇宙黑底上的一个蓝点，点缀着星系。"},"chain":["SCIENTIFIC ADJECTIVE","HUGE SCALE","COMPOUNDS","IMPORTANCE","JUSTICE / ORDER","TERMINOLOGY / POP CULTURE"],"branches":[{"senses":"01 · 03","en":"SCIENCE","cn":"科学"},{"senses":"02","en":"SCALE / HUGENESS","cn":"尺度 / 巨大"},{"senses":"04 · 05","en":"IMPORTANCE / JUSTICE","cn":"重要 / 正义"},{"senses":"06","en":"TERMINOLOGY","cn":"术语"},{"senses":"07 · 08","en":"POP CULTURE / PARTICLE PHYSICS","cn":"流行文化 / 粒子物理"}]},"affixes":{"intro":{"en":"cosmic = cosmos + -ic; -ic is a common English adjective suffix borrowed from Greek.","cn":"cosmic = cosmos + -ic；-ic 是英语里借自希腊语的常见形容词后缀。"},"latinIntro":{"en":"Greek -ikos → Latin -icus → English -ic.","cn":"希腊 -ikos → 拉丁 -icus → 英语 -ic。"},"items":[{"word":"cosmos","structure":"Greek kosmos","meaning":"ordered universe","meaningCN":"宇宙","example":"the whole cosmos","exampleCN":"整个宇宙"},{"word":"cosmic","structure":"kosmos + -ic","meaning":"of the cosmos","meaningCN":"宇宙的；巨大的","example":"cosmic event","exampleCN":"宇宙事件"},{"word":"cosmically","structure":"cosmic + -ly","meaning":"in a cosmic way","meaningCN":"宇宙级地","example":"cosmically distant","exampleCN":"宇宙级地远"},{"word":"cosmology","structure":"kosmos + -logy","meaning":"study of the cosmos","meaningCN":"宇宙学","example":"study cosmology","exampleCN":"学习宇宙学"},{"word":"cosmologist","structure":"kosmos + -logy + -ist","meaning":"one who studies cosmology","meaningCN":"宇宙学家","example":"leading cosmologist","exampleCN":"顶尖宇宙学家"},{"word":"cosmogony","structure":"kosmos + -gony","meaning":"origin of the cosmos","meaningCN":"宇宙起源论","example":"ancient cosmogony","exampleCN":"古代宇宙起源论"},{"word":"cosmogenesis","structure":"kosmos + genesis","meaning":"birth of the cosmos","meaningCN":"宇宙诞生","example":"question cosmogenesis","exampleCN":"探讨宇宙诞生"},{"word":"chaos","structure":"Greek opposite of kosmos","meaning":"unordered matter","meaningCN":"混沌","example":"primordial chaos","exampleCN":"太初混沌"},{"word":"cosmopolitan","structure":"kosmos + polites","meaning":"citizen of the world","meaningCN":"世界主义者","example":"cosmopolitan city","exampleCN":"国际化都市"},{"word":"cosmos flower","structure":"genus name","meaning":"flowering plant","meaningCN":"大波斯菊","example":"cosmos in bloom","exampleCN":"盛开的大波斯菊"}],"latinEntries":[]}},{"word":"galaxy","ipa_uk":"/ˈɡæləksi/","ipa_us":"/ˈɡæləksi/","definition_zh":"星系；银河","definition_en":"a gravitationally bound system of stars, gas, dust and dark matter; the Milky Way","core_image":"哈勃拍的 Andromeda 星系，清晰的螺旋臂上点缀着粉蓝色的恒星形成区","scene":"纪录片里解说员说：Our Milky Way is a galaxy with about 100 billion stars; astronomers now count two trillion galaxies in the observable universe.","sceneCN":"这里指「由引力绑定的恒星系统」（第1个义项）；句意为我们的银河是一个约一千亿颗恒星的星系；天文学家现在在可观测宇宙里数出了两万亿个星系。","pos":[{"tag":"n.","zh":"星系；银河（大写 Galaxy 特指银河系）"}],"collocations":[{"phrase":"the Galaxy","zh":"银河系（大写 G）"},{"phrase":"a galaxy of stars","zh":"一个星系"},{"phrase":"spiral galaxy","zh":"旋涡星系"},{"phrase":"elliptical galaxy","zh":"椭圆星系"},{"phrase":"dwarf galaxy","zh":"矮星系"},{"phrase":"a galaxy of...","zh":"一大群（比喻）"}],"forms":[{"label":"复数","form":"galaxies"},{"label":"形容词","form":"galactic"}],"derivatives":[{"word":"galactic","pos":"adj.","zh":"星系的"},{"word":"galactically","pos":"adv.","zh":"星系级地"},{"word":"galaxy-wide","pos":"adj.","zh":"星系范围的"},{"word":"Milky Way","pos":"n.","zh":"银河（the Galaxy 的别名）"},{"word":"nebula","pos":"n.","zh":"星云（常与 galaxy 混淆）"}],"senses":[{"no":"01","title":"A gravitationally bound system of stars","titleCN":"由引力绑定的恒星系统","definition":"the core scientific sense: stars, gas, dust and dark matter held together by their own gravity, rotating around a central point","definitionCN":"核心科学义项：恒星、气体、尘埃、暗物质靠自身引力绑定，绕中心旋转","example":"The Hubble image shows two galaxies merging together over millions of years.","exampleCN":"哈勃图像展示两个星系在几百万年里合并。","why":"Greek galaxias meant 'milk-white' because of the Milky Way's appearance in the sky.","whyCN":"希腊语 galaxias 意为「乳白色的」，因为银河在天上看起来是乳白色的。"},{"no":"02","title":"The Milky Way (our home galaxy)","titleCN":"我们的家园星系——银河","definition":"when capitalised as 'the Galaxy', refers specifically to the Milky Way, the one we live inside","definitionCN":"大写 the Galaxy 特指银河系，就是我们居住的这个","example":"The Sun is located about 26,000 light-years from the centre of the Galaxy.","exampleCN":"太阳位于距银河中心约 2.6 万光年处。","why":"Originally 'the galaxy' meant the Milky Way; other galaxies were 'island universes' until the 1920s.","whyCN":"最初「the galaxy」就是指银河；其他星系在 1920 年代之前被视为「岛宇宙」。"},{"no":"03","title":"Galaxy types: spiral, elliptical, irregular","titleCN":"星系类型：旋涡、椭圆、不规则","definition":"the Hubble tuning fork: spiral (with arms), elliptical (smooth), irregular (chaotic)","definitionCN":"哈勃音叉：旋涡（有旋臂）、椭圆（平滑）、不规则（混沌）","example":"The Andromeda galaxy is a spiral, while M87 is an elliptical galaxy at the heart of a cluster.","exampleCN":"仙女座星系是旋涡星系，而 M87 是一个星系团中心的椭圆星系。","why":"Hubble's 1920s classification is still the starting point for galaxy studies.","whyCN":"哈勃 1920 年代的分类仍是星系研究的起点。"},{"no":"04","title":"Galaxy clusters and filaments","titleCN":"星系团与纤维结构","definition":"galaxies cluster together to form groups, clusters and filaments that shape the large-scale structure of the universe","definitionCN":"星系聚在一起形成组、团、纤维，塑造宇宙的大尺度结构","example":"The Great Attractor is a mysterious mass pulling our local galaxy cluster toward it.","exampleCN":"大吸引子是一个神秘的大质量体，把我们所在的星系团拉向它。","why":"Galaxy clusters are the largest objects held together by gravity in the universe.","whyCN":"星系团是宇宙里最大的引力绑定物体。"},{"no":"05","title":"Supermassive black holes at galaxy centres","titleCN":"星系中心的超大质量黑洞","definition":"almost every large galaxy has a supermassive black hole at its heart, including our own Milky Way (Sagittarius A*)","definitionCN":"几乎每个大星系中心都有一个超大质量黑洞，包括我们的银河（人马座 A*）","example":"The Event Horizon Telescope imaged the black hole at the centre of the M87 galaxy.","exampleCN":"事件视界望远镜拍到了 M87 星系中心黑洞的照片。","why":"Galaxy formation and black hole growth are tightly linked; each shapes the other.","whyCN":"星系形成和黑洞成长紧密相连；互相塑造。"},{"no":"06","title":"Figurative: a large gathering","titleCN":"比喻：一大群","definition":"a galaxy of people or things — an impressive collection, like stars in a galaxy","definitionCN":"一大群人或事物——令人印象深刻的集合，像星系里的恒星","example":"The gala featured a galaxy of Hollywood stars.","exampleCN":"庆典有一整星系（一大群）好莱坞明星出席。","why":"People use galaxy for impressive gatherings because a galaxy is huge and packed with stars.","whyCN":"人们用 galaxy 来形容一大群令人印象深刻的人，因为星系巨大又挤满恒星。"},{"no":"07","title":"Galactic centre and galactic year","titleCN":"银心与银河年","definition":"galactic centre = the black hole at the Milky Way's heart; galactic year = the time the Sun takes to orbit the centre (~230 million years)","definitionCN":"银心 = 银河系中心的黑洞；银河年 = 太阳绕中心一周的时间（约 2.3 亿年）","example":"The Sun is halfway through its 18th galactic year since forming.","exampleCN":"太阳形成以来刚走完第 18 个银河年的一半。","why":"Using galaxy as the frame of reference gives us cosmic-scale time and distance units.","whyCN":"用星系作参考系给了我们宇宙尺度的时间和距离单位。"},{"no":"08","title":"Galaxy vs nebula vs universe","titleCN":"galaxy vs nebula vs universe","definition":"nebula = cloud of gas and dust inside a galaxy; galaxy = system of stars; universe = everything","definitionCN":"nebula = 星系内的气体尘埃云；galaxy = 恒星系统；universe = 一切","example":"The Orion Nebula is inside our galaxy, not a galaxy itself.","exampleCN":"猎户星云在我们的星系内部，本身不是星系。","why":"Popular media often confuses nebulae, galaxies and universes; astronomy draws clear lines.","whyCN":"大众媒体常把星云、星系、宇宙搞混；天文学画了清楚的界线。"}],"etymology":{"intro":{"en":"galaxy comes from Greek galaxias, short for galaxias kyklos 'milky circle' — the Milky Way.","cn":"galaxy 来自希腊语 galaxias，是 galaxias kyklos「乳白的圆」的缩写——即银河。"},"items":[{"era":"GREEK","en":"galaxias 'milky' + kyklos 'circle' = the milky circle in the sky, the Milky Way.","cn":"galaxias「乳白的」+ kyklos「圆」= 天上那个乳白的圆，即银河。"},{"era":"LATIN","en":"Latin galaxia kept both the 'milky' and 'circle' senses.","cn":"拉丁语 galaxia 保留了「乳白的」和「圆」两种意思。"},{"era":"MIDDLE ENGLISH","en":"Middle English galaxie (14th century) meant only the Milky Way.","cn":"中古英语 galaxie（14 世纪）只指银河。"},{"era":"1920s EXPANSION","en":"Hubble's observations showed that 'spiral nebulae' were actually other galaxies, not part of our own.","cn":"哈勃的观测表明「旋涡星云」其实是别的星系，不是我们的一部分。"},{"era":"20TH C STANDARDISATION","en":"The Hubble telescope and later surveys established modern galaxy classification.","cn":"哈勃望远镜和后来的巡天建立了现代星系分类。"},{"era":"TODAY","en":"Two trillion galaxies are estimated to exist in the observable universe.","cn":"今天估计可观测宇宙里存在两万亿个星系。"}]},"similar":{"note":{"en":"Group one shares the galax- root; group two compares galaxy to nebula, universe and other sky objects.","cn":"第一组共享 galax- 词根；第二组把 galaxy 和 nebula, universe 等天体对比。"},"groups":[{"heading":"SAME ROOT","entries":[{"word":"galactic","ipa":"/ɡəˈlæktɪk/","tag":"adjective","definition":"Of or relating to a galaxy.","definitionCN":"星系的。"},{"word":"galactically","ipa":"/ɡəˈlæktɪkli/","tag":"adverb","definition":"On a galactic scale.","definitionCN":"星系级地。"},{"word":"Galaxy","ipa":"/ˈɡæləksi/","tag":"proper noun","definition":"Capitalised: the Milky Way, our home galaxy.","definitionCN":"大写：我们的家园星系——银河。"},{"word":"galaxy-wide","ipa":"/ˈɡæləksi waɪd/","tag":"compound","definition":"Spanning an entire galaxy.","definitionCN":"跨整个星系的。"}]},{"heading":"RELATED SKY OBJECTS","entries":[{"word":"nebula","ipa":"/ˈnebələ/","tag":"smaller scale","definition":"A cloud of gas and dust inside a galaxy; often misidentified as a galaxy.","definitionCN":"星系内的气体尘埃云；常被误认为星系。"},{"word":"universe","ipa":"/ˈjuːnɪvɜːrs/","tag":"larger scale","definition":"Everything that exists; contains trillions of galaxies.","definitionCN":"一切存在之物；包含几万亿个星系。"},{"word":"star","ipa":"/stɑːr/","tag":"much smaller","definition":"An individual point of light inside a galaxy.","definitionCN":"星系内的单个光点。"},{"word":"solar system","ipa":"/ˈsəʊlər ˈsɪstəm/","tag":"tiny scale","definition":"Our star and its planets; one tiny corner of one galaxy.","definitionCN":"我们的恒星和它的行星；一个星系里的一个小角落。"}]}]},"mnemonics":{"normalIntro":{"en":"Galaxy = milky circle in Greek = Milky Way. Now means one of trillions of such systems.","cn":"Galaxy 希腊语是「乳白的圆」= 银河。现在指几万亿个这种系统之一。"},"normal":[{"en":"Greek galaxias means milky → the Galaxy is our milky band in the sky.","cn":"希腊语 galaxias 意为乳白的 → 天上那条乳白带就是我们的 Galaxy。"},{"en":"A galaxy is a system of stars, gas and dust bound by gravity.","cn":"星系是引力绑定的恒星、气体、尘埃系统。"},{"en":"The Sun orbits the galactic centre every ~230 million years.","cn":"太阳约 2.3 亿年绕银河中心转一圈。"},{"en":"A galaxy of stars = a huge collection of stars.","cn":"A galaxy of stars = 一大堆恒星。"},{"en":"Our Milky Way is one of two trillion galaxies in the observable universe.","cn":"我们的银河是可观测宇宙里两万亿个星系之一。"}],"abstract":[{"en":"A pale band across a dark sky, which is actually hundreds of billions of stars seen edge-on.","cn":"暗天空上的一条白带，其实是几千亿颗恒星侧着看的样子。"},{"en":"A pinwheel of stars spinning slowly around a hidden point of gravity.","cn":"一个围绕隐形引力点慢慢旋转的恒星风车。"},{"en":"Every atom in your body was made inside a star that lives inside a galaxy.","cn":"你身上每个原子都是在一个住在某个星系里的恒星内部制造的。"}]},"examples":[{"en":"The Andromeda galaxy will collide with our Milky Way in about 4 billion years.","cn":"仙女座星系将在约 40 亿年后与我们的银河相撞。"},{"en":"A galaxy of A-list celebrities arrived on the red carpet for the premiere.","cn":"一整星系（一大群）一线明星走上首映礼的红毯。"},{"en":"Dwarf galaxies are the smallest known galaxies, some with only a few thousand stars.","cn":"矮星系是已知最小的星系，有些只有几千颗恒星。"}],"dict_mnemonic":{"note":"词源记忆","text":"希腊语 galaxias（乳白的）→ 乳白的圆 → 银河 → 星系","word":"galaxy"},"root":"galaxias（希腊语，乳白的）→ galaxia → galaxy。","sensesIntro":{"en":"Eight senses map galaxy from its core scientific definition, through our Milky Way, galaxy types, clusters, black holes, figurative gatherings, cosmic timescales and terminological distinctions.","cn":"八个义项把 galaxy 从核心科学定义，经我们的银河、星系类型、星系团、黑洞、比喻人群、宇宙时间尺度，到术语区分。"},"semanticMap":{"core":{"en":"CORE IMAGE: the Andromeda galaxy, a pinwheel of blue young stars and red old stars.","cn":"核心意象：仙女座星系，蓝色年轻恒星和红色年老恒星组成的风车。"},"chain":["SYSTEM OF STARS","OUR HOME GALAXY","TYPES","CLUSTERS","BLACK HOLES","FIGURATIVE / TERMINOLOGY"],"branches":[{"senses":"01 · 02","en":"DEFINITION","cn":"定义"},{"senses":"03","en":"CLASSIFICATION","cn":"分类"},{"senses":"04","en":"LARGE-SCALE STRUCTURE","cn":"大尺度结构"},{"senses":"05","en":"BLACK HOLES","cn":"黑洞"},{"senses":"06 · 07 · 08","en":"FIGURATIVE / TIMESCALES / TERMINOLOGY","cn":"比喻 / 时间尺度 / 术语"}]},"affixes":{"intro":{"en":"galaxy comes from Greek galaxias 'milky'; the adjective galactic is from Latin galacticus.","cn":"galaxy 来自希腊语 galaxias「乳白的」；形容词 galactic 来自拉丁语 galacticus。"},"latinIntro":{"en":"Greek galaxias → Latin galaxia → English galaxy; galactic is Latin.","cn":"希腊 galaxias → 拉丁 galaxia → 英语 galaxy；galactic 是拉丁语。"},"items":[{"word":"galaxias","structure":"Greek root","meaning":"milky","meaningCN":"乳白的","example":"galaxias kyklos","exampleCN":"乳白的圆"},{"word":"galaxy","structure":"galaxia → English","meaning":"gravitational system of stars","meaningCN":"星系","example":"spiral galaxy","exampleCN":"旋涡星系"},{"word":"Galaxy","structure":"capitalised","meaning":"the Milky Way","meaningCN":"银河系","example":"centre of the Galaxy","exampleCN":"银河系中心"},{"word":"galactic","structure":"Latin galacticus","meaning":"relating to a galaxy","meaningCN":"星系的","example":"galactic centre","exampleCN":"星系中心"},{"word":"galactically","structure":"galactic + -ly","meaning":"on a galactic scale","meaningCN":"星系级地","example":"galactically distant","exampleCN":"星系级地远"},{"word":"galaxy cluster","structure":"compound","meaning":"group of galaxies","meaningCN":"星系团","example":"Virgo cluster","exampleCN":"室女座星系团"},{"word":"galaxy filament","structure":"compound","meaning":"thread-like string of galaxies","meaningCN":"星系纤维","example":"largest galaxy filament","exampleCN":"最大星系纤维"},{"word":"nebula","structure":"Latin nebula","meaning":"gas cloud inside galaxy","meaningCN":"星云","example":"Orion nebula","exampleCN":"猎户星云"},{"word":"universe","structure":"un- + vertere","meaning":"all that exists","meaningCN":"宇宙","example":"the whole universe","exampleCN":"整个宇宙"},{"word":"cosmos","structure":"Greek kosmos","meaning":"ordered universe","meaningCN":"有序宇宙","example":"the ordered cosmos","exampleCN":"有序的宇宙"}],"latinEntries":[]}}]);
